INSERT INTO `mawadi3` (`mawdi_id`,`mawdi_number`,`surah_id`,`reference_text`,`start_page`,`end_page`,`plain_text`,`html_text`,`normalized_text`,`is_closed`) VALUES (1,1,1,'النمل : ٣٠-٣١',1,1,'
﴿ بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ ۝١ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ ﴾ [الفاتحة : ١-٢]
﴿ إِنَّهُۥ مِن سُلَيْمَٰنَ وَإِنَّهُۥ بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ ۝٣٠ أَلَّا تَعْلُواْ عَلَيَّ وَأْتُونِي مُسْلِمِينَ ﴾','
﴿ <span style="color:red">بِسْمِ</span> اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ ۝١ <span style="color:red">الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ</span> ﴾ [الفاتحة : ١-٢]
﴿ إِنَّهُۥ مِن سُلَيْمَٰنَ وَإِنَّهُۥ <span style="color:red">بِسْمِ</span> اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ ۝٣٠ <span style="color:red">أَلَّا تَعْلُواْ عَلَيَّ وَأْتُونِي مُسْلِمِينَ</span> ﴾','بسم الله الرحمن الرحيم ۝١ الحمد لله رب العالمين الفاتحه ١٢ انهۥ من سليمن وانهۥ بسم الله الرحمن الرحيم ۝٣٠ الا تعلوا علي واتوني مسلمين',1);
INSERT INTO `mawadi3` (`mawdi_id`,`mawdi_number`,`surah_id`,`reference_text`,`start_page`,`end_page`,`plain_text`,`html_text`,`normalized_text`,`is_closed`) VALUES (2,2,1,'فاطر : ١',1,1,'
﴿ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ ﴾ [الفاتحة : ٢]
﴿ الْحَمْدُ لِلَّهِ الَّذِي خَلَقَ السَّمَٰوَٰتِ وَالأَرْضَ وَجَعَلَ الظُّلُمَٰتِ وَالنُّورَ ثُمَّ الَّذِينَ كَفَرُواْ بِرَبِّهِمْ يَعْدِلُونَ ﴾ [الأنعام : ١]
﴿ الْحَمْدُ لِلَّهِ الَّذِي أَنزَلَ عَلَىٰ عَبْدِهِ الْكِتَٰبَ وَلَمْ يَجْعَل لَّهُۥ عِوَجَا ﴾ [الكهف : ١]
﴿ الْحَمْدُ لِلَّهِ الَّذِي لَهُۥ مَا فِي السَّمَٰوَٰتِ وَمَا فِي الأَرْضِ وَلَهُ الْحَمْدُ فِي الآخِرَةِ وَهُوَ الْحَكِيمُ الْخَبِيرُ ﴾ [سبأ : ١]
﴿ الْحَمْدُ لِلَّهِ فَاطِرِ السَّمَٰوَٰتِ وَالأَرْضِ جَاعِلِ الْمَلَٰئِكَةِ رُسُلاً أُولِي أَجْنِحَةٍ مَّثْنَىٰ وَثُلَٰثَ وَرُبَٰعَ يَزِيدُ فِي الْخَلْقِ مَا يَشَاءُ إِنَّ اللَّهَ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ ﴾ [فاطر : ١]
السور التي بدأت بـ ﴿ الْحَمْدُ لِلَّهِ ﴾ بعد البسملة خمس سور.','
﴿ <span style="color:red"><span style="color:red">الْحَمْدُ لِلَّهِ</span> رَبِّ الْعَالَمِينَ</span> ﴾ [الفاتحة : ٢]
﴿ <span style="color:red">الْحَمْدُ لِلَّهِ</span> الَّذِي خَلَقَ السَّمَٰوَٰتِ وَالأَرْضَ وَجَعَلَ الظُّلُمَٰتِ وَالنُّورَ <span style="color:red">ثُمَّ الَّذِينَ كَفَرُواْ بِرَبِّهِمْ يَعْدِلُونَ</span> ﴾ [الأنعام : ١]
﴿ <span style="color:red">الْحَمْدُ لِلَّهِ</span> الَّذِي أَنزَلَ عَلَىٰ عَبْدِهِ الْكِتَٰبَ وَلَمْ يَجْعَل لَّهُۥ <span style="color:red">عِوَجَا</span> ﴾ [الكهف : ١]
﴿ <span style="color:red">الْحَمْدُ لِلَّهِ</span> الَّذِي لَهُۥ مَا فِي السَّمَٰوَٰتِ وَمَا فِي الأَرْضِ وَلَهُ <span style="color:red">الْحَمْدُ فِي الآخِرَةِ وَهُوَ الْحَكِيمُ الْخَبِيرُ</span> ﴾ [سبأ : ١]
﴿ <span style="color:red">الْحَمْدُ لِلَّهِ</span> فَاطِرِ السَّمَٰوَٰتِ وَالأَرْضِ جَاعِلِ الْمَلَٰئِكَةِ رُسُلاً أُولِي أَجْنِحَةٍ مَّثْنَىٰ وَثُلَٰثَ وَرُبَٰعَ يَزِيدُ فِي الْخَلْقِ مَا يَشَاءُ إِنَّ اللَّهَ عَلَىٰ كُلِّ شَيْءٍ <span style="color:red">قَدِيرٌ</span> ﴾ [فاطر : ١]
السور التي بدأت بـ ﴿ <span style="color:red">الْحَمْدُ لِلَّهِ</span> ﴾ بعد البسملة خمس سور.','الحمد لله رب العالمين الفاتحه ٢ الحمد لله الذي خلق السموت والارض وجعل الظلمت والنور ثم الذين كفروا بربهم يعدلون الانعام ١ الحمد لله الذي انزل علي عبده الكتب ولم يجعل لهۥ عوجا الكهف ١ الحمد لله الذي لهۥ ما في السموت وما في الارض وله الحمد في الاخره وهو الحكيم الخبير سبا ١ الحمد لله فاطر السموت والارض جاعل الملئكه رسلا اولي اجنحه مثني وثلث وربع يزيد في الخلق ما يشاء ان الله علي كل شيء قدير فاطر ١ السور التي بدات ب الحمد لله بعد البسمله خمس سور',1);
INSERT INTO `mawadi3` (`mawdi_id`,`mawdi_number`,`surah_id`,`reference_text`,`start_page`,`end_page`,`plain_text`,`html_text`,`normalized_text`,`is_closed`) VALUES (3,2,1,'غافر : ٦٥-٦٦',1,1,'
﴿ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ ۝٢ الرَّحْمَٰنِ الرَّحِيمِ ﴾ [الفاتحة : ٢-٣]
﴿ فَقُطِعَ دَابِرُ الْقَوْمِ الَّذِينَ ظَلَمُواْ وَالْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ ۝٤٥ قُلْ أَرَأَيْتُمْ إِنْ أَخَذَ اللَّهُ سَمْعَكُمْ وَأَبْصَٰرَكُمْ وَخَتَمَ عَلَىٰ قُلُوبِكُم مَّنْ إِلَٰهٌ غَيْرُ اللَّهِ يَأْتِيكُم بِهِ انظُرْ كَيْفَ نُصَرِّفُ الآيَٰتِ ثُمَّ هُمْ يَصْدِفُونَ ﴾ [الأنعام : ٤٥-٤٦]
﴿ دَعْوَٰهُمْ فِيهَا سُبْحَٰنَكَ اللَّهُمَّ وَتَحِيَّتُهُمْ فِيهَا سَلَٰمٌ وَآخِرُ دَعْوَٰهُمْ أَنِ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ ۝١٠ وَلَوْ يُعَجِّلُ اللَّهُ لِلنَّاسِ الشَّرَّ اسْتِعْجَالَهُم بِالْخَيْرِ لَقُضِيَ إِلَيْهِمْ أَجَلُهُمْ فَنَذَرُ الَّذِينَ لاَ يَرْجُونَ لِقَاءَنَا فِي طُغْيَٰنِهِمْ يَعْمَهُونَ ﴾ [يونس : ١٠-١١]
﴿ وَالْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ ﴾ [آخر آية بالصافات : ١٨٢]
﴿ وَتَرَى الْمَلَٰئِكَةَ حَافِّينَ مِنْ حَوْلِ الْعَرْشِ يُسَبِّحُونَ بِحَمْدِ رَبِّهِمْ وَقُضِيَ بَيْنَهُم بِالْحَقِّ وَقِيلَ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ ﴾ [آخر آية بالزمر : ٧٥]
﴿ هُوَ الْحَيُّ لاَ إِلَٰهَ إِلاَّ هُوَ فَادْعُوهُ مُخْلِصِينَ لَهُ الدِّينَ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ ۝٦٥ قُلْ إِنِّي نُهِيتُ أَنْ أَعْبُدَ الَّذِينَ تَدْعُونَ مِن دُونِ اللَّهِ لَمَّا جَاءَنِيَ الْبَيِّنَٰتُ مِن رَّبِّي وَأُمِرْتُ أَنْ أُسْلِمَ لِرَبِّ الْعَالَمِينَ ﴾ [غافر : ٦٥-٦٦]
﴿ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ ﴾ تكررت ست مرات.','
﴿ <span style="color:red">الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ</span> ۝٢ <span style="color:red">الرَّحْمَٰنِ الرَّحِيمِ</span> ﴾ [الفاتحة : ٢-٣]
﴿ فَقُطِعَ دَابِرُ الْقَوْمِ الَّذِينَ ظَلَمُواْ وَ<span style="color:red">الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ</span> ۝٤٥ <span style="color:red">قُلْ أَرَأَيْتُمْ إِنْ أَخَذَ اللَّهُ سَمْعَكُمْ وَأَبْصَٰرَكُمْ وَخَتَمَ عَلَىٰ قُلُوبِكُم</span> مَّنْ إِلَٰهٌ غَيْرُ اللَّهِ يَأْتِيكُم بِهِ انظُرْ كَيْفَ نُصَرِّفُ الآيَٰتِ <span style="color:red">ثُمَّ هُمْ يَصْدِفُونَ</span> ﴾ [الأنعام : ٤٥-٤٦]
﴿ دَعْوَٰهُمْ فِيهَا سُبْحَٰنَكَ اللَّهُمَّ وَتَحِيَّتُهُمْ فِيهَا سَلَٰمٌ وَآخِرُ دَعْوَٰهُمْ أَنِ <span style="color:red">الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ</span> ۝١٠ <span style="color:red">وَلَوْ يُعَجِّلُ اللَّهُ لِلنَّاسِ الشَّرَّ اسْتِعْجَالَهُم بِالْخَيْرِ لَقُضِيَ إِلَيْهِمْ أَجَلُهُمْ فَنَذَرُ الَّذِينَ لاَ يَرْجُونَ لِقَاءَنَا فِي طُغْيَٰنِهِمْ يَعْمَهُونَ</span> ﴾ [يونس : ١٠-١١]
﴿ وَ<span style="color:red">الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ</span> ﴾ [آخر آية بالصافات : ١٨٢]
﴿ وَتَرَى الْمَلَٰئِكَةَ حَافِّينَ مِنْ حَوْلِ الْعَرْشِ يُسَبِّحُونَ بِحَمْدِ رَبِّهِمْ وَقُضِيَ بَيْنَهُم بِالْحَقِّ وَقِيلَ <span style="color:red">الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ</span> ﴾ [آخر آية بالزمر : ٧٥]
﴿ <span style="color:red">هُوَ الْحَيُّ</span> لاَ إِلَٰهَ إِلاَّ هُوَ فَادْعُوهُ مُخْلِصِينَ لَهُ الدِّينَ <span style="color:red">الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ</span> ۝٦٥ <span style="color:red">قُلْ إِنِّي نُهِيتُ أَنْ أَعْبُدَ الَّذِينَ تَدْعُونَ مِن دُونِ اللَّهِ لَمَّا جَاءَنِيَ الْبَيِّنَٰتُ مِن رَّبِّي وَأُمِرْتُ أَنْ أُسْلِمَ لِرَبِّ الْعَالَمِينَ</span> ﴾ [غافر : ٦٥-٦٦]
﴿ <span style="color:red">الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ</span> ﴾ تكررت ست مرات.','الحمد لله رب العالمين ۝٢ الرحمن الرحيم الفاتحه ٢٣ فقطع دابر القوم الذين ظلموا والحمد لله رب العالمين ۝٤٥ قل ارايتم ان اخذ الله سمعكم وابصركم وختم علي قلوبكم من اله غير الله ياتيكم به انظر كيف نصرف الايت ثم هم يصدفون الانعام ٤٥٤٦ دعوهم فيها سبحنك اللهم وتحيتهم فيها سلم واخر دعوهم ان الحمد لله رب العالمين ۝١٠ ولو يعجل الله للناس الشر استعجالهم بالخير لقضي اليهم اجلهم فنذر الذين لا يرجون لقاءنا في طغينهم يعمهون يونس ١٠١١ والحمد لله رب العالمين اخر ايه بالصافات ١٨٢ وتري الملئكه حافين من حول العرش يسبحون بحمد ربهم وقضي بينهم بالحق وقيل الحمد لله رب العالمين اخر ايه بالزمر ٧٥ هو الحي لا اله الا هو فادعوه مخلصين له الدين الحمد لله رب العالمين ۝٦٥ قل اني نهيت ان اعبد الذين تدعون من دون الله لما جاءني البينت من ربي وامرت ان اسلم لرب العالمين غافر ٦٥٦٦ الحمد لله رب العالمين تكررت ست مرات',1);
INSERT INTO `mawadi3` (`mawdi_id`,`mawdi_number`,`surah_id`,`reference_text`,`start_page`,`end_page`,`plain_text`,`html_text`,`normalized_text`,`is_closed`) VALUES (4,1,2,NULL,2,2,'
﴿ الم ﴿١﴾ ذَٰلِكَ الْكِتَٰبُ لَا رَيْبَ فِيهِ هُدًى لِّلْمُتَّقِينَ ﴿٢﴾ ﴾ [البقرة : ١ - ٢]
﴿ الم ﴿١﴾ اللَّهُ لَا إِلَٰهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ ﴿٢﴾ ﴾ [آل عمران : ١ - ٢]
﴿ الم ﴿١﴾ أَحَسِبَ النَّاسُ أَن يُتْرَكُوا أَن يَقُولُوا آمَنَّا وَهُمْ لَا يُفْتَنُونَ ﴿٢﴾ ﴾ [العنكبوت : ١ - ٢]
﴿ الم ﴿١﴾ غُلِبَتِ الرُّومُ ﴿٢﴾ ﴾ [الروم : ١ - ٢]
﴿ الم ﴿١﴾ تِلْكَ آيَاتُ الْكِتَابِ الْحَكِيمِ ﴿٢﴾ ﴾ [لقمان : ١ - ٢]
﴿ الم ﴿١﴾ تَنزِيلُ الْكِتَابِ لَا رَيْبَ فِيهِ مِن رَّبِّ الْعَالَمِينَ ﴿٢﴾ ﴾ [السجدة : ١ - ٢]
ست سور بدأت بقوله تعالى: ﴿ الم ﴾، وانتبه إلى الآية التي تليها.','
﴿ <span style="color:red"><span style="color:red"><span style="color:red"><span style="color:red"><span style="color:red"><span style="color:red"><span style="color:red">الم</span></span></span></span></span></span></span> ﴿١﴾ <span style="color:red">ذَٰلِكَ الْكِتَٰبُ لَا رَيْبَ فِيهِ هُدًى لِّلْمُتَّقِينَ</span> ﴿٢﴾ ﴾ [البقرة : ١ - ٢]
﴿ <span style="color:red"><span style="color:red"><span style="color:red"><span style="color:red"><span style="color:red"><span style="color:red"><span style="color:red">الم</span></span></span></span></span></span></span> ﴿١﴾ <span style="color:red">اللَّهُ لَا إِلَٰهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ</span> ﴿٢﴾ ﴾ [آل عمران : ١ - ٢]
﴿ <span style="color:red"><span style="color:red"><span style="color:red"><span style="color:red"><span style="color:red"><span style="color:red"><span style="color:red">الم</span></span></span></span></span></span></span> ﴿١﴾ <span style="color:red">أَحَسِبَ النَّاسُ أَن يُتْرَكُوا أَن يَقُولُوا آمَنَّا وَهُمْ لَا يُفْتَنُونَ</span> ﴿٢﴾ ﴾ [العنكبوت : ١ - ٢]
﴿ <span style="color:red"><span style="color:red"><span style="color:red"><span style="color:red"><span style="color:red"><span style="color:red"><span style="color:red">الم</span></span></span></span></span></span></span> ﴿١﴾ <span style="color:red">غُلِبَتِ الرُّومُ</span> ﴿٢﴾ ﴾ [الروم : ١ - ٢]
﴿ <span style="color:red"><span style="color:red"><span style="color:red"><span style="color:red"><span style="color:red"><span style="color:red"><span style="color:red">الم</span></span></span></span></span></span></span> ﴿١﴾ <span style="color:red">تِلْكَ آيَاتُ الْكِتَابِ الْحَكِيمِ</span> ﴿٢﴾ ﴾ [لقمان : ١ - ٢]
﴿ <span style="color:red"><span style="color:red"><span style="color:red"><span style="color:red"><span style="color:red"><span style="color:red"><span style="color:red">الم</span></span></span></span></span></span></span> ﴿١﴾ <span style="color:red">تَنزِيلُ الْكِتَابِ لَا رَيْبَ فِيهِ مِن رَّبِّ الْعَالَمِينَ</span> ﴿٢﴾ ﴾ [السجدة : ١ - ٢]
ست سور بدأت بقوله تعالى: ﴿ <span style="color:red"><span style="color:red"><span style="color:red"><span style="color:red"><span style="color:red"><span style="color:red"><span style="color:red">الم</span></span></span></span></span></span></span> ﴾، وانتبه إلى الآية التي تليها.','الم ١ ذلك الكتب لا ريب فيه هدي للمتقين ٢ البقره ١ ٢ الم ١ الله لا اله الا هو الحي القيوم ٢ ال عمران ١ ٢ الم ١ احسب الناس ان يتركوا ان يقولوا امنا وهم لا يفتنون ٢ العنكبوت ١ ٢ الم ١ غلبت الروم ٢ الروم ١ ٢ الم ١ تلك ايات الكتاب الحكيم ٢ لقمان ١ ٢ الم ١ تنزيل الكتاب لا ريب فيه من رب العالمين ٢ السجده ١ ٢ ست سور بدات بقوله تعالي الم ، وانتبه الي الايه التي تليها',1);
INSERT INTO `mawadi3` (`mawdi_id`,`mawdi_number`,`surah_id`,`reference_text`,`start_page`,`end_page`,`plain_text`,`html_text`,`normalized_text`,`is_closed`) VALUES (5,3,2,NULL,2,2,'
﴿ الَّذِينَ يُؤْمِنُونَ بِالْغَيْبِ وَيُقِيمُونَ الصَّلَوٰةَ وَمِمَّا رَزَقْنَاهُمْ يُنفِقُونَ ﴿٣﴾ وَالَّذِينَ يُؤْمِنُونَ بِمَا أُنزِلَ إِلَيْكَ ... ﴾ [البقرة : ٣ - ٤]
﴿ الَّذِينَ يُقِيمُونَ الصَّلَوٰةَ وَمِمَّا رَزَقْنَاهُمْ يُنفِقُونَ ﴿٣﴾ أُولَٰئِكَ هُمُ الْمُؤْمِنُونَ حَقًّا ... ﴾ [الأنفال : ٣ - ٤]
﴿ ... وَالصَّابِرِينَ عَلَىٰ مَا أَصَابَهُمْ وَالْمُقِيمِي الصَّلَوٰةِ وَمِمَّا رَزَقْنَاهُمْ يُنفِقُونَ ﴿٣٥﴾ وَالْبُدْنَ جَعَلْنَاهَا لَكُم ... ﴾ [الحج : ٣٥ - ٣٦]
ثلاث آيات ختمت بقوله تعالى: ﴿ وَمِمَّا رَزَقْنَاهُمْ يُنفِقُونَ ﴾ بعد ذكر إقامة الصلاة.','
﴿ <span style="color:red">الَّذِينَ يُؤْمِنُونَ بِالْغَيْبِ وَيُقِيمُونَ الصَّلَوٰةَ <span style="color:red">وَمِمَّا رَزَقْنَاهُمْ يُنفِقُونَ</span></span> ﴿٣﴾ <span style="color:red">وَالَّذِينَ يُؤْمِنُونَ بِمَا أُنزِلَ إِلَيْكَ</span> ... ﴾ [البقرة : ٣ - ٤]
﴿ الَّذِينَ يُقِيمُونَ الصَّلَوٰةَ <span style="color:red">وَمِمَّا رَزَقْنَاهُمْ يُنفِقُونَ</span> ﴿٣﴾ <span style="color:red">أُولَٰئِكَ هُمُ الْمُؤْمِنُونَ حَقًّا</span> ... ﴾ [الأنفال : ٣ - ٤]
﴿ ... وَالصَّابِرِينَ عَلَىٰ مَا أَصَابَهُمْ وَالْمُقِيمِي الصَّلَوٰةِ <span style="color:red">وَمِمَّا رَزَقْنَاهُمْ يُنفِقُونَ</span> ﴿٣٥﴾ <span style="color:red">وَالْبُدْنَ جَعَلْنَاهَا لَكُم</span> ... ﴾ [الحج : ٣٥ - ٣٦]
ثلاث آيات ختمت بقوله تعالى: ﴿ <span style="color:red">وَمِمَّا رَزَقْنَاهُمْ يُنفِقُونَ</span> ﴾ بعد ذكر إقامة الصلاة.','الذين يؤمنون بالغيب ويقيمون الصلوه ومما رزقناهم ينفقون ٣ والذين يؤمنون بما انزل اليك البقره ٣ ٤ الذين يقيمون الصلوه ومما رزقناهم ينفقون ٣ اولئك هم المؤمنون حقا الانفال ٣ ٤ والصابرين علي ما اصابهم والمقيمي الصلوه ومما رزقناهم ينفقون ٣٥ والبدن جعلناها لكم الحج ٣٥ ٣٦ ثلاث ايات ختمت بقوله تعالي ومما رزقناهم ينفقون بعد ذكر اقامه الصلاه',1);
INSERT INTO `mawadi3` (`mawdi_id`,`mawdi_number`,`surah_id`,`reference_text`,`start_page`,`end_page`,`plain_text`,`html_text`,`normalized_text`,`is_closed`) VALUES (6,4,2,NULL,2,2,'
﴿ وَالَّذِينَ يُؤْمِنُونَ بِمَا أُنزِلَ إِلَيْكَ وَمَا أُنزِلَ مِن قَبْلِكَ وَبِالْآخِرَةِ هُمْ يُوقِنُونَ ﴿٤﴾ أُولَٰئِكَ عَلَىٰ هُدًى ... ﴾ [البقرة : ٤ - ٥]
﴿ الَّذِينَ يُقِيمُونَ الصَّلَوٰةَ وَيُؤْتُونَ الزَّكَوٰةَ وَهُم بِالْآخِرَةِ هُمْ يُوقِنُونَ ﴿٣﴾ إِنَّ الَّذِينَ لَا يُؤْمِنُونَ بِالْآخِرَةِ ... ﴾ [النمل : ٣ - ٤]
﴿ الَّذِينَ يُقِيمُونَ الصَّلَوٰةَ وَيُؤْتُونَ الزَّكَوٰةَ وَهُم بِالْآخِرَةِ هُمْ يُوقِنُونَ ﴿٤﴾ أُولَٰئِكَ عَلَىٰ هُدًى مِّن رَّبِّهِمْ ... ﴾ [لقمان : ٤ - ٥]
ملحوظة: آية البقرة الوحيدة "وبالآخرة هم يوقنون" وباقي المواضع "وهم بالآخرة هم يوقنون".','
﴿ وَالَّذِينَ يُؤْمِنُونَ بِمَا أُنزِلَ إِلَيْكَ وَمَا أُنزِلَ مِن قَبْلِكَ وَبِالْآخِرَةِ هُمْ يُوقِنُونَ ﴿٤﴾ <span style="color:red">أُولَٰئِكَ عَلَىٰ هُدًى</span> ... ﴾ [البقرة : ٤ - ٥]
﴿ الَّذِينَ يُقِيمُونَ الصَّلَوٰةَ وَيُؤْتُونَ الزَّكَوٰةَ <span style="color:red"><span style="color:red">وَهُم بِالْآخِرَةِ</span></span> هُمْ يُوقِنُونَ ﴿٣﴾ <span style="color:red">إِنَّ الَّذِينَ لَا يُؤْمِنُونَ بِالْآخِرَةِ</span> ... ﴾ [النمل : ٣ - ٤]
﴿ الَّذِينَ يُقِيمُونَ الصَّلَوٰةَ وَيُؤْتُونَ الزَّكَوٰةَ <span style="color:red"><span style="color:red">وَهُم بِالْآخِرَةِ</span></span> هُمْ يُوقِنُونَ ﴿٤﴾ <span style="color:red">أُولَٰئِكَ عَلَىٰ هُدًى</span> مِّن رَّبِّهِمْ ... ﴾ [لقمان : ٤ - ٥]
ملحوظة: آية البقرة الوحيدة "<span style="color:red">وبالآخرة هم يوقنون</span>" وباقي المواضع "<span style="color:red">وهم بالآخرة هم يوقنون</span>".','والذين يؤمنون بما انزل اليك وما انزل من قبلك وبالاخره هم يوقنون ٤ اولئك علي هدي البقره ٤ ٥ الذين يقيمون الصلوه ويؤتون الزكوه وهم بالاخره هم يوقنون ٣ ان الذين لا يؤمنون بالاخره النمل ٣ ٤ الذين يقيمون الصلوه ويؤتون الزكوه وهم بالاخره هم يوقنون ٤ اولئك علي هدي من ربهم لقمان ٤ ٥ ملحوظه ايه البقره الوحيده وبالاخره هم يوقنون وباقي المواضع وهم بالاخره هم يوقنون',1);
INSERT INTO `mawadi3` (`mawdi_id`,`mawdi_number`,`surah_id`,`reference_text`,`start_page`,`end_page`,`plain_text`,`html_text`,`normalized_text`,`is_closed`) VALUES (7,4,2,NULL,2,2,'
﴿ وَالَّذِينَ يُؤْمِنُونَ بِمَا أُنزِلَ إِلَيْكَ وَمَا أُنزِلَ مِن قَبْلِكَ وَبِالْآخِرَةِ هُمْ يُوقِنُونَ ﴾ [البقرة : ٤]
﴿ لَّٰكِنِ الرَّاسِخُونَ فِي الْعِلْمِ مِنْهُمْ وَالْمُؤْمِنُونَ يُؤْمِنُونَ بِمَا أُنزِلَ إِلَيْكَ وَمَا أُنزِلَ مِن قَبْلِكَ وَالْمُقِيمِينَ الصَّلَوٰةَ ... ﴾ [النساء : ١٦٢]
اربط بين راء "وبالآخرة" وراء البقرة، أي أن السورة التي جاء في اسمها حرف الراء -البقرة- هي التي وقعت بها "وبالآخرة" التي جاء بها حرف الراء كذلك.','
﴿ وَالَّذِينَ يُؤْمِنُونَ بِمَا أُنزِلَ إِلَيْكَ وَمَا أُنزِلَ مِن قَبْلِكَ وَبِالْآخِرَةِ <span style="color:red">هُمْ يُوقِنُونَ</span> ﴾ [<span style="color:red"><span style="color:red">البقرة</span></span> : ٤]
﴿ لَّٰكِنِ الرَّاسِخُونَ فِي الْعِلْمِ مِنْهُمْ وَالْمُؤْمِنُونَ يُؤْمِنُونَ بِمَا أُنزِلَ إِلَيْكَ وَمَا أُنزِلَ مِن قَبْلِكَ <span style="color:red">وَالْمُقِيمِينَ الصَّلَوٰةَ</span> ... ﴾ [النساء : ١٦٢]
اربط بين راء "<span style="color:red"><span style="color:red">وبالآخرة</span></span>" وراء <span style="color:red"><span style="color:red">البقرة</span></span>، أي أن السورة التي جاء في اسمها حرف الراء -<span style="color:red"><span style="color:red">البقرة</span></span>- هي التي وقعت بها "<span style="color:red"><span style="color:red">وبالآخرة</span></span>" التي جاء بها حرف الراء كذلك.','والذين يؤمنون بما انزل اليك وما انزل من قبلك وبالاخره هم يوقنون البقره ٤ لكن الراسخون في العلم منهم والمؤمنون يؤمنون بما انزل اليك وما انزل من قبلك والمقيمين الصلوه النساء ١٦٢ اربط بين راء وبالاخره وراء البقره، اي ان السوره التي جاء في اسمها حرف الراء البقره هي التي وقعت بها وبالاخره التي جاء بها حرف الراء كذلك',1);
INSERT INTO `mawadi3` (`mawdi_id`,`mawdi_number`,`surah_id`,`reference_text`,`start_page`,`end_page`,`plain_text`,`html_text`,`normalized_text`,`is_closed`) VALUES (8,5,2,NULL,2,2,'
﴿ أُولَٰئِكَ عَلَىٰ هُدًى مِّن رَّبِّهِمْ وَأُولَٰئِكَ هُمُ الْمُفْلِحُونَ ﴿٥﴾ إِنَّ الَّذِينَ كَفَرُوا سَوَاءٌ عَلَيْهِمُ ... ﴾ [البقرة : ٥ - ٦]
﴿ أُولَٰئِكَ عَلَىٰ هُدًى مِّن رَّبِّهِمْ وَأُولَٰئِكَ هُمُ الْمُفْلِحُونَ ﴿٥﴾ وَمِنَ النَّاسِ مَن يَشْتَرِي لَهْوَ الْحَدِيثِ ... ﴾ [لقمان : ٥ - ٦]
اربط بين راء "كفروا" وراء البقرة، أي أن السورة التي جاء في اسمها حرف الراء -البقرة- هي التي وقعت بها "كفروا" التي جاء بها حرف الراء كذلك، وأيضًا اربط بين ميم "ومن" وميم لقمان، أي أن السورة التي جاء في اسمها حرف الميم -لقمان- هي التي وقعت بها "ومن" التي جاء بها حرف الميم كذلك.','
﴿ أُولَٰئِكَ عَلَىٰ هُدًى مِّن رَّبِّهِمْ وَأُولَٰئِكَ هُمُ الْمُفْلِحُونَ ﴿٥﴾ <span style="color:red">إِنَّ الَّذِينَ كَفَرُوا سَوَاءٌ عَلَيْهِمُ</span> ... ﴾ [<span style="color:red">البقرة</span> : ٥ - ٦]
﴿ أُولَٰئِكَ عَلَىٰ هُدًى مِّن رَّبِّهِمْ وَأُولَٰئِكَ هُمُ الْمُفْلِحُونَ ﴿٥﴾ <span style="color:red">وَمِنَ النَّاسِ مَن يَشْتَرِي لَهْوَ الْحَدِيثِ</span> ... ﴾ [<span style="color:red"><span style="color:red">لقمان</span></span> : ٥ - ٦]
اربط بين راء "<span style="color:red"><span style="color:red">كفروا</span></span>" وراء <span style="color:red">البقرة</span>، أي أن السورة التي جاء في اسمها حرف الراء -<span style="color:red">البقرة</span>- هي التي وقعت بها "<span style="color:red"><span style="color:red">كفروا</span></span>" التي جاء بها حرف الراء كذلك، وأيضًا اربط بين ميم "<span style="color:red"><span style="color:red">ومن</span></span>" وميم <span style="color:red"><span style="color:red">لقمان</span></span>، أي أن السورة التي جاء في اسمها حرف الميم -<span style="color:red"><span style="color:red">لقمان</span></span>- هي التي وقعت بها "<span style="color:red"><span style="color:red">ومن</span></span>" التي جاء بها حرف الميم كذلك.','اولئك علي هدي من ربهم واولئك هم المفلحون ٥ ان الذين كفروا سواء عليهم البقره ٥ ٦ اولئك علي هدي من ربهم واولئك هم المفلحون ٥ ومن الناس من يشتري لهو الحديث لقمان ٥ ٦ اربط بين راء كفروا وراء البقره، اي ان السوره التي جاء في اسمها حرف الراء البقره هي التي وقعت بها كفروا التي جاء بها حرف الراء كذلك، وايضا اربط بين ميم ومن وميم لقمان، اي ان السوره التي جاء في اسمها حرف الميم لقمان هي التي وقعت بها ومن التي جاء بها حرف الميم كذلك',1);
INSERT INTO `mawadi3` (`mawdi_id`,`mawdi_number`,`surah_id`,`reference_text`,`start_page`,`end_page`,`plain_text`,`html_text`,`normalized_text`,`is_closed`) VALUES (9,6,2,'[يس : ١٠-١١]',3,3,'
﴿ إِنَّ الَّذِينَ كَفَرُوا سَوَاءٌ عَلَيْهِمْ أَأَنذَرْتَهُمْ أَمْ لَمْ تُنذِرْهُمْ لَا يُؤْمِنُونَ ﴿٦﴾ خَتَمَ اللَّهُ عَلَىٰ قُلُوبِهِمْ...﴾ [البقرة : ٦-٧]
﴿ وَسَوَاءٌ عَلَيْهِمْ أَأَنذَرْتَهُمْ أَمْ لَمْ تُنذِرْهُمْ لَا يُؤْمِنُونَ ﴿١٠﴾ إِنَّمَا تُنذِرُ مَنِ اتَّبَعَ الذِّكْرَ... ﴾ [يس : ١٠-١١]','
﴿ <span style="color:red">إِنَّ الَّذِينَ كَفَرُوا</span> سَوَاءٌ عَلَيْهِمْ أَأَنذَرْتَهُمْ أَمْ لَمْ تُنذِرْهُمْ لَا يُؤْمِنُونَ ﴿٦﴾ <span style="color:red">خَتَمَ اللَّهُ عَلَىٰ قُلُوبِهِمْ</span>...﴾ [البقرة : ٦-٧]
﴿ <span style="color:red">وَسَوَاءٌ عَلَيْهِمْ أَأَنذَرْتَهُمْ أَمْ لَمْ تُنذِرْهُمْ لَا يُؤْمِنُونَ</span> ﴿١٠﴾ <span style="color:red">إِنَّمَا تُنذِرُ مَنِ اتَّبَعَ الذِّكْرَ</span>... ﴾ [يس : ١٠-١١]','ان الذين كفروا سواء عليهم اانذرتهم ام لم تنذرهم لا يؤمنون ٦ ختم الله علي قلوبهم البقره ٦٧ وسواء عليهم اانذرتهم ام لم تنذرهم لا يؤمنون ١٠ انما تنذر من اتبع الذكر يس ١٠١١',1);
INSERT INTO `mawadi3` (`mawdi_id`,`mawdi_number`,`surah_id`,`reference_text`,`start_page`,`end_page`,`plain_text`,`html_text`,`normalized_text`,`is_closed`) VALUES (10,7,2,'[النحل : ١٠٨]',3,3,'
﴿ خَتَمَ اللَّهُ عَلَىٰ قُلُوبِهِمْ وَعَلَىٰ سَمْعِهِمْ وَعَلَىٰ أَبْصَٰرِهِمْ غِشَٰوَةٌ وَلَهُمْ عَذَابٌ عَظِيمٌ ﴾ [البقرة : ٧]
﴿ أُولَٰئِكَ الَّذِينَ طَبَعَ اللَّهُ عَلَىٰ قُلُوبِهِمْ وَسَمْعِهِمْ وَأَبْصَٰرِهِمْ وَأُولَٰئِكَ هُمُ الْغَٰفِلُونَ ﴾ [النحل : ١٠٨]','
﴿ <span style="color:red">خَتَمَ</span> اللَّهُ عَلَىٰ قُلُوبِهِمْ <span style="color:red">وَعَلَىٰ</span> سَمْعِهِمْ <span style="color:red">وَعَلَىٰ</span> أَبْصَٰرِهِمْ <span style="color:red">غِشَٰوَةٌ وَلَهُمْ عَذَابٌ عَظِيمٌ</span> ﴾ [البقرة : ٧]
﴿ أُولَٰئِكَ الَّذِينَ <span style="color:red">طَبَعَ</span> اللَّهُ عَلَىٰ قُلُوبِهِمْ وَسَمْعِهِمْ وَأَبْصَٰرِهِمْ <span style="color:red">وَأُولَٰئِكَ هُمُ الْغَٰفِلُونَ</span> ﴾ [النحل : ١٠٨]','ختم الله علي قلوبهم وعلي سمعهم وعلي ابصرهم غشوه ولهم عذاب عظيم البقره ٧ اولئك الذين طبع الله علي قلوبهم وسمعهم وابصرهم واولئك هم الغفلون النحل ١٠٨',1);
INSERT INTO `mawadi3` (`mawdi_id`,`mawdi_number`,`surah_id`,`reference_text`,`start_page`,`end_page`,`plain_text`,`html_text`,`normalized_text`,`is_closed`) VALUES (11,'٧ ، ١٠',2,'[ثاني البقرة : ١٠]',3,3,'
﴿ خَتَمَ اللَّهُ عَلَىٰ قُلُوبِهِمْ وَعَلَىٰ سَمْعِهِمْ وَعَلَىٰ أَبْصَٰرِهِمْ غِشَٰوَةٌ وَلَهُمْ عَذَابٌ عَظِيمٌ ﴾ [أول البقرة : ٧]
﴿ ... وَلَهُمْ عَذَابٌ أَلِيمٌ بِمَا كَانُوا يَكْذِبُونَ ﴾ [ثاني البقرة : ١٠]
اربط بين عين "على" وعين "عظيم"، أي أن الآية التي جاء بها "على" وجاء بها حرف العين هي التي ختمت بـ"عظيم" التي جاء بها حرف العين كذلك.','
﴿ خَتَمَ اللَّهُ <span style="color:red">عَلَىٰ</span> قُلُوبِهِمْ وَ<span style="color:red">عَلَىٰ</span> سَمْعِهِمْ وَ<span style="color:red">عَلَىٰ</span> أَبْصَٰرِهِمْ غِشَٰوَةٌ وَلَهُمْ عَذَابٌ <span style="color:red">عَظِيمٌ</span> ﴾ [أول البقرة : ٧]
﴿ ... وَلَهُمْ عَذَابٌ <span style="color:red">أَلِيمٌ بِمَا كَانُوا يَكْذِبُونَ</span> ﴾ [ثاني البقرة : ١٠]
اربط بين عين "<span style="color:red"><span style="color:red">على</span></span>" وعين "<span style="color:red"><span style="color:red">عظيم</span></span>"، أي أن الآية التي جاء بها "<span style="color:red"><span style="color:red">على</span></span>" وجاء بها حرف العين هي التي ختمت بـ"<span style="color:red"><span style="color:red">عظيم</span></span>" التي جاء بها حرف العين كذلك.','ختم الله علي قلوبهم وعلي سمعهم وعلي ابصرهم غشوه ولهم عذاب عظيم اول البقره ٧ ولهم عذاب اليم بما كانوا يكذبون ثاني البقره ١٠ اربط بين عين علي وعين عظيم، اي ان الايه التي جاء بها علي وجاء بها حرف العين هي التي ختمت بعظيم التي جاء بها حرف العين كذلك',1);
INSERT INTO `mawadi3` (`mawdi_id`,`mawdi_number`,`surah_id`,`reference_text`,`start_page`,`end_page`,`plain_text`,`html_text`,`normalized_text`,`is_closed`) VALUES (12,8,2,'[العنكبوت : ١٠]',3,3,'
﴿ وَمِنَ النَّاسِ مَن يَقُولُ ءَامَنَّا بِاللَّهِ وَبِالْيَوْمِ... ﴾ [البقرة : ٨]، ﴿ وَمِنَ النَّاسِ مَن يَقُولُ ءَامَنَّا بِاللَّهِ فَإِذَا أُوذِيَ... ﴾ [العنكبوت : ١٠]','
﴿ وَمِنَ النَّاسِ مَن يَقُولُ ءَامَنَّا بِاللَّهِ <span style="color:red">وَبِالْيَوْمِ</span>... ﴾ [البقرة : ٨]، ﴿ وَمِنَ النَّاسِ مَن يَقُولُ ءَامَنَّا بِاللَّهِ <span style="color:red">فَإِذَا أُوذِيَ</span>... ﴾ [العنكبوت : ١٠]','ومن الناس من يقول ءامنا بالله وباليوم البقره ٨، ومن الناس من يقول ءامنا بالله فاذا اوذي العنكبوت ١٠',1);
INSERT INTO `mawadi3` (`mawdi_id`,`mawdi_number`,`surah_id`,`reference_text`,`start_page`,`end_page`,`plain_text`,`html_text`,`normalized_text`,`is_closed`) VALUES (13,8,2,NULL,3,3,'
﴿ بِاللَّهِ وَبِالْيَوْمِ الْآخِرِ ﴾ الوحيدة في القرآن وباقي المواضع ﴿ بِاللَّهِ وَالْيَوْمِ الْآخِرِ ﴾ [تكررت ١٩ مرة] عدا موضع [النساء : ٣٨ ، التوبة : ٢٩] ﴿ بِاللَّهِ وَلَا بِالْيَوْمِ الْآخِرِ ﴾','
﴿ <span style="color:red">بِاللَّهِ وَبِالْيَوْمِ الْآخِرِ</span> ﴾ الوحيدة في القرآن وباقي المواضع ﴿ <span style="color:red">بِاللَّهِ وَالْيَوْمِ الْآخِرِ</span> ﴾ [تكررت ١٩ مرة] عدا موضع [النساء : ٣٨ ، التوبة : ٢٩] ﴿ <span style="color:red">بِاللَّهِ وَلَا بِالْيَوْمِ الْآخِرِ</span> ﴾','بالله وباليوم الاخر الوحيده في القران وباقي المواضع بالله واليوم الاخر تكررت ١٩ مره عدا موضع النساء ٣٨ ، التوبه ٢٩ بالله ولا باليوم الاخر',1);
INSERT INTO `mawadi3` (`mawdi_id`,`mawdi_number`,`surah_id`,`reference_text`,`start_page`,`end_page`,`plain_text`,`html_text`,`normalized_text`,`is_closed`) VALUES (14,'١٢ ، ١٣',2,'[ثاني البقرة : ١٣]',3,3,'
﴿ أَلَا إِنَّهُمْ هُمُ الْمُفْسِدُونَ وَلَٰكِن لَّا يَشْعُرُونَ ﴾ [أول البقرة : ١٢]
﴿ وَإِذَا قِيلَ لَهُمْ ءَامِنُوا ... أَلَا إِنَّهُمْ هُمُ السُّفَهَاءُ وَلَٰكِن لَّا يَعْلَمُونَ ﴾ [ثاني البقرة : ١٣]، اربط بين ميم "آمنوا" وميم "لايعلمون"، أي أن الآية التي جاء بها "آمنوا" وجاء بها حرف الميم هي التي ختمت بـ"لا يعلمون" التي جاء بها حرف الميم كذلك.','
﴿ أَلَا إِنَّهُمْ هُمُ الْمُفْسِدُونَ وَلَٰكِن <span style="color:red">لَّا يَشْعُرُونَ</span> ﴾ [أول البقرة : ١٢]
﴿ وَإِذَا قِيلَ لَهُمْ <span style="color:red">ءَامِنُوا</span> ... أَلَا إِنَّهُمْ هُمُ السُّفَهَاءُ وَلَٰكِن <span style="color:red">لَّا يَعْلَمُونَ</span> ﴾ [ثاني البقرة : ١٣]، اربط بين ميم "<span style="color:red"><span style="color:red">آمنوا</span></span>" وميم "<span style="color:red">لايعلمون</span>"، أي أن الآية التي جاء بها "<span style="color:red"><span style="color:red">آمنوا</span></span>" وجاء بها حرف الميم هي التي ختمت بـ"<span style="color:red">لا يعلمون</span>" التي جاء بها حرف الميم كذلك.','الا انهم هم المفسدون ولكن لا يشعرون اول البقره ١٢ واذا قيل لهم ءامنوا الا انهم هم السفهاء ولكن لا يعلمون ثاني البقره ١٣، اربط بين ميم امنوا وميم لايعلمون، اي ان الايه التي جاء بها امنوا وجاء بها حرف الميم هي التي ختمت بلا يعلمون التي جاء بها حرف الميم كذلك',1);
INSERT INTO `mawadi3` (`mawdi_id`,`mawdi_number`,`surah_id`,`reference_text`,`start_page`,`end_page`,`plain_text`,`html_text`,`normalized_text`,`is_closed`) VALUES (15,13,2,'[ثاني البقرة : ٩١]',3,3,'
﴿ وَإِذَا قِيلَ لَهُمْ ءَامِنُوا كَمَا ءَامَنَ النَّاسُ قَالُوا أَنُؤْمِنُ كَمَا ءَامَنَ السُّفَهَاءُ ... ﴾ [أول البقرة : ١٣]
﴿ وَإِذَا قِيلَ لَهُمْ ءَامِنُوا بِمَا أَنزَلَ اللَّهُ قَالُوا نُؤْمِنُ بِمَا أُنزِلَ عَلَيْنَا ... ﴾ [ثاني البقرة : ٩١]','
﴿ وَإِذَا قِيلَ لَهُمْ ءَامِنُوا <span style="color:red">كَمَا ءَامَنَ النَّاسُ</span> قَالُوا أَنُؤْمِنُ <span style="color:red">كَمَا ءَامَنَ السُّفَهَاءُ</span> ... ﴾ [أول البقرة : ١٣]
﴿ وَإِذَا قِيلَ لَهُمْ ءَامِنُوا <span style="color:red">بِمَا أَنزَلَ اللَّهُ</span> قَالُوا نُؤْمِنُ <span style="color:red">بِمَا أُنزِلَ عَلَيْنَا</span> ... ﴾ [ثاني البقرة : ٩١]','واذا قيل لهم ءامنوا كما ءامن الناس قالوا انؤمن كما ءامن السفهاء اول البقره ١٣ واذا قيل لهم ءامنوا بما انزل الله قالوا نؤمن بما انزل علينا ثاني البقره ٩١',1);
INSERT INTO `mawadi3` (`mawdi_id`,`mawdi_number`,`surah_id`,`reference_text`,`start_page`,`end_page`,`plain_text`,`html_text`,`normalized_text`,`is_closed`) VALUES (16,14,2,'[ثاني البقرة : ٧٦]',3,3,'
﴿ وَإِذَا لَقُوا الَّذِينَ ءَامَنُوا قَالُوا ءَامَنَّا وَإِذَا خَلَوْا إِلَىٰ شَيَٰطِينِهِمْ قَالُوا إِنَّا مَعَكُمْ إِنَّمَا نَحْنُ مُسْتَهْزِءُونَ ﴾ [أول البقرة : ١٤]
﴿ وَإِذَا لَقُوا الَّذِينَ ءَامَنُوا قَالُوا ءَامَنَّا وَإِذَا خَلَا بَعْضُهُمْ إِلَىٰ بَعْضٍ قَالُوا أَتُحَدِّثُونَهُم ... ﴾ [ثاني البقرة : ٧٦]
اربط بين واو "خلوا" وواو أول، أي أن الآية التي جاء بها "خلوا" وجاء بها حرف الواو قد وقعت بالموضع الأول الذي جاء به حرف الواو كذلك، وأيضًا اربط بين الألف المدية في "خلا" والألف المدية في ثاني.','
﴿ وَإِذَا لَقُوا الَّذِينَ ءَامَنُوا قَالُوا ءَامَنَّا وَإِذَا <span style="color:red">خَلَوْا إِلَىٰ شَيَٰطِينِهِمْ</span> قَالُوا إِنَّا مَعَكُمْ <span style="color:red">إِنَّمَا نَحْنُ مُسْتَهْزِءُونَ</span> ﴾ [<span style="color:red">أول</span> البقرة : ١٤]
﴿ وَإِذَا لَقُوا الَّذِينَ ءَامَنُوا قَالُوا ءَامَنَّا وَإِذَا <span style="color:red">خَلَا بَعْضُهُمْ إِلَىٰ بَعْضٍ</span> قَالُوا <span style="color:red">أَتُحَدِّثُونَهُم</span> ... ﴾ [<span style="color:red">ثاني</span> البقرة : ٧٦]
اربط بين واو "<span style="color:red"><span style="color:red">خلوا</span></span>" وواو <span style="color:red">أول</span>، أي أن الآية التي جاء بها "<span style="color:red"><span style="color:red">خلوا</span></span>" وجاء بها حرف الواو قد وقعت بالموضع ال<span style="color:red">أول</span> الذي جاء به حرف الواو كذلك، وأيضًا اربط بين الألف المدية في "<span style="color:red">خلا</span>" والألف المدية في <span style="color:red">ثاني</span>.','واذا لقوا الذين ءامنوا قالوا ءامنا واذا خلوا الي شيطينهم قالوا انا معكم انما نحن مستهزءون اول البقره ١٤ واذا لقوا الذين ءامنوا قالوا ءامنا واذا خلا بعضهم الي بعض قالوا اتحدثونهم ثاني البقره ٧٦ اربط بين واو خلوا وواو اول، اي ان الايه التي جاء بها خلوا وجاء بها حرف الواو قد وقعت بالموضع الاول الذي جاء به حرف الواو كذلك، وايضا اربط بين الالف المديه في خلا والالف المديه في ثاني',1);
INSERT INTO `mawadi3` (`mawdi_id`,`mawdi_number`,`surah_id`,`reference_text`,`start_page`,`end_page`,`plain_text`,`html_text`,`normalized_text`,`is_closed`) VALUES (17,16,2,'[ثاني البقرة : ٨٦]',3,3,'
﴿ أُولَٰئِكَ الَّذِينَ اشْتَرَوُا الضَّلَٰلَةَ بِالْهُدَىٰ فَمَا رَبِحَت تِّجَٰرَتُهُمْ وَمَا كَانُوا مُهْتَدِينَ ﴾ [أول البقرة : ١٦]
﴿ أُولَٰئِكَ الَّذِينَ اشْتَرَوُا الضَّلَٰلَةَ بِالْهُدَىٰ وَالْعَذَابَ بِالْمَغْفِرَةِ فَمَا أَصْبَرَهُمْ عَلَى النَّارِ ﴾ [ثالث البقرة : ١٧٥]
﴿ أُولَٰئِكَ الَّذِينَ اشْتَرَوُا الْحَيَوٰةَ الدُّنْيَا بِالْآخِرَةِ فَلَا يُخَفَّفُ عَنْهُمُ الْعَذَابُ وَلَا هُمْ يُنصَرُونَ ﴾ [ثاني البقرة : ٨٦]
ملحوظة: آية البقرة الثانية "اشتروا الحياة" وباقي المواضع "اشتروا الضلالة".','
﴿ أُولَٰئِكَ الَّذِينَ اشْتَرَوُا الضَّلَٰلَةَ بِالْهُدَىٰ <span style="color:red">فَمَا رَبِحَت تِّجَٰرَتُهُمْ وَمَا كَانُوا مُهْتَدِينَ</span> ﴾ [أول البقرة : ١٦]
﴿ أُولَٰئِكَ الَّذِينَ اشْتَرَوُا الضَّلَٰلَةَ بِالْهُدَىٰ <span style="color:red">وَالْعَذَابَ بِالْمَغْفِرَةِ فَمَا أَصْبَرَهُمْ عَلَى النَّارِ</span> ﴾ [ثالث البقرة : ١٧٥]
﴿ أُولَٰئِكَ الَّذِينَ اشْتَرَوُا <span style="color:red">الْحَيَوٰةَ الدُّنْيَا بِالْآخِرَةِ فَلَا يُخَفَّفُ عَنْهُمُ الْعَذَابُ وَلَا هُمْ يُنصَرُونَ</span> ﴾ [ثاني البقرة : ٨٦]
ملحوظة: آية البقرة الثانية "<span style="color:red">اشتروا الحياة</span>" وباقي المواضع "<span style="color:red">اشتروا الضلالة</span>".','اولئك الذين اشتروا الضلله بالهدي فما ربحت تجرتهم وما كانوا مهتدين اول البقره ١٦ اولئك الذين اشتروا الضلله بالهدي والعذاب بالمغفره فما اصبرهم علي النار ثالث البقره ١٧٥ اولئك الذين اشتروا الحيوه الدنيا بالاخره فلا يخفف عنهم العذاب ولا هم ينصرون ثاني البقره ٨٦ ملحوظه ايه البقره الثانيه اشتروا الحياه وباقي المواضع اشتروا الضلاله',1);
INSERT INTO `mawadi3` (`mawdi_id`,`mawdi_number`,`surah_id`,`reference_text`,`start_page`,`end_page`,`plain_text`,`html_text`,`normalized_text`,`is_closed`) VALUES (18,18,2,'ثاني البقرة : ١٧١',4,4,'
﴿ صُمٌّ بُكْمٌ عُمْيٌ فَهُمْ لَا يَرْجِعُونَ ﴾ [أول البقرة : ١٨]
﴿ ... كَمَثَلِ الَّذِي يَنْعِقُ بِمَا لَا يَسْمَعُ إِلَّا دُعَاءً وَنِدَاءً صُمٌّ بُكْمٌ عُمْيٌ فَهُمْ لَا يَعْقِلُونَ ﴾ [ثاني البقرة : ١٧١]
اربط بين قاف "ينعق" وقاف "يعقلون"، أي أن الآية التي جاء بها "ينعق" هي التي ختمت بـ"لا يعقلون".','
﴿ صُمٌّ بُكْمٌ عُمْيٌ فَهُمْ لَا <span style="color:red">يَرْجِعُونَ</span> ﴾ [أول البقرة : ١٨]
﴿ ... كَمَثَلِ الَّذِي <span style="color:red">يَنْعِقُ</span> بِمَا لَا يَسْمَعُ إِلَّا دُعَاءً وَنِدَاءً صُمٌّ بُكْمٌ عُمْيٌ فَهُمْ لَا <span style="color:red">يَعْقِلُونَ</span> ﴾ [ثاني البقرة : ١٧١]
اربط بين قاف "ينعق" وقاف "يعقلون"، أي أن الآية التي جاء بها "ينعق" هي التي ختمت بـ"لا يعقلون".','صم بكم عمي فهم لا يرجعون اول البقره ١٨ كمثل الذي ينعق بما لا يسمع الا دعاء ونداء صم بكم عمي فهم لا يعقلون ثاني البقره ١٧١ اربط بين قاف ينعق وقاف يعقلون، اي ان الايه التي جاء بها ينعق هي التي ختمت بلا يعقلون',1);
INSERT INTO `mawadi3` (`mawdi_id`,`mawdi_number`,`surah_id`,`reference_text`,`start_page`,`end_page`,`plain_text`,`html_text`,`normalized_text`,`is_closed`) VALUES (19,21,2,'لقمان : ٣٣',4,4,'
﴿ يَٰأَيُّهَا النَّاسُ اعْبُدُوا رَبَّكُمُ الَّذِي خَلَقَكُمْ وَالَّذِينَ مِن قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ ﴾ [البقرة : ٢١]
﴿ يَٰأَيُّهَا النَّاسُ اتَّقُوا رَبَّكُمُ الَّذِي خَلَقَكُم مِّن نَّفْسٍ وَٰحِدَةٍ ... ﴾ [النساء : ١]
﴿ يَٰأَيُّهَا النَّاسُ اتَّقُوا رَبَّكُمْ إِنَّ زَلْزَلَةَ ... ﴾ [الحج : ١]
﴿ يَٰأَيُّهَا النَّاسُ اتَّقُوا رَبَّكُمْ وَاخْشَوْا يَوْمًا ... ﴾ [لقمان : ٣٣]
ملحوظة : آية البقرة الوحيدة "يا أيها الناس اعبدوا ربكم" وباقي المواضع "يا أيها الناس اتقوا ربكم".','
﴿ <span style="color:red">يَٰأَيُّهَا النَّاسُ اعْبُدُوا رَبَّكُمُ الَّذِي خَلَقَكُمْ وَالَّذِينَ مِن قَبْلِكُمْ</span> <span style="color:red">لَعَلَّكُمْ تَتَّقُونَ</span> ﴾ [البقرة : ٢١]
﴿ <span style="color:red">يَٰأَيُّهَا النَّاسُ اتَّقُوا رَبَّكُمُ الَّذِي خَلَقَكُم مِّن نَّفْسٍ</span> <span style="color:red">وَٰحِدَةٍ</span> ... ﴾ [النساء : ١]
﴿ يَٰأَيُّهَا النَّاسُ <span style="color:red">اتَّقُوا رَبَّكُمْ إِنَّ زَلْزَلَةَ</span> ... ﴾ [الحج : ١]
﴿ يَٰأَيُّهَا النَّاسُ <span style="color:red">اتَّقُوا رَبَّكُمْ وَاخْشَوْا يَوْمًا</span> ... ﴾ [لقمان : ٣٣]
ملحوظة : آية البقرة الوحيدة "يا أيها الناس اعبدوا ربكم" وباقي المواضع "يا أيها الناس اتقوا ربكم".','يايها الناس اعبدوا ربكم الذي خلقكم والذين من قبلكم لعلكم تتقون البقره ٢١ يايها الناس اتقوا ربكم الذي خلقكم من نفس وحده النساء ١ يايها الناس اتقوا ربكم ان زلزله الحج ١ يايها الناس اتقوا ربكم واخشوا يوما لقمان ٣٣ ملحوظه ايه البقره الوحيده يا ايها الناس اعبدوا ربكم وباقي المواضع يا ايها الناس اتقوا ربكم',1);
INSERT INTO `mawadi3` (`mawdi_id`,`mawdi_number`,`surah_id`,`reference_text`,`start_page`,`end_page`,`plain_text`,`html_text`,`normalized_text`,`is_closed`) VALUES (20,22,2,'الملك : ١٥',4,4,'
﴿ الَّذِي جَعَلَ لَكُمُ الْأَرْضَ فِرَٰشًا وَالسَّمَاءَ بِنَاءً وَأَنزَلَ مِنَ السَّمَاءِ مَاءً فَأَخْرَجَ بِهِۦ ... ﴾ [البقرة : ٢٢]
﴿ اللَّهُ الَّذِي جَعَلَ لَكُمُ الْأَرْضَ قَرَارًا وَالسَّمَاءَ بِنَاءً وَصَوَّرَكُمْ فَأَحْسَنَ صُوَرَكُمْ ... ﴾ [غافر : ٦٤]
﴿ الَّذِي جَعَلَ لَكُمُ الْأَرْضَ مَهْدًا وَسَلَكَ لَكُمْ فِيهَا سُبُلًا وَأَنزَلَ مِنَ السَّمَاءِ مَاءً فَأَخْرَجْنَا بِهِۦ ... ﴾ [طه : ٥٣]
﴿ الَّذِي جَعَلَ لَكُمُ الْأَرْضَ مَهْدًا وَجَعَلَ لَكُمُ فِيهَا سُبُلًا لَّعَلَّكُمْ تَهْتَدُونَ ﴾ [الزخرف : ١٠]
﴿ هُوَ الَّذِي جَعَلَ لَكُمُ الْأَرْضَ ذَلُولًا فَامْشُوا فِي مَنَاكِبِهَا وَكُلُوا مِن رِّزْقِهِۦ وَإِلَيْهِ النُّشُورُ ﴾ [الملك : ١٥]','
﴿ الَّذِي جَعَلَ لَكُمُ الْأَرْضَ <span style="color:red">فِرَٰشًا</span> وَالسَّمَاءَ بِنَاءً <span style="color:red">وَأَنزَلَ مِنَ السَّمَاءِ مَاءً فَأَخْرَجَ بِهِۦ</span> ... ﴾ [البقرة : ٢٢]
﴿ اللَّهُ الَّذِي جَعَلَ لَكُمُ الْأَرْضَ <span style="color:red">قَرَارًا</span> وَالسَّمَاءَ بِنَاءً <span style="color:red">وَصَوَّرَكُمْ فَأَحْسَنَ صُوَرَكُمْ</span> ... ﴾ [غافر : ٦٤]
﴿ الَّذِي جَعَلَ لَكُمُ الْأَرْضَ <span style="color:red">مَهْدًا وَسَلَكَ لَكُمْ فِيهَا سُبُلًا وَأَنزَلَ مِنَ السَّمَاءِ مَاءً فَأَخْرَجْنَا بِهِۦ</span> ... ﴾ [طه : ٥٣]
﴿ الَّذِي جَعَلَ لَكُمُ الْأَرْضَ <span style="color:red">مَهْدًا وَجَعَلَ لَكُمُ فِيهَا سُبُلًا لَّعَلَّكُمْ تَهْتَدُونَ</span> ﴾ [الزخرف : ١٠]
﴿ هُوَ الَّذِي جَعَلَ لَكُمُ الْأَرْضَ <span style="color:red">ذَلُولًا فَامْشُوا فِي مَنَاكِبِهَا وَكُلُوا مِن رِّزْقِهِۦ وَإِلَيْهِ النُّشُورُ</span> ﴾ [الملك : ١٥]','الذي جعل لكم الارض فرشا والسماء بناء وانزل من السماء ماء فاخرج بهۦ البقره ٢٢ الله الذي جعل لكم الارض قرارا والسماء بناء وصوركم فاحسن صوركم غافر ٦٤ الذي جعل لكم الارض مهدا وسلك لكم فيها سبلا وانزل من السماء ماء فاخرجنا بهۦ طه ٥٣ الذي جعل لكم الارض مهدا وجعل لكم فيها سبلا لعلكم تهتدون الزخرف ١٠ هو الذي جعل لكم الارض ذلولا فامشوا في مناكبها وكلوا من رزقهۦ واليه النشور الملك ١٥',1);
INSERT INTO `mawadi3` (`mawdi_id`,`mawdi_number`,`surah_id`,`reference_text`,`start_page`,`end_page`,`plain_text`,`html_text`,`normalized_text`,`is_closed`) VALUES (21,22,2,'النمل : ٦٠',4,4,'
﴿ ... وَأَنزَلَ مِنَ السَّمَاءِ مَاءً فَأَخْرَجَ بِهِۦ مِنَ الثَّمَرَٰتِ رِزْقًا لَّكُمْ فَلَا تَجْعَلُوا لِلَّهِ أَندَادًا وَأَنتُمْ تَعْلَمُونَ ﴾ [البقرة : ٢٢]
﴿ ... وَأَنزَلَ مِنَ السَّمَاءِ مَاءً فَأَخْرَجَ بِهِۦ مِنَ الثَّمَرَٰتِ رِزْقًا لَّكُمْ وَسَخَّرَ لَكُمُ الْفُلْكَ لِتَجْرِيَ فِي الْبَحْرِ ... ﴾ [إبراهيم : ٣٢]
﴿ وَهُوَ الَّذِي أَنزَلَ مِنَ السَّمَاءِ مَاءً فَأَخْرَجْنَا بِهِۦ نَبَاتَ كُلِّ شَيْءٍ فَأَخْرَجْنَا مِنْهُ خَضِرًا ... ﴾ [الأنعام : ٩٩]
﴿ الَّذِي جَعَلَ لَكُمُ الْأَرْضَ مَهْدًا وَسَلَكَ لَكُمْ فِيهَا سُبُلًا وَأَنزَلَ مِنَ السَّمَاءِ مَاءً فَأَخْرَجْنَا بِهِۦ أَزْوَٰجًا مِّن نَّبَاتٍ ... ﴾ [طه : ٥٣]
﴿ أَلَمْ تَرَ أَنَّ اللَّهَ أَنزَلَ مِنَ السَّمَاءِ مَاءً فَأَخْرَجْنَا بِهِۦ ثَمَرَٰتٍ مُّخْتَلِفًا أَلْوَٰنُهَا وَمِنَ الْجِبَالِ جُدَدٌ بِيضٌ ... ﴾ [فاطر : ٢٧]
﴿ أَمَّنْ خَلَقَ السَّمَٰوَٰتِ وَالْأَرْضَ وَأَنزَلَ لَكُم مِّنَ السَّمَاءِ مَاءً فَأَنبَتْنَا بِهِۦ حَدَائِقَ ذَاتَ بَهْجَةٍ ... ﴾ [النمل : ٦٠]
ملحوظة : آية النمل الوحيدة "أنزل لكم من السماء ماء" وباقي المواضع "أنزل من السماء ماء".','
﴿ ... وَأَنزَلَ مِنَ السَّمَاءِ مَاءً <span style="color:red"><span style="color:red">فَأَخْرَجَ بِهِۦ</span></span> مِنَ الثَّمَرَٰتِ رِزْقًا لَّكُمْ <span style="color:red">فَلَا تَجْعَلُوا لِلَّهِ أَندَادًا وَأَنتُمْ تَعْلَمُونَ</span> ﴾ [البقرة : ٢٢]
﴿ ... وَأَنزَلَ مِنَ السَّمَاءِ مَاءً <span style="color:red"><span style="color:red">فَأَخْرَجَ بِهِۦ</span></span> مِنَ الثَّمَرَٰتِ رِزْقًا لَّكُمْ <span style="color:red">وَسَخَّرَ <span style="color:red">لَكُم</span>ُ الْفُلْكَ لِتَجْرِيَ فِي الْبَحْرِ</span> ... ﴾ [إبراهيم : ٣٢]
﴿ وَهُوَ الَّذِي أَنزَلَ مِنَ السَّمَاءِ مَاءً <span style="color:red">فَأَخْرَجْنَا بِهِۦ</span> <span style="color:red">نَبَاتَ كُلِّ شَيْءٍ فَأَخْرَجْنَا مِنْهُ خَضِرًا</span> ... ﴾ [الأنعام : ٩٩]
﴿ الَّذِي جَعَلَ <span style="color:red">لَكُم</span>ُ الْأَرْضَ مَهْدًا وَسَلَكَ <span style="color:red">لَكُم</span>ْ فِيهَا سُبُلًا وَأَنزَلَ مِنَ السَّمَاءِ مَاءً <span style="color:red">فَأَخْرَجْنَا بِهِۦ</span> أَزْوَٰجًا مِّن نَّبَاتٍ ... ﴾ [طه : ٥٣]
﴿ أَلَمْ تَرَ أَنَّ اللَّهَ أَنزَلَ مِنَ السَّمَاءِ مَاءً <span style="color:red">فَأَخْرَجْنَا بِهِۦ</span> ثَمَرَٰتٍ مُّخْتَلِفًا أَلْوَٰنُهَا وَمِنَ الْجِبَالِ جُدَدٌ بِيضٌ ... ﴾ [فاطر : ٢٧]
﴿ أَمَّنْ خَلَقَ السَّمَٰوَٰتِ وَالْأَرْضَ وَأَنزَلَ <span style="color:red">لَكُم</span> مِّنَ السَّمَاءِ مَاءً <span style="color:red">فَأَنبَتْنَا بِهِۦ حَدَائِقَ ذَاتَ بَهْجَةٍ</span> ... ﴾ [النمل : ٦٠]
ملحوظة : آية النمل الوحيدة "أنزل لكم من السماء ماء" وباقي المواضع "أنزل من السماء ماء".','وانزل من السماء ماء فاخرج بهۦ من الثمرت رزقا لكم فلا تجعلوا لله اندادا وانتم تعلمون البقره ٢٢ وانزل من السماء ماء فاخرج بهۦ من الثمرت رزقا لكم وسخر لكم الفلك لتجري في البحر ابراهيم ٣٢ وهو الذي انزل من السماء ماء فاخرجنا بهۦ نبات كل شيء فاخرجنا منه خضرا الانعام ٩٩ الذي جعل لكم الارض مهدا وسلك لكم فيها سبلا وانزل من السماء ماء فاخرجنا بهۦ ازوجا من نبات طه ٥٣ الم تر ان الله انزل من السماء ماء فاخرجنا بهۦ ثمرت مختلفا الونها ومن الجبال جدد بيض فاطر ٢٧ امن خلق السموت والارض وانزل لكم من السماء ماء فانبتنا بهۦ حدائق ذات بهجه النمل ٦٠ ملحوظه ايه النمل الوحيده انزل لكم من السماء ماء وباقي المواضع انزل من السماء ماء',1);
INSERT INTO `mawadi3` (`mawdi_id`,`mawdi_number`,`surah_id`,`reference_text`,`start_page`,`end_page`,`plain_text`,`html_text`,`normalized_text`,`is_closed`) VALUES (22,23,2,'هود : ١٣-١٤',4,4,'
﴿ ... وَإِن كُنتُمْ فِي رَيْبٍ ... فَأْتُوا بِسُورَةٍ مِّن مِّثْلِهِۦ وَادْعُوا شُهَدَاءَكُم مِّن دُونِ اللَّهِ إِن كُنتُمْ صَٰدِقِينَ ۝ ﴾ [البقرة : ٢٣-٢٤]
﴿ أَمْ يَقُولُونَ افْتَرَاهُ قُلْ فَأْتُوا بِسُورَةٍ مِّثْلِهِ وَادْعُوا مَنِ اسْتَطَعْتُم مِّن دُونِ اللَّهِ إِن كُنتُمْ صَٰدِقِينَ ۝ بَلْ كَذَّبُوا بِمَا لَمْ يُحِيطُوا بِعِلْمِهِۦ وَلَمَّا يَأْتِهِمْ تَأْوِيلُهُۥ ... ﴾ [يونس : ٣٨-٣٩]
﴿ أَمْ يَقُولُونَ افْتَرَاهُ قُلْ فَأْتُوا بِعَشْرِ سُوَرٍ مِّثْلِهِۦ مُفْتَرَيَٰتٍ وَادْعُوا مَنِ اسْتَطَعْتُم مِّن دُونِ اللَّهِ إِن كُنتُمْ صَٰدِقِينَ ۝ فَإِلَّمْ يَسْتَجِيبُوا لَكُمْ ... ﴾ [هود : ١٣-١٤]
ملحوظة : آية البقرة الوحيدة "بسورة من مثله" و"وادعوا من استطعتم"، وآية هود الوحيدة "بعشر سور مثله مفتريات".','
﴿ ... <span style="color:red">وَإِن كُنتُمْ فِي رَيْبٍ</span> ... فَأْتُوا بِسُورَةٍ <span style="color:red">مِّن مِّثْلِهِۦ</span> وَادْعُوا <span style="color:red">شُهَدَاءَكُم</span> مِّن دُونِ اللَّهِ إِن كُنتُمْ صَٰدِقِينَ ۝ ﴾ [البقرة : ٢٣-٢٤]
﴿ أَمْ يَقُولُونَ افْتَرَاهُ قُلْ فَأْتُوا بِسُورَةٍ مِّثْلِهِ وَادْعُوا <span style="color:red"><span style="color:red">مَنِ اسْتَطَعْتُم</span></span> مِّن دُونِ اللَّهِ إِن كُنتُمْ صَٰدِقِينَ ۝ <span style="color:red">بَلْ كَذَّبُوا بِمَا لَمْ يُحِيطُوا بِعِلْمِهِۦ وَلَمَّا يَأْتِهِمْ تَأْوِيلُهُۥ</span> ... ﴾ [يونس : ٣٨-٣٩]
﴿ أَمْ يَقُولُونَ افْتَرَاهُ قُلْ فَأْتُوا <span style="color:red">بِعَشْرِ سُوَرٍ مِّثْلِهِۦ مُفْتَرَيَٰتٍ</span> وَادْعُوا <span style="color:red"><span style="color:red">مَنِ اسْتَطَعْتُم</span></span> مِّن دُونِ اللَّهِ إِن كُنتُمْ صَٰدِقِينَ ۝ <span style="color:red">فَإِلَّمْ يَسْتَجِيبُوا لَكُمْ</span> ... ﴾ [هود : ١٣-١٤]
ملحوظة : آية البقرة الوحيدة "بسورة من مثله" و"وادعوا من استطعتم"، وآية هود الوحيدة "بعشر سور مثله مفتريات".','وان كنتم في ريب فاتوا بسوره من مثلهۦ وادعوا شهداءكم من دون الله ان كنتم صدقين ۝ البقره ٢٣٢٤ ام يقولون افتراه قل فاتوا بسوره مثله وادعوا من استطعتم من دون الله ان كنتم صدقين ۝ بل كذبوا بما لم يحيطوا بعلمهۦ ولما ياتهم تاويلهۥ يونس ٣٨٣٩ ام يقولون افتراه قل فاتوا بعشر سور مثلهۦ مفتريت وادعوا من استطعتم من دون الله ان كنتم صدقين ۝ فالم يستجيبوا لكم هود ١٣١٤ ملحوظه ايه البقره الوحيده بسوره من مثله ووادعوا من استطعتم، وايه هود الوحيده بعشر سور مثله مفتريات',1);
INSERT INTO `mawadi3` (`mawdi_id`,`mawdi_number`,`surah_id`,`reference_text`,`start_page`,`end_page`,`plain_text`,`html_text`,`normalized_text`,`is_closed`) VALUES (23,25,2,'يونس : ٢',5,5,'
[٢٥] ﴿ وَبَشِّرِ الَّذِينَ ءَامَنُوا وَعَمِلُوا الصَّـٰلِحَـٰتِ أَنَّ لَهُمْ جَنَّـٰتٍ... ﴾ [البقرة : ٢٥]
﴿ ... وَبَشِّرِ الَّذِينَ ءَامَنُوا أَنَّ لَهُمْ قَدَمَ صِدْقٍ عِندَ رَبِّهِمْ ... ﴾ [يونس : ٢]','
[٢٥] ﴿ وَبَشِّرِ الَّذِينَ ءَامَنُوا <span style="color:red">وَعَمِلُوا الصَّـٰلِحَـٰتِ</span> أَنَّ لَهُمْ جَنَّـٰتٍ... ﴾ [البقرة : ٢٥]
﴿ ... وَبَشِّرِ الَّذِينَ ءَامَنُوا أَنَّ لَهُمْ <span style="color:red">قَدَمَ صِدْقٍ عِندَ رَبِّهِمْ</span> ... ﴾ [يونس : ٢]','٢٥ وبشر الذين ءامنوا وعملوا الصلحت ان لهم جنت البقره ٢٥ وبشر الذين ءامنوا ان لهم قدم صدق عند ربهم يونس ٢',1);
INSERT INTO `mawadi3` (`mawdi_id`,`mawdi_number`,`surah_id`,`reference_text`,`start_page`,`end_page`,`plain_text`,`html_text`,`normalized_text`,`is_closed`) VALUES (24,25,2,NULL,5,5,'
[٢٥] ﴿ جَنَّـٰتٍ تَجْرِى مِن تَحْتِهَا الْأَنْهَـٰرُ ﴾ تكررت ١١ مرة:
[البقرة : ٢٥، آل عمران : ١٩٥، المائدة : ١٢، الحج : ١٤، ٢٣، الفرقان : ١٠، محمد : ١٢، الفتح : ١٧، الصف : ١٢، التحريم : ٨، البروج : ١١]
وباقي المواضع بزيادة ﴿ خَـٰلِدِينَ فِيهَا ﴾
[آل عمران : ١٥ ، ١٣٦ ، ١٩٨، النساء : ١٣ ، ٥٧ ، ١٢٢، المائدة : ٨٥، ١١٩، التوبة : ٧٢ ، ٨٩، إبراهيم : ٢٣ ، الفتح : ٥، الحديد : ١٢
المجادلة : ٢٢ ، التغابن : ٩، الطلاق : ١١]','
[٢٥] ﴿ <span style="color:red">جَنَّـٰتٍ تَجْرِى مِن تَحْتِهَا الْأَنْهَـٰرُ</span> ﴾ تكررت ١١ مرة:
[البقرة : ٢٥، آل عمران : ١٩٥، المائدة : ١٢، الحج : ١٤، ٢٣، الفرقان : ١٠، محمد : ١٢، الفتح : ١٧، الصف : ١٢، التحريم : ٨، البروج : ١١]
وباقي المواضع بزيادة ﴿ <span style="color:red">خَـٰلِدِينَ فِيهَا</span> ﴾
[آل عمران : ١٥ ، ١٣٦ ، ١٩٨، النساء : ١٣ ، ٥٧ ، ١٢٢، المائدة : ٨٥، ١١٩، التوبة : ٧٢ ، ٨٩، إبراهيم : ٢٣ ، الفتح : ٥، الحديد : ١٢
المجادلة : ٢٢ ، التغابن : ٩، الطلاق : ١١]','٢٥ جنت تجري من تحتها الانهر تكررت ١١ مره البقره ٢٥، ال عمران ١٩٥، المائده ١٢، الحج ١٤، ٢٣، الفرقان ١٠، محمد ١٢، الفتح ١٧، الصف ١٢، التحريم ٨، البروج ١١ وباقي المواضع بزياده خلدين فيها ال عمران ١٥ ، ١٣٦ ، ١٩٨، النساء ١٣ ، ٥٧ ، ١٢٢، المائده ٨٥، ١١٩، التوبه ٧٢ ، ٨٩، ابراهيم ٢٣ ، الفتح ٥، الحديد ١٢ المجادله ٢٢ ، التغابن ٩، الطلاق ١١',1);
INSERT INTO `mawadi3` (`mawdi_id`,`mawdi_number`,`surah_id`,`reference_text`,`start_page`,`end_page`,`plain_text`,`html_text`,`normalized_text`,`is_closed`) VALUES (25,25,2,'النساء : ٥٧',5,5,'
[٢٥] ﴿ ... وَأُتُوا۟ بِهِۦ مُتَشَـٰبِهً۠ا وَلَهُمْ فِيهَا أَزْوَٰجٌ مُّطَهَّرَةٌ وَهُمْ فِيهَا خَـٰلِدُونَ ﴾ [البقرة : ٢٥]
﴿ ... جَنَّـٰتٍ تَجْرِى مِن تَحْتِهَا الْأَنْهَـٰرُ خَـٰلِدِينَ فِيهَا وَأَزْوَٰجٌ مُّطَهَّرَةٌ وَرِضْوَٰنٌ مِّنَ اللَّهِ... ﴾ [آل عمران : ١٥]
﴿ ... سَنُدْخِلُهُمْ جَنَّـٰتٍ تَجْرِى مِن تَحْتِهَا الْأَنْهَـٰرُ خَـٰلِدِينَ فِيهَا أَبَدً۠ا لَّهُمْ فِيهَا أَزْوَٰجٌ مُّطَهَّرَةٌ وَنُدْخِلُهُمْ ظِلًّا ظَلِيلًا ﴾ [النساء : ٥٧]','
[٢٥] ﴿ ... وَأُتُوا۟ بِهِۦ مُتَشَـٰبِهً۠ا وَلَهُمْ فِيهَا أَزْوَٰجٌ مُّطَهَّرَةٌ <span style="color:red">وَهُمْ فِيهَا خَـٰلِدُونَ</span> ﴾ [البقرة : ٢٥]
﴿ ... جَنَّـٰتٍ تَجْرِى مِن تَحْتِهَا الْأَنْهَـٰرُ خَـٰلِدِينَ فِيهَا وَأَزْوَٰجٌ مُّطَهَّرَةٌ <span style="color:red">وَرِضْوَٰنٌ مِّنَ اللَّهِ</span>... ﴾ [آل عمران : ١٥]
﴿ ... سَنُدْخِلُهُمْ جَنَّـٰتٍ تَجْرِى مِن تَحْتِهَا الْأَنْهَـٰرُ خَـٰلِدِينَ فِيهَا أَبَدً۠ا لَّهُمْ فِيهَا أَزْوَٰجٌ مُّطَهَّرَةٌ <span style="color:red">وَنُدْخِلُهُمْ ظِلًّا ظَلِيلًا</span> ﴾ [النساء : ٥٧]','٢٥ واتوا۟ بهۦ متشبه۠ا ولهم فيها ازوج مطهره وهم فيها خلدون البقره ٢٥ جنت تجري من تحتها الانهر خلدين فيها وازوج مطهره ورضون من الله ال عمران ١٥ سندخلهم جنت تجري من تحتها الانهر خلدين فيها ابد۠ا لهم فيها ازوج مطهره وندخلهم ظلا ظليلا النساء ٥٧',1);
INSERT INTO `mawadi3` (`mawdi_id`,`mawdi_number`,`surah_id`,`reference_text`,`start_page`,`end_page`,`plain_text`,`html_text`,`normalized_text`,`is_closed`) VALUES (26,26,2,'المدثر : ٣١',5,5,'
[٢٦] ﴿ ... وَأَمَّا الَّذِينَ كَفَرُوا۟ فَيَقُولُونَ مَاذَآ أَرَادَ اللَّهُ بِهَـٰذَا مَثَلًا يُضِلُّ بِهِۦ كَثِيرًا وَيَهْدِى بِهِۦ كَثِيرًا ... ﴾ [البقرة : ٢٦]
﴿ ... وَلِيَقُولَ الَّذِينَ فِى قُلُوبِهِم مَّرَضٌ وَالْكَـٰفِرُونَ مَاذَآ أَرَادَ اللَّهُ بِهَـٰذَا مَثَلًا كَذَٰلِكَ يُضِلُّ اللَّهُ مَن يَشَآءُ وَيَهْدِى مَن يَشَآءُ... ﴾ [المدثر : ٣١]
"به" جاء بها حرف الباء، واسم السورة كذلك جاء به حرف الباء -البقرة- وعن طريقه يكون الربط.','
[٢٦] ﴿ ... وَأَمَّا الَّذِينَ كَفَرُوا۟ فَيَقُولُونَ مَاذَآ أَرَادَ اللَّهُ بِهَـٰذَا مَثَلًا يُضِلُّ بِهِۦ <span style="color:red"><span style="color:red">كَثِيرًا</span></span> وَيَهْدِى بِهِۦ <span style="color:red"><span style="color:red">كَثِيرًا</span></span> ... ﴾ [البقرة : ٢٦]
﴿ ... وَلِيَقُولَ الَّذِينَ فِى قُلُوبِهِم مَّرَضٌ وَالْكَـٰفِرُونَ مَاذَآ أَرَادَ اللَّهُ بِهَـٰذَا مَثَلًا <span style="color:red">كَذَٰلِكَ يُضِلُّ اللَّهُ مَن يَشَآءُ وَيَهْدِى مَن يَشَآءُ</span>... ﴾ [المدثر : ٣١]
"<span style="color:red">به</span>" جاء <span style="color:red">به</span>ا حرف الباء، واسم السورة كذلك جاء <span style="color:red">به</span> حرف الباء -البقرة- وعن طريقه يكون الربط.','٢٦ واما الذين كفروا۟ فيقولون ماذا اراد الله بهذا مثلا يضل بهۦ كثيرا ويهدي بهۦ كثيرا البقره ٢٦ وليقول الذين في قلوبهم مرض والكفرون ماذا اراد الله بهذا مثلا كذلك يضل الله من يشاء ويهدي من يشاء المدثر ٣١ به جاء بها حرف الباء، واسم السوره كذلك جاء به حرف الباء البقره وعن طريقه يكون الربط',1);
INSERT INTO `mawadi3` (`mawdi_id`,`mawdi_number`,`surah_id`,`reference_text`,`start_page`,`end_page`,`plain_text`,`html_text`,`normalized_text`,`is_closed`) VALUES (27,27,2,'الرعد : ٢٥',5,5,'
[٢٧] ﴿ الَّذِينَ يَنقُضُونَ عَهْدَ اللَّهِ مِن بَعْدِ مِيثَـٰقِهِۦ وَيَقْطَعُونَ مَآ أَمَرَ اللَّهُ بِهِۦ أَن يُوصَلَ وَيُفْسِدُونَ فِى الْأَرْضِ أُو۟لَـٰٓئِكَ هُمُ الْخَـٰسِرُونَ ﴾ [البقرة : ٢٧]
﴿ وَالَّذِينَ يَنقُضُونَ عَهْدَ اللَّهِ مِن بَعْدِ مِيثَـٰقِهِۦ وَيَقْطَعُونَ مَآ أَمَرَ اللَّهُ بِهِۦ أَن يُوصَلَ وَيُفْسِدُونَ فِى الْأَرْضِ أُو۟لَـٰٓئِكَ لَهُمُ اللَّعْنَةُ وَلَهُمْ سُوٓءُ الدَّارِ ﴾ [الرعد : ٢٥]
اربط بين هاء "هم" وهَاء البقره، أي أن السورة التي جاء في اسمها حرف الهاء -البقره- هـ، التي وقعت بها "هم" التي جاء بها حرف الهاء كذلك، وأيضًا اربط بين عين "اللعنة" وعين الرعد.','
[٢٧] ﴿ الَّذِينَ يَنقُضُونَ عَهْدَ اللَّهِ مِن بَعْدِ مِيثَـٰقِهِۦ وَيَقْطَعُونَ مَآ أَمَرَ اللَّهُ بِهِۦ أَن يُوصَلَ وَيُفْسِدُونَ فِى الْأَرْضِ أُو۟لَـٰٓئِكَ <span style="color:red">هُمُ الْخَـٰسِرُونَ</span> ﴾ [البقرة : ٢٧]
﴿ وَالَّذِينَ يَنقُضُونَ عَهْدَ اللَّهِ مِن بَعْدِ مِيثَـٰقِهِۦ وَيَقْطَعُونَ مَآ أَمَرَ اللَّهُ بِهِۦ أَن يُوصَلَ وَيُفْسِدُونَ فِى الْأَرْضِ أُو۟لَـٰٓئِكَ <span style="color:red">لَهُمُ اللَّعْنَةُ وَلَهُمْ سُوٓءُ الدَّارِ</span> ﴾ [الرعد : ٢٥]
اربط بين هاء "<span style="color:red"><span style="color:red">هم</span></span>" وهَاء البقره، أي أن السورة التي جاء في اسمها حرف الهاء -البقره- هـ، التي وقعت بها "<span style="color:red"><span style="color:red">هم</span></span>" التي جاء بها حرف الهاء كذلك، وأيضًا اربط بين عين "اللعنة" وعين الرعد.','٢٧ الذين ينقضون عهد الله من بعد ميثقهۦ ويقطعون ما امر الله بهۦ ان يوصل ويفسدون في الارض او۟لٓئك هم الخسرون البقره ٢٧ والذين ينقضون عهد الله من بعد ميثقهۦ ويقطعون ما امر الله بهۦ ان يوصل ويفسدون في الارض او۟لٓئك لهم اللعنه ولهم سوٓء الدار الرعد ٢٥ اربط بين هاء هم وهاء البقره، اي ان السوره التي جاء في اسمها حرف الهاء البقره ه، التي وقعت بها هم التي جاء بها حرف الهاء كذلك، وايضا اربط بين عين اللعنه وعين الرعد',1);
INSERT INTO `mawadi3` (`mawdi_id`,`mawdi_number`,`surah_id`,`reference_text`,`start_page`,`end_page`,`plain_text`,`html_text`,`normalized_text`,`is_closed`) VALUES (28,28,2,'آل عمران : ١٠١',5,5,'
[٢٨] ﴿ كَيْفَ تَكْفُرُونَ بِاللَّهِ وَكُنتُمْ أَمْوَٰتًا... ﴾ [البقرة : ٢٨]، ﴿ وَكَيْفَ تَكْفُرُونَ وَأَنتُمْ تُتْلَىٰ عَلَيْكُمْ ءَايَـٰتُ... ﴾ [آل عمران : ١٠١]
وبالزيادة في ترتيب السور جاءت "وكيف" بآل عمران بزيادة حرف الواو.','
[٢٨] ﴿ كَيْفَ تَكْفُرُونَ بِاللَّهِ <span style="color:red">وَكُنتُمْ أَمْوَٰتًا</span>... ﴾ [البقرة : ٢٨]، ﴿ <span style="color:red">وَكَيْفَ تَكْفُرُونَ وَأَنتُمْ تُتْلَىٰ عَلَيْكُمْ ءَايَـٰتُ</span>... ﴾ [آل عمران : ١٠١]
وبالزيادة في ترتيب السور جاءت "<span style="color:red">وكيف</span>" بآل عمران بزيادة حرف الواو.','٢٨ كيف تكفرون بالله وكنتم اموتا البقره ٢٨، وكيف تكفرون وانتم تتلي عليكم ءايت ال عمران ١٠١ وبالزياده في ترتيب السور جاءت وكيف بال عمران بزياده حرف الواو',1);
INSERT INTO `mawadi3` (`mawdi_id`,`mawdi_number`,`surah_id`,`reference_text`,`start_page`,`end_page`,`plain_text`,`html_text`,`normalized_text`,`is_closed`) VALUES (29,29,2,NULL,5,5,'
[٢٩] ﴿ وَهُوَ بِكُلِّ خَلْقٍ عَلِيمٌ ﴾ [يس : ٧٩] الوحيدة وباقي المواضع ﴿ وَهُوَ بِكُلِّ شَىْءٍ عَلِيمٌ ﴾ [البقرة : ٢٩، الأنعام : ١٠١، الحديد : ٣]','
[٢٩] ﴿ وَهُوَ بِكُلِّ <span style="color:red">خَلْقٍ</span> عَلِيمٌ ﴾ [يس : ٧٩] الوحيدة وباقي المواضع ﴿ وَهُوَ بِكُلِّ <span style="color:red">شَىْءٍ</span> عَلِيمٌ ﴾ [البقرة : ٢٩، الأنعام : ١٠١، الحديد : ٣]','٢٩ وهو بكل خلق عليم يس ٧٩ الوحيده وباقي المواضع وهو بكل شيء عليم البقره ٢٩، الانعام ١٠١، الحديد ٣',1);
INSERT INTO `mawadi3` (`mawdi_id`,`mawdi_number`,`surah_id`,`reference_text`,`start_page`,`end_page`,`plain_text`,`html_text`,`normalized_text`,`is_closed`) VALUES (30,30,2,'ص : ٧١',5,5,'
[٣٠] ﴿ وَإِذْ قَالَ رَبُّكَ لِلْمَلَـٰٓئِكَةِ إِنِّى جَاعِلٌ فِى الْأَرْضِ... ﴾ [البقرة : ٣٠]
﴿ وَإِذْ قَالَ رَبُّكَ لِلْمَلَـٰٓئِكَةِ إِنِّى خَـٰلِقٌ بَشَرًا مِّن صَلْصَـٰلٍ مِّنْ حَمَإٍ مَّسْنُونٍ ﴾ [الحجر : ٢٨]
﴿ إِذْ قَالَ رَبُّكَ لِلْمَلَـٰٓئِكَةِ إِنِّى خَـٰلِقٌ بَشَرًا مِّن طِينٍ ﴾ [ص : ٧١]
ملحوظة: آية البقرة الوحيدة "إني جاعل في الأرض" وباقي المواضع "إني خالق بشرًا"، وآية ص الوحيدة بدون واو في أولها.','
[٣٠] ﴿ وَإِذْ قَالَ رَبُّكَ لِلْمَلَـٰٓئِكَةِ إِنِّى <span style="color:red">جَاعِلٌ فِى الْأَرْضِ</span>... ﴾ [البقرة : ٣٠]
﴿ وَإِذْ قَالَ رَبُّكَ لِلْمَلَـٰٓئِكَةِ إِنِّى <span style="color:red">خَـٰلِقٌ بَشَرًا مِّن صَلْصَـٰلٍ مِّنْ حَمَإٍ مَّسْنُونٍ</span> ﴾ [الحجر : ٢٨]
﴿ إِذْ قَالَ رَبُّكَ لِلْمَلَـٰٓئِكَةِ إِنِّى <span style="color:red">خَـٰلِقٌ بَشَرًا مِّن طِينٍ</span> ﴾ [ص : ٧١]
ملحوظة: آية البقرة الوحيدة "<span style="color:red">إني جاعل في الأرض</span>" وباقي المواضع "<span style="color:red">إني خالق بشرًا</span>"، وآية ص الوحيدة بدون واو في أولها.','٣٠ واذ قال ربك للملٓئكه اني جاعل في الارض البقره ٣٠ واذ قال ربك للملٓئكه اني خلق بشرا من صلصل من حما مسنون الحجر ٢٨ اذ قال ربك للملٓئكه اني خلق بشرا من طين ص ٧١ ملحوظه ايه البقره الوحيده اني جاعل في الارض وباقي المواضع اني خالق بشرا، وايه ص الوحيده بدون واو في اولها',0);
INSERT INTO `mawadi3` (`mawdi_id`,`mawdi_number`,`surah_id`,`reference_text`,`start_page`,`end_page`,`plain_text`,`html_text`,`normalized_text`,`is_closed`) VALUES (31,32,NULL,'المائدة : ١٠٩',6,6,'
﴿قَالُوا۟ سُبْحَٰنَكَ لَا عِلْمَ لَنَآ إِلَّا مَا عَلَّمْتَنَآ إِنَّكَ أَنتَ ٱلْعَلِيمُ ٱلْحَكِيمُ﴾ [البقرة : ٣٢]
﴿... قَالُوا۟ لَا عِلْمَ لَنَآ إِنَّكَ أَنتَ عَلَّٰمُ ٱلْغُيُوبِ﴾ [المائدة : ١٠٩]','
﴿قَالُوا۟ سُبْحَٰنَكَ لَا عِلْمَ لَنَآ إِلَّا مَا عَلَّمْتَنَآ <span style="color:red">إِنَّكَ أَنتَ</span> <span style="color:red">ٱلْعَلِيمُ ٱلْحَكِيمُ</span>﴾ [البقرة : ٣٢]
﴿... قَالُوا۟ لَا عِلْمَ لَنَآ <span style="color:red">إِنَّكَ أَنتَ</span> عَلَّٰمُ ٱلْغُيُوبِ﴾ [المائدة : ١٠٩]','قالوا۟ سبحنك لا علم لنآ الا ما علمتنآ انك انت ٱلعليم ٱلحكيم البقره ٣٢ قالوا۟ لا علم لنآ انك انت علم ٱلغيوب المائده ١٠٩',1);
INSERT INTO `mawadi3` (`mawdi_id`,`mawdi_number`,`surah_id`,`reference_text`,`start_page`,`end_page`,`plain_text`,`html_text`,`normalized_text`,`is_closed`) VALUES (32,32,NULL,NULL,6,6,'
﴿ٱلْعَلِيمُ ٱلْحَكِيمُ﴾ تكررت أربع مرات: [البقرة : ٣٢، يوسف : ٨٣، ١٠٠، التحريم : ٢] وباقي المواضع ﴿ٱلْعَزِيزُ ٱلْحَكِيمُ﴾ [تكررت ٢٩ مرة]','
﴿<span style="color:red">ٱلْعَلِيمُ ٱلْحَكِيمُ</span>﴾ تكررت أربع مرات: [البقرة : ٣٢، يوسف : ٨٣، ١٠٠، التحريم : ٢] وباقي المواضع ﴿<span style="color:red">ٱلْعَزِيزُ ٱلْحَكِيمُ</span>﴾ [تكررت ٢٩ مرة]','ٱلعليم ٱلحكيم تكررت اربع مرات البقره ٣٢، يوسف ٨٣، ١٠٠، التحريم ٢ وباقي المواضع ٱلعزيز ٱلحكيم تكررت ٢٩ مره',1);
INSERT INTO `mawadi3` (`mawdi_id`,`mawdi_number`,`surah_id`,`reference_text`,`start_page`,`end_page`,`plain_text`,`html_text`,`normalized_text`,`is_closed`) VALUES (33,33,NULL,NULL,6,6,'
﴿مَا تُبْدُونَ وَمَا كُنتُمْ تَكْتُمُونَ﴾ الوحيدة في القرآن وباقي المواضع ﴿مَا تُبْدُونَ وَمَا تَكْتُمُونَ﴾ [المائدة : ٩٩، النور : ٢٩]','
﴿مَا تُبْدُونَ وَمَا <span style="color:red">كُنتُمْ</span> <span style="color:red"><span style="color:red">تَكْتُمُونَ</span></span>﴾ الوحيدة في القرآن وباقي المواضع ﴿مَا تُبْدُونَ وَمَا <span style="color:red"><span style="color:red">تَكْتُمُونَ</span></span>﴾ [المائدة : ٩٩، النور : ٢٩]','ما تبدون وما كنتم تكتمون الوحيده في القران وباقي المواضع ما تبدون وما تكتمون المائده ٩٩، النور ٢٩',1);
INSERT INTO `mawadi3` (`mawdi_id`,`mawdi_number`,`surah_id`,`reference_text`,`start_page`,`end_page`,`plain_text`,`html_text`,`normalized_text`,`is_closed`) VALUES (34,34,NULL,'طه : ١١٦-١١٧',6,6,'
﴿وَإِذْ قُلْنَا لِلْمَلَٰٓئِكَةِ ٱسْجُدُوا۟ لَءَادَمَ فَسَجَدُوٓا۟ إِلَّآ إِبْلِيسَ أَبَىٰ وَٱسْتَكْبَرَ وَكَانَ مِنَ ٱلْكَٰفِرِينَ﴾ [البقرة : ٣٤]
﴿... ثُمَّ قُلْنَا لِلْمَلَٰٓئِكَةِ ٱسْجُدُوا۟ لَءَادَمَ فَسَجَدُوٓا۟ إِلَّآ إِبْلِيسَ لَمْ يَكُن مِّنَ ٱلسَّٰجِدِينَ﴾ [الأعراف : ١١]
﴿وَإِذْ قُلْنَا لِلْمَلَٰٓئِكَةِ ٱسْجُدُوا۟ لَءَادَمَ فَسَجَدُوٓا۟ إِلَّآ إِبْلِيسَ قَالَ أَءَسْجُدُ لِمَنْ خَلَقْتَ طِينًا﴾ [الإسراء : ٦١]
﴿وَإِذْ قُلْنَا لِلْمَلَٰٓئِكَةِ ٱسْجُدُوا۟ لَءَادَمَ فَسَجَدُوٓا۟ إِلَّآ إِبْلِيسَ كَانَ مِنَ ٱلْجِنِّ فَفَسَقَ عَنْ أَمْرِ رَبِّهِۦ ...﴾ [الكهف : ٥٠]
﴿وَإِذْ قُلْنَا لِلْمَلَٰٓئِكَةِ ٱسْجُدُوا۟ لَءَادَمَ فَسَجَدُوٓا۟ إِلَّآ إِبْلِيسَ أَبَىٰ ۝ فَقُلْنَا يَٰٓـَٔادَمُ إِنَّ هَٰذَا عَدُوٌّ لَّكَ ...﴾ [طه : ١١٦-١١٧]','
﴿وَإِذْ قُلْنَا لِلْمَلَٰٓئِكَةِ ٱسْجُدُوا۟ لَءَادَمَ فَسَجَدُوٓا۟ إِلَّآ إِبْلِيسَ <span style="color:red">أَبَىٰ وَٱسْتَكْبَرَ وَكَانَ مِنَ ٱلْكَٰفِرِينَ</span>﴾ [البقرة : ٣٤]
﴿... ثُمَّ قُلْنَا لِلْمَلَٰٓئِكَةِ ٱسْجُدُوا۟ لَءَادَمَ فَسَجَدُوٓا۟ إِلَّآ إِبْلِيسَ <span style="color:red">لَمْ يَكُن مِّنَ ٱلسَّٰجِدِينَ</span>﴾ [الأعراف : ١١]
﴿وَإِذْ قُلْنَا لِلْمَلَٰٓئِكَةِ ٱسْجُدُوا۟ لَءَادَمَ فَسَجَدُوٓا۟ إِلَّآ إِبْلِيسَ <span style="color:red">قَالَ أَءَسْجُدُ لِمَنْ خَلَقْتَ طِينًا</span>﴾ [الإسراء : ٦١]
﴿وَإِذْ قُلْنَا لِلْمَلَٰٓئِكَةِ ٱسْجُدُوا۟ لَءَادَمَ فَسَجَدُوٓا۟ إِلَّآ إِبْلِيسَ <span style="color:red">كَانَ مِنَ ٱلْجِنِّ فَفَسَقَ عَنْ أَمْرِ رَبِّهِۦ</span> ...﴾ [الكهف : ٥٠]
﴿وَإِذْ قُلْنَا لِلْمَلَٰٓئِكَةِ ٱسْجُدُوا۟ لَءَادَمَ فَسَجَدُوٓا۟ إِلَّآ إِبْلِيسَ أَبَىٰ ۝ <span style="color:red">فَقُلْنَا يَٰٓـَٔادَمُ إِنَّ هَٰذَا عَدُوٌّ لَّكَ</span> ...﴾ [طه : ١١٦-١١٧]','واذ قلنا للملٓئكه ٱسجدوا۟ لءادم فسجدوٓا۟ الآ ابليس ابي وٱستكبر وكان من ٱلكفرين البقره ٣٤ ثم قلنا للملٓئكه ٱسجدوا۟ لءادم فسجدوٓا۟ الآ ابليس لم يكن من ٱلسجدين الاعراف ١١ واذ قلنا للملٓئكه ٱسجدوا۟ لءادم فسجدوٓا۟ الآ ابليس قال اءسجد لمن خلقت طينا الاسراء ٦١ واذ قلنا للملٓئكه ٱسجدوا۟ لءادم فسجدوٓا۟ الآ ابليس كان من ٱلجن ففسق عن امر ربهۦ الكهف ٥٠ واذ قلنا للملٓئكه ٱسجدوا۟ لءادم فسجدوٓا۟ الآ ابليس ابي ۝ فقلنا يٓٔادم ان هذا عدو لك طه ١١٦١١٧',1);
INSERT INTO `mawadi3` (`mawdi_id`,`mawdi_number`,`surah_id`,`reference_text`,`start_page`,`end_page`,`plain_text`,`html_text`,`normalized_text`,`is_closed`) VALUES (35,34,NULL,'ص : ٧٤-٧٥',6,6,'
﴿... إِلَّآ إِبْلِيسَ أَبَىٰ وَٱسْتَكْبَرَ وَكَانَ مِنَ ٱلْكَٰفِرِينَ ۝ وَقُلْنَا يَٰٓـَٔادَمُ ٱسْكُنْ أَنتَ وَزَوْجُكَ ...﴾ [البقرة : ٣٤-٣٥]
﴿إِلَّآ إِبْلِيسَ ٱسْتَكْبَرَ وَكَانَ مِنَ ٱلْكَٰفِرِينَ ۝ قَالَ يَٰٓإِبْلِيسُ مَا مَنَعَكَ أَن تَسْجُدَ لِمَا خَلَقْتُ بِيَدَيَّ ...﴾ [ص : ٧٤-٧٥]','
﴿... إِلَّآ إِبْلِيسَ أَبَىٰ وَٱسْتَكْبَرَ وَكَانَ مِنَ ٱلْكَٰفِرِينَ ۝ <span style="color:red">وَقُلْنَا يَٰٓـَٔادَمُ ٱسْكُنْ أَنتَ وَزَوْجُكَ</span> ...﴾ [البقرة : ٣٤-٣٥]
﴿إِلَّآ إِبْلِيسَ ٱسْتَكْبَرَ وَكَانَ مِنَ ٱلْكَٰفِرِينَ ۝ <span style="color:red">قَالَ يَٰٓإِبْلِيسُ مَا مَنَعَكَ أَن تَسْجُدَ لِمَا خَلَقْتُ بِيَدَيَّ</span> ...﴾ [ص : ٧٤-٧٥]','الآ ابليس ابي وٱستكبر وكان من ٱلكفرين ۝ وقلنا يٓٔادم ٱسكن انت وزوجك البقره ٣٤٣٥ الآ ابليس ٱستكبر وكان من ٱلكفرين ۝ قال يٓابليس ما منعك ان تسجد لما خلقت بيدي ص ٧٤٧٥',1);
INSERT INTO `mawadi3` (`mawdi_id`,`mawdi_number`,`surah_id`,`reference_text`,`start_page`,`end_page`,`plain_text`,`html_text`,`normalized_text`,`is_closed`) VALUES (36,35,NULL,'طه : ١١٧',6,6,'
﴿وَقُلْنَا يَٰٓـَٔادَمُ ٱسْكُنْ أَنتَ وَزَوْجُكَ ٱلْجَنَّةَ وَكُلَا مِنْهَا رَغَدًا ...﴾ [البقرة : ٣٥]
﴿فَقُلْنَا يَٰٓـَٔادَمُ إِنَّ هَٰذَا عَدُوٌّ لَّكَ وَلِزَوْجِكَ فَلَا يُخْرِجَنَّكُمَا ...﴾ [طه : ١١٧]','
﴿<span style="color:red">وَقُلْنَا</span> يَٰٓـَٔادَمُ ٱسْكُنْ أَنتَ وَزَوْجُكَ ٱلْجَنَّةَ وَكُلَا مِنْهَا رَغَدًا ...﴾ [البقرة : ٣٥]
﴿<span style="color:red">فَقُلْنَا</span> يَٰٓـَٔادَمُ إِنَّ هَٰذَا عَدُوٌّ لَّكَ وَلِزَوْجِكَ فَلَا يُخْرِجَنَّكُمَا ...﴾ [طه : ١١٧]','وقلنا يٓٔادم ٱسكن انت وزوجك ٱلجنه وكلا منها رغدا البقره ٣٥ فقلنا يٓٔادم ان هذا عدو لك ولزوجك فلا يخرجنكما طه ١١٧',1);
INSERT INTO `mawadi3` (`mawdi_id`,`mawdi_number`,`surah_id`,`reference_text`,`start_page`,`end_page`,`plain_text`,`html_text`,`normalized_text`,`is_closed`) VALUES (37,35,NULL,'الأعراف : ١٩-٢٠',6,6,'
﴿وَقُلْنَا يَٰٓـَٔادَمُ ٱسْكُنْ أَنتَ وَزَوْجُكَ ٱلْجَنَّةَ وَكُلَا مِنْهَا رَغَدًا حَيْثُ شِئْتُمَا ... ۝ فَأَزَلَّهُمَا ٱلشَّيْطَٰنُ ...﴾ [البقرة : ٣٥-٣٦]، سورة البقرة أطول من سورة الأعراف، فكانت زيادة "وكلا منها رغدًا" في السورة الأطول –البقرة–.
﴿وَيَٰٓـَٔادَمُ ٱسْكُنْ أَنتَ وَزَوْجُكَ ٱلْجَنَّةَ فَكُلَا مِنْ حَيْثُ شِئْتُمَا ... ۝ فَوَسْوَسَ لَهُمَا ٱلشَّيْطَٰنُ ...﴾ [الأعراف : ١٩-٢٠]','
﴿وَقُلْنَا يَٰٓـَٔادَمُ ٱسْكُنْ أَنتَ وَزَوْجُكَ ٱلْجَنَّةَ وَكُلَا <span style="color:red">مِنْهَا رَغَدًا</span> حَيْثُ شِئْتُمَا ... ۝ <span style="color:red">فَأَزَلَّهُمَا ٱلشَّيْطَٰنُ</span> ...﴾ [البقرة : ٣٥-٣٦]، سورة البقرة أطول من سورة الأعراف، فكانت زيادة "<span style="color:red">وكلا منها رغدًا</span>" في السورة الأطول –البقرة–.
﴿وَيَٰٓـَٔادَمُ ٱسْكُنْ أَنتَ وَزَوْجُكَ ٱلْجَنَّةَ <span style="color:red">فَكُلَا</span> مِنْ حَيْثُ شِئْتُمَا ... ۝ <span style="color:red">فَوَسْوَسَ لَهُمَا ٱلشَّيْطَٰنُ</span> ...﴾ [الأعراف : ١٩-٢٠]','وقلنا يٓٔادم ٱسكن انت وزوجك ٱلجنه وكلا منها رغدا حيث شئتما ۝ فازلهما ٱلشيطن البقره ٣٥٣٦، سوره البقره اطول من سوره الاعراف، فكانت زياده وكلا منها رغدا في السوره الاطول البقره ويٓٔادم ٱسكن انت وزوجك ٱلجنه فكلا من حيث شئتما ۝ فوسوس لهما ٱلشيطن الاعراف ١٩٢٠',1);
INSERT INTO `mawadi3` (`mawdi_id`,`mawdi_number`,`surah_id`,`reference_text`,`start_page`,`end_page`,`plain_text`,`html_text`,`normalized_text`,`is_closed`) VALUES (38,35,NULL,NULL,6,6,'
﴿... وَكُلَا مِنْهَا رَغَدًا حَيْثُ شِئْتُمَا وَلَا تَقْرَبَا هَٰذِهِ ٱلشَّجَرَةَ ...﴾ [أول البقرة : ٣٥]، اربط بين واو "وكلا" وواو أول.
﴿... فَكُلُوا۟ مِنْهَا حَيْثُ شِئْتُمْ رَغَدًا وَٱدْخُلُوا۟ ٱلْبَابَ ...﴾ [ثاني البقرة : ٥٨]','
﴿... <span style="color:red">و</span>َكُلَا مِنْهَا <span style="color:red"><span style="color:red">رَغَدًا</span></span> حَيْثُ شِئْتُمَا <span style="color:red">و</span>َلَا تَقْرَبَا هَٰذِهِ ٱلشَّجَرَةَ ...﴾ [أ<span style="color:red">و</span>ل البقرة : ٣٥]، اربط بين <span style="color:red">و</span>ا<span style="color:red">و</span> "<span style="color:red">و</span>كلا" <span style="color:red">و</span><span style="color:red">و</span>ا<span style="color:red">و</span> أ<span style="color:red">و</span>ل.
﴿... فَكُلُ<span style="color:red">و</span>ا۟ مِنْهَا حَيْثُ شِئْتُمْ <span style="color:red"><span style="color:red">رَغَدًا</span></span> <span style="color:red">و</span>َٱدْخُلُ<span style="color:red">و</span>ا۟ ٱلْبَابَ ...﴾ [ثاني البقرة : ٥٨]','وكلا منها رغدا حيث شئتما ولا تقربا هذه ٱلشجره اول البقره ٣٥، اربط بين واو وكلا وواو اول فكلوا۟ منها حيث شئتم رغدا وٱدخلوا۟ ٱلباب ثاني البقره ٥٨',1);
INSERT INTO `mawadi3` (`mawdi_id`,`mawdi_number`,`surah_id`,`reference_text`,`start_page`,`end_page`,`plain_text`,`html_text`,`normalized_text`,`is_closed`) VALUES (39,36,NULL,NULL,6,6,'
﴿... وَقُلْنَا ٱهْبِطُوا۟ بَعْضُكُمْ لِبَعْضٍ عَدُوٌّ وَلَكُمْ فِي ٱلْأَرْضِ مُسْتَقَرٌّ وَمَتَٰعٌ إِلَىٰ حِينٍ ۝ فَتَلَقَّىٰٓ ءَادَمُ ...﴾ [البقرة : ٣٦-٣٧]
﴿قَالَ ٱهْبِطُوا۟ بَعْضُكُمْ لِبَعْضٍ عَدُوٌّ وَلَكُمْ فِي ٱلْأَرْضِ مُسْتَقَرٌّ وَمَتَٰعٌ إِلَىٰ حِينٍ ۝ قَالَ فِيهَا تَحْيَوْنَ ...﴾ [الأعراف : ٢٤-٢٥]
﴿قَالَ ٱهْبِطَا مِنْهَا جَمِيعًا بَعْضُكُمْ لِبَعْضٍ عَدُوٌّ فَإِمَّا يَأْتِيَنَّكُم ...﴾ [طه : ١٢٣]، ملحوظة: آية طه الوحيدة بزيادة "منها جميعًا".','
﴿... <span style="color:red">وَقُلْنَا</span> ٱهْبِطُوا۟ بَعْضُكُمْ لِبَعْضٍ عَدُوٌّ وَلَكُمْ فِي ٱلْأَرْضِ مُسْتَقَرٌّ وَمَتَٰعٌ إِلَىٰ حِينٍ ۝ <span style="color:red">فَتَلَقَّىٰٓ ءَادَمُ</span> ...﴾ [البقرة : ٣٦-٣٧]
﴿<span style="color:red">قَالَ</span> ٱهْبِطُوا۟ بَعْضُكُمْ لِبَعْضٍ عَدُوٌّ وَلَكُمْ فِي ٱلْأَرْضِ مُسْتَقَرٌّ وَمَتَٰعٌ إِلَىٰ حِينٍ ۝ <span style="color:red">قَالَ</span> فِيهَا تَحْيَوْنَ ...﴾ [الأعراف : ٢٤-٢٥]
﴿<span style="color:red">قَالَ</span> ٱهْبِطَا مِنْهَا <span style="color:red">جَمِيعًا</span> بَعْضُكُمْ لِبَعْضٍ عَدُوٌّ <span style="color:red">فَإِمَّا يَأْتِيَنَّكُم</span> ...﴾ [طه : ١٢٣]، ملحوظة: آية طه الوحيدة بزيادة "<span style="color:red">منها جميعًا</span>".','وقلنا ٱهبطوا۟ بعضكم لبعض عدو ولكم في ٱلارض مستقر ومتع الي حين ۝ فتلقيٓ ءادم البقره ٣٦٣٧ قال ٱهبطوا۟ بعضكم لبعض عدو ولكم في ٱلارض مستقر ومتع الي حين ۝ قال فيها تحيون الاعراف ٢٤٢٥ قال ٱهبطا منها جميعا بعضكم لبعض عدو فاما ياتينكم طه ١٢٣، ملحوظه ايه طه الوحيده بزياده منها جميعا',1);
INSERT INTO `mawadi3` (`mawdi_id`,`mawdi_number`,`surah_id`,`reference_text`,`start_page`,`end_page`,`plain_text`,`html_text`,`normalized_text`,`is_closed`) VALUES (40,'٣٨,٣٦',NULL,'ثاني البقرة : ٣٨',7,7,'
﴿ ... وَقُلْنَا أَهْبِطُواْ بَعْضُكُمْ ... ﴾ [أول البقرة : ٣٦]
﴿ قُلْنَا أَهْبِطُواْ مِنْهَا جَمِيعاً فَإِمَّا ... ﴾ [ثاني البقرة : ٣٨]','
﴿ ... وَقُلْنَا أَهْبِطُواْ <span style="color:red">بَعْضُكُمْ</span> ... ﴾ [أول البقرة : ٣٦]
﴿ قُلْنَا أَهْبِطُواْ <span style="color:red">مِنْهَا جَمِيعاً فَإِمَّا</span> ... ﴾ [ثاني البقرة : ٣٨]','وقلنا اهبطوا بعضكم اول البقره ٣٦ قلنا اهبطوا منها جميعا فاما ثاني البقره ٣٨',1);
INSERT INTO `mawadi3` (`mawdi_id`,`mawdi_number`,`surah_id`,`reference_text`,`start_page`,`end_page`,`plain_text`,`html_text`,`normalized_text`,`is_closed`) VALUES (41,'٣٨',NULL,'طه : ١٢٣',7,7,'
﴿ ... فَمَن تَبِعَ هُدَايَ فَلَا خَوْفٌ عَلَيْهِمْ ... ﴾ [البقرة : ٣٨]
﴿ ... فَمَنِ اتَّبَعَ هُدَايَ فَلَا يَضِلُّ ... ﴾ [طه : ١٢٣]
وبالزيادة في ترتيب السور جاءت "اتبع" بطه بزيادة حرف همزة الوصل.','
﴿ ... فَمَن <span style="color:red">تَبِعَ</span> هُدَايَ فَلَا <span style="color:red">خَوْفٌ عَلَيْهِمْ</span> ... ﴾ [البقرة : ٣٨]
﴿ ... فَمَنِ <span style="color:red">اتَّبَعَ</span> هُدَايَ فَلَا <span style="color:red">يَضِلُّ</span> ... ﴾ [طه : ١٢٣]
وبالزيادة في ترتيب السور جاءت "اتبع" بطه بزيادة حرف همزة الوصل.','فمن تبع هداي فلا خوف عليهم البقره ٣٨ فمن اتبع هداي فلا يضل طه ١٢٣ وبالزياده في ترتيب السور جاءت اتبع بطه بزياده حرف همزه الوصل',1);
INSERT INTO `mawadi3` (`mawdi_id`,`mawdi_number`,`surah_id`,`reference_text`,`start_page`,`end_page`,`plain_text`,`html_text`,`normalized_text`,`is_closed`) VALUES (42,'٣٩',NULL,'الروم : ١٦',7,7,'
﴿ وَالَّذِينَ كَفَرُواْ وَكَذَّبُواْ بِآيَاتِنَا أُولَـئِكَ أَصْحَابُ النَّارِ هُمْ فِيهَا خَالِدُونَ ﴾ [البقرة : ٣٩]
﴿ وَالَّذِينَ كَفَرُوا وَكَذَّبُوا بِآيَاتِنَا أُولَئِكَ أَصْحَابُ النَّارِ خَالِدِينَ فِيهَا وَبِئْسَ الْمَصِيرُ ﴾ [التغابن : ١٠]
﴿ وَالَّذِينَ كَفَرُوا وَكَذَّبُوا بِآيَاتِنَا أُولَئِكَ أَصْحَابُ الْجَحِيمِ ﴾ [المائدة : ١٠ ، ٨٦، الحديد : ١٩]
﴿ وَالَّذِينَ كَفَرُوا وَكَذَّبُوا بِآيَاتِنَا فَأُوْلَئِكَ لَهُمْ عَذَابٌ مُّهِينٌ ﴾ [الحج : ٥٧]
﴿ وَأَمَّا الَّذِينَ كَفَرُوا وَكَذَّبُوا بِآيَاتِنَا وَلِقَاءِ الْآخِرَةِ... ﴾ [الروم : ١٦]
﴿ الَّذِينَ كَفَرُوا وَكَذَّبُوا بِآيَاتِنَا ﴾ تكررت سبع مرات، ملحوظة: آية الروم الوحيدة بزيادة "أَمَّا".','
﴿ وَالَّذِينَ كَفَرُواْ وَكَذَّبُواْ بِآيَاتِنَا أُولَـئِكَ أَصْحَابُ النَّارِ <span style="color:red">هُمْ</span> فِيهَا <span style="color:red">خَالِدُونَ</span> ﴾ [البقرة : ٣٩]
﴿ وَالَّذِينَ كَفَرُوا وَكَذَّبُوا بِآيَاتِنَا أُولَئِكَ أَصْحَابُ النَّارِ <span style="color:red">خَالِدِينَ</span> فِيهَا <span style="color:red">وَبِئْسَ الْمَصِيرُ</span> ﴾ [التغابن : ١٠]
﴿ وَالَّذِينَ كَفَرُوا وَكَذَّبُوا بِآيَاتِنَا أُولَئِكَ <span style="color:red">أَصْحَابُ الْجَحِيمِ</span> ﴾ [المائدة : ١٠ ، ٨٦، الحديد : ١٩]
﴿ وَالَّذِينَ كَفَرُوا وَكَذَّبُوا بِآيَاتِنَا فَأُوْلَئِكَ لَ<span style="color:red">هُمْ</span> عَذَابٌ مُّهِينٌ ﴾ [الحج : ٥٧]
﴿ <span style="color:red">وَ<span style="color:red">أَمَّا</span></span> الَّذِينَ كَفَرُوا وَكَذَّبُوا بِآيَاتِنَا <span style="color:red">وَلِقَاءِ الْآخِرَةِ</span>... ﴾ [الروم : ١٦]
﴿ الَّذِينَ كَفَرُوا وَكَذَّبُوا بِآيَاتِنَا ﴾ تكررت سبع مرات، ملحوظة: آية الروم الوحيدة بزيادة "<span style="color:red">أَمَّا</span>".','والذين كفروا وكذبوا باياتنا اولئك اصحاب النار هم فيها خالدون البقره ٣٩ والذين كفروا وكذبوا باياتنا اولئك اصحاب النار خالدين فيها وبئس المصير التغابن ١٠ والذين كفروا وكذبوا باياتنا اولئك اصحاب الجحيم المائده ١٠ ، ٨٦، الحديد ١٩ والذين كفروا وكذبوا باياتنا فاولئك لهم عذاب مهين الحج ٥٧ واما الذين كفروا وكذبوا باياتنا ولقاء الاخره الروم ١٦ الذين كفروا وكذبوا باياتنا تكررت سبع مرات، ملحوظه ايه الروم الوحيده بزياده اما',1);
INSERT INTO `mawadi3` (`mawdi_id`,`mawdi_number`,`surah_id`,`reference_text`,`start_page`,`end_page`,`plain_text`,`html_text`,`normalized_text`,`is_closed`) VALUES (43,'٤٧-٤٩،٤٠',NULL,'طه : ٨٠',7,7,'
﴿ يٰبَنِي إِسْرَٰءِيلَ أذْكُرُوا نِعْمَتِيَ الَّتِي أَنْعَمْتُ عَلَيْكُمْ وَأَوْفُواْ بِعَهْدِي أُوفِ بِعَهْدِكُمْ ... ﴾ [أول البقرة : ٤٠]
﴿ يٰبَنِي إِسْرَٰءِيلَ أذْكُرُوا نِعْمَتِيَ الَّتِي أَنْعَمْتُ عَلَيْكُمْ وَأَنِّي فَضَّلْتُكُمْ عَلَى الْعَٰلَمِينَ ﴿٤٧﴾ وَاتَّقُوا يَوْمًا لَّا تَجْزِي نَفْسٌ عَن نَّفْسٍ شَيْئًا وَلَا يُقْبَلُ مِنْهَا شَفٰعَةٌ وَلَا يُؤْخَذُ مِنْهَا عَدْلٌ وَلَا هُمْ يُنصَرُونَ ﴿٤٨﴾ وَإِذْ نَجَّيْنٰكُم ... ﴾ [ثاني البقرة : ٤٧-٤٩]
﴿ يٰبَنِي إِسْرَٰءِيلَ أذْكُرُوا نِعْمَتِيَ الَّتِي أَنْعَمْتُ عَلَيْكُمْ وَأَنِّي فَضَّلْتُكُمْ عَلَى الْعَٰلَمِينَ ﴿١٢٢﴾ وَاتَّقُوا يَوْمًا لَّا تَجْزِي نَفْسٌ عَن نَّفْسٍ شَيْئًا وَلَا يُقْبَلُ مِنْهَا عَدْلٌ وَلَا تَنفَعُهَا شَفٰعَةٌ وَلَا هُمْ يُنصَرُونَ ﴿١٢٣﴾ وَإِذِ ابْتَلَىٰ إِبْرَٰهِيمَ رَبُّهُۥ ... ﴾ [ثالث البقرة : ١٢٢-١٢٤]
﴿ يٰبَنِي إِسْرَٰءِيلَ قَدْ أَنجَيْنٰكُم مِّنْ عَدُوِّكُمْ وَوَٰعَدْنٰكُمْ جَانِبَ الطُّورِ الْأَيْمَنَ وَنَزَّلْنَا عَلَيْكُمُ الْمَنَّ وَالسَّلْوَىٰ ﴾ [طه : ٨٠]
ملحوظة: آية البقرة الأولى الوحيدة "نعمتي التي أنعمت عليكم وأوفوا بعهدي" وباقي المواضع "عليكم وأني فضلتكم".','
﴿ يٰبَنِي إِسْرَٰءِيلَ أذْكُرُوا نِعْمَتِيَ الَّتِي أَنْعَمْتُ عَلَيْكُمْ <span style="color:red">وَأَوْفُواْ بِعَهْدِي أُوفِ بِعَهْدِكُمْ</span> ... ﴾ [أول البقرة : ٤٠]
﴿ يٰبَنِي إِسْرَٰءِيلَ أذْكُرُوا نِعْمَتِيَ الَّتِي أَنْعَمْتُ عَلَيْكُمْ <span style="color:red"><span style="color:red">وَأَنِّي فَضَّلْتُكُمْ عَلَى الْعَٰلَمِينَ</span></span> ﴿٤٧﴾ وَاتَّقُوا يَوْمًا لَّا تَجْزِي نَفْسٌ عَن نَّفْسٍ شَيْئًا وَلَا يُقْبَلُ مِنْهَا <span style="color:red"><span style="color:red">شَفٰعَةٌ</span></span> وَلَا يُؤْخَذُ مِنْهَا <span style="color:red"><span style="color:red">عَدْلٌ</span></span> وَلَا هُمْ يُنصَرُونَ ﴿٤٨﴾ <span style="color:red">وَإِذْ نَجَّيْنٰكُم</span> ... ﴾ [ثاني البقرة : ٤٧-٤٩]
﴿ يٰبَنِي إِسْرَٰءِيلَ أذْكُرُوا نِعْمَتِيَ الَّتِي أَنْعَمْتُ عَلَيْكُمْ <span style="color:red"><span style="color:red">وَأَنِّي فَضَّلْتُكُمْ عَلَى الْعَٰلَمِينَ</span></span> ﴿١٢٢﴾ وَاتَّقُوا يَوْمًا لَّا تَجْزِي نَفْسٌ عَن نَّفْسٍ شَيْئًا وَلَا يُقْبَلُ مِنْهَا <span style="color:red"><span style="color:red">عَدْلٌ</span></span> وَلَا تَنفَعُهَا <span style="color:red"><span style="color:red">شَفٰعَةٌ</span></span> وَلَا هُمْ يُنصَرُونَ ﴿١٢٣﴾ <span style="color:red">وَإِذِ ابْتَلَىٰ إِبْرَٰهِيمَ رَبُّهُۥ</span> ... ﴾ [ثالث البقرة : ١٢٢-١٢٤]
﴿ يٰبَنِي إِسْرَٰءِيلَ <span style="color:red">قَدْ أَنجَيْنٰكُم مِّنْ عَدُوِّكُمْ وَوَٰعَدْنٰكُمْ جَانِبَ الطُّورِ الْأَيْمَنَ وَنَزَّلْنَا عَلَيْكُمُ الْمَنَّ وَالسَّلْوَىٰ</span> ﴾ [طه : ٨٠]
ملحوظة: آية البقرة الأولى الوحيدة "<span style="color:red">نعمتي التي أنعمت عليكم وأوفوا بعهدي</span>" وباقي المواضع "<span style="color:red">عليكم وأني فضلتكم</span>".','يبني اسرءيل اذكروا نعمتي التي انعمت عليكم واوفوا بعهدي اوف بعهدكم اول البقره ٤٠ يبني اسرءيل اذكروا نعمتي التي انعمت عليكم واني فضلتكم علي العلمين ٤٧ واتقوا يوما لا تجزي نفس عن نفس شيئا ولا يقبل منها شفعه ولا يؤخذ منها عدل ولا هم ينصرون ٤٨ واذ نجينكم ثاني البقره ٤٧٤٩ يبني اسرءيل اذكروا نعمتي التي انعمت عليكم واني فضلتكم علي العلمين ١٢٢ واتقوا يوما لا تجزي نفس عن نفس شيئا ولا يقبل منها عدل ولا تنفعها شفعه ولا هم ينصرون ١٢٣ واذ ابتلي ابرهيم ربهۥ ثالث البقره ١٢٢١٢٤ يبني اسرءيل قد انجينكم من عدوكم ووعدنكم جانب الطور الايمن ونزلنا عليكم المن والسلوي طه ٨٠ ملحوظه ايه البقره الاولي الوحيده نعمتي التي انعمت عليكم واوفوا بعهدي وباقي المواضع عليكم واني فضلتكم',1);
INSERT INTO `mawadi3` (`mawdi_id`,`mawdi_number`,`surah_id`,`reference_text`,`start_page`,`end_page`,`plain_text`,`html_text`,`normalized_text`,`is_closed`) VALUES (44,'٤١،٤٠',NULL,'العنكبوت : ٥٦',7,7,'
﴿ ... أُوفِ بِعَهْدِكُمْ وَإِيَّٰيَ فَٱرْهَبُونِ ﴾ [أول البقرة : ٤٠]
﴿ ... وَلَا تَشْتَرُواْ بِـَٔايَٰتِي ثَمَنًا قَلِيلًا وَإِيَّٰيَ فَٱتَّقُونِ ﴾ [ثاني البقرة : ٤١]، اربط بين قاف "قَلِيلًا" وقاف "فَاتَّقُونِ".
﴿ ... إِنَّمَا هُوَ إِلَٰهٌ وَٰحِدٌ فَإِيَّٰيَ فَٱرْهَبُونِ ﴾ [النحل : ٥١] ، ﴿ ... إِنَّ أَرْضِي وَٰسِعَةٌ فَإِيَّٰيَ فَٱعْبُدُونِ ﴾ [العنكبوت : ٥٦]','
﴿ ... أُوفِ بِعَهْدِكُمْ وَإِيَّٰيَ <span style="color:red"><span style="color:red">فَٱرْهَبُونِ</span></span> ﴾ [أول البقرة : ٤٠]
﴿ ... وَلَا تَشْتَرُواْ بِـَٔايَٰتِي ثَمَنًا <span style="color:red"><span style="color:red">قَلِيلًا</span></span> وَإِيَّٰيَ <span style="color:red">فَٱتَّقُونِ</span> ﴾ [ثاني البقرة : ٤١]، اربط بين قاف "<span style="color:red"><span style="color:red">قَلِيلًا</span></span>" وقاف "<span style="color:red">فَاتَّقُونِ</span>".
﴿ ... إِنَّمَا هُوَ إِلَٰهٌ وَٰحِدٌ فَإِيَّٰيَ <span style="color:red"><span style="color:red">فَٱرْهَبُونِ</span></span> ﴾ [النحل : ٥١] ، ﴿ ... إِنَّ أَرْضِي وَٰسِعَةٌ فَإِيَّٰيَ <span style="color:red">فَٱعْبُدُونِ</span> ﴾ [العنكبوت : ٥٦]','اوف بعهدكم وايي فٱرهبون اول البقره ٤٠ ولا تشتروا بٔايتي ثمنا قليلا وايي فٱتقون ثاني البقره ٤١، اربط بين قاف قليلا وقاف فاتقون انما هو اله وحد فايي فٱرهبون النحل ٥١ ، ان ارضي وسعه فايي فٱعبدون العنكبوت ٥٦',1);
INSERT INTO `mawadi3` (`mawdi_id`,`mawdi_number`,`surah_id`,`reference_text`,`start_page`,`end_page`,`plain_text`,`html_text`,`normalized_text`,`is_closed`) VALUES (45,'٤٣',NULL,'النور : ٥٦',7,7,'
﴿ وَأَقِيمُواْ الصَّلَٰوةَ وَءَاتُواْ الزَّكَٰوةَ وَارْكَعُواْ مَعَ الرَّٰكِعِينَ ﴾ [أول البقرة : ٤٣]
﴿ وَأَقِيمُواْ الصَّلَٰوةَ وَءَاتُواْ الزَّكَٰوةَ وَمَا تُقَدِّمُواْ لِأَنفُسِكُم مِّنْ خَيْرٍ تَجِدُوهُ عِندَ اللَّهِ ... ﴾ [ثاني البقرة : ١١٠]
﴿ وَأَقِيمُواْ الصَّلَٰوةَ وَءَاتُواْ الزَّكَٰوةَ وَأَطِيعُواْ الرَّسُولَ لَعَلَّكُمْ تُرْحَمُونَ ﴾ [النور : ٥٦]، هذه المواضع خاصة ببدايات الآيات.','
﴿ وَأَقِيمُواْ الصَّلَٰوةَ وَءَاتُواْ الزَّكَٰوةَ <span style="color:red">وَارْكَعُواْ مَعَ الرَّٰكِعِينَ</span> ﴾ [أول البقرة : ٤٣]
﴿ وَأَقِيمُواْ الصَّلَٰوةَ وَءَاتُواْ الزَّكَٰوةَ <span style="color:red">وَمَا تُقَدِّمُواْ لِأَنفُسِكُم مِّنْ خَيْرٍ تَجِدُوهُ عِندَ اللَّهِ ...</span> ﴾ [ثاني البقرة : ١١٠]
﴿ وَأَقِيمُواْ الصَّلَٰوةَ وَءَاتُواْ الزَّكَٰوةَ <span style="color:red">وَأَطِيعُواْ الرَّسُولَ لَعَلَّكُمْ تُرْحَمُونَ</span> ﴾ [النور : ٥٦]، هذه المواضع خاصة ببدايات الآيات.','واقيموا الصلوه وءاتوا الزكوه واركعوا مع الركعين اول البقره ٤٣ واقيموا الصلوه وءاتوا الزكوه وما تقدموا لانفسكم من خير تجدوه عند الله ثاني البقره ١١٠ واقيموا الصلوه وءاتوا الزكوه واطيعوا الرسول لعلكم ترحمون النور ٥٦، هذه المواضع خاصه ببدايات الايات',1);
INSERT INTO `mawadi3` (`mawdi_id`,`mawdi_number`,`surah_id`,`reference_text`,`start_page`,`end_page`,`plain_text`,`html_text`,`normalized_text`,`is_closed`) VALUES (46,'٤٥',NULL,'ثاني البقرة : ١٥٣',7,7,'
﴿ وَاسْتَعِينُواْ بِالصَّبْرِ وَالصَّلَٰوةِ وَإِنَّهَا لَكَبِيرَةٌ ... ﴾ [أول البقرة : ٤٥]، اربط بين واو "وَإِنَّهَا" وواو أُوَّل.
﴿ يٰأَيُّهَا الَّذِينَ ءَامَنُواْ اسْتَعِينُواْ بِالصَّبْرِ وَالصَّلَٰوةِ إِنَّ اللَّهَ مَعَ الصَّٰبِرِينَ ﴾ [ثاني البقرة : ١٥٣]','
﴿ وَاسْتَعِينُواْ بِالصَّبْرِ وَالصَّلَٰوةِ <span style="color:red"><span style="color:red">وَإِنَّهَا</span> لَكَبِيرَةٌ</span> ... ﴾ [أول البقرة : ٤٥]، اربط بين واو "<span style="color:red">وَإِنَّهَا</span>" وواو <span style="color:red">أُوَّل</span>.
﴿ يٰأَيُّهَا الَّذِينَ ءَامَنُواْ اسْتَعِينُواْ بِالصَّبْرِ وَالصَّلَٰوةِ <span style="color:red">إِنَّ اللَّهَ مَعَ الصَّٰبِرِينَ</span> ﴾ [ثاني البقرة : ١٥٣]','واستعينوا بالصبر والصلوه وانها لكبيره اول البقره ٤٥، اربط بين واو وانها وواو اول يايها الذين ءامنوا استعينوا بالصبر والصلوه ان الله مع الصبرين ثاني البقره ١٥٣',1);
INSERT INTO `mawadi3` (`mawdi_id`,`mawdi_number`,`surah_id`,`reference_text`,`start_page`,`end_page`,`plain_text`,`html_text`,`normalized_text`,`is_closed`) VALUES (47,49,NULL,'إبراهيم: ٦-٧',8,8,'
[٤٩] ﴿ وَإِذْ نَجَّيْنٰكُم مِّنْ ءَالِ فِرْعَوْنَ يَسُومُونَكُمْ سُوٓءَ ٱلْعَذَابِ يُذَبِّحُونَ أَبْنَاءَكُمْ وَيَسْتَحْيُونَ نِسَاءَكُمْ وَفِي ذٰلِكُم بَلَاءٌ مِّن رَّبِّكُمْ عَظِيمٌ ﴿٤٩﴾ وَإِذْ فَرَقْنَا بِكُمُ... ﴾ [البقرة: ٤٩-٥٠]
﴿ وَإِذْ أَنجَيْنٰكُم مِّنْ ءَالِ فِرْعَوْنَ يَسُومُونَكُمْ سُوٓءَ ٱلْعَذَابِ يُقَتِّلُونَ أَبْنَاءَكُمْ وَيَسْتَحْيُونَ نِسَاءَكُمْ وَفِي ذٰلِكُم بَلَاءٌ مِّن رَّبِّكُمْ عَظِيمٌ ﴿١٤١﴾ وَوَٰعَدْنَا... ﴾ [الأعراف: ١٤١-١٤٢]
﴿ ... إِذْ أَنجَيٰكُم مِّنْ ءَالِ فِرْعَوْنَ يَسُومُونَكُمْ سُوٓءَ ٱلْعَذَابِ وَيُذَبِّحُونَ أَبْنَاءَكُمْ وَيَسْتَحْيُونَ نِسَاءَكُمْ وَفِي ذٰلِكُم بَلَاءٌ مِّن رَّبِّكُمْ عَظِيمٌ ﴿٦﴾ وَإِذْ تَأَذَّنَ ... ﴾ [إبراهيم: ٦-٧]
ملحوظة: آية البقرة "نجيناكم" بدون همزة، وآية الأعراف الوحيدة "يقتلون" وباقي المواضع "يذبحون"، وآية إبراهيم الوحيدة "ويذبحون" بزيادة حرف الواو.','
[٤٩] ﴿ وَإِذْ <span style="color:red">نَجَّيْنٰكُم</span> مِّنْ ءَالِ فِرْعَوْنَ يَسُومُونَكُمْ سُوٓءَ ٱلْعَذَابِ <span style="color:red">يُذَبِّحُونَ</span> أَبْنَاءَكُمْ وَيَسْتَحْيُونَ نِسَاءَكُمْ وَفِي ذٰلِكُم بَلَاءٌ مِّن رَّبِّكُمْ عَظِيمٌ ﴿٤٩﴾ <span style="color:red">وَإِذْ فَرَقْنَا بِكُمُ...</span> ﴾ [البقرة: ٤٩-٥٠]
﴿ وَإِذْ <span style="color:red">أَنجَيْنٰكُم</span> مِّنْ ءَالِ فِرْعَوْنَ يَسُومُونَكُمْ سُوٓءَ ٱلْعَذَابِ <span style="color:red">يُقَتِّلُونَ</span> أَبْنَاءَكُمْ وَيَسْتَحْيُونَ نِسَاءَكُمْ وَفِي ذٰلِكُم بَلَاءٌ مِّن رَّبِّكُمْ عَظِيمٌ ﴿١٤١﴾ <span style="color:red">وَوَٰعَدْنَا...</span> ﴾ [الأعراف: ١٤١-١٤٢]
﴿ ... إِذْ <span style="color:red">أَنجَيٰكُم</span> مِّنْ ءَالِ فِرْعَوْنَ يَسُومُونَكُمْ سُوٓءَ ٱلْعَذَابِ وَ<span style="color:red">يُذَبِّحُونَ</span> أَبْنَاءَكُمْ وَيَسْتَحْيُونَ نِسَاءَكُمْ وَفِي ذٰلِكُم بَلَاءٌ مِّن رَّبِّكُمْ عَظِيمٌ ﴿٦﴾ <span style="color:red">وَإِذْ تَأَذَّنَ ...</span> ﴾ [إبراهيم: ٦-٧]
ملحوظة: آية البقرة "<span style="color:red">نجيناكم</span>" بدون همزة، وآية الأعراف الوحيدة "<span style="color:red">يقتلون</span>" وباقي المواضع "<span style="color:red">يذبحون</span>"، وآية إبراهيم الوحيدة "و<span style="color:red">يذبحون</span>" بزيادة حرف الواو.','٤٩ واذ نجينكم من ءال فرعون يسومونكم سوٓء ٱلعذاب يذبحون ابناءكم ويستحيون نساءكم وفي ذلكم بلاء من ربكم عظيم ٤٩ واذ فرقنا بكم البقره ٤٩٥٠ واذ انجينكم من ءال فرعون يسومونكم سوٓء ٱلعذاب يقتلون ابناءكم ويستحيون نساءكم وفي ذلكم بلاء من ربكم عظيم ١٤١ ووعدنا الاعراف ١٤١١٤٢ اذ انجيكم من ءال فرعون يسومونكم سوٓء ٱلعذاب ويذبحون ابناءكم ويستحيون نساءكم وفي ذلكم بلاء من ربكم عظيم ٦ واذ تاذن ابراهيم ٦٧ ملحوظه ايه البقره نجيناكم بدون همزه، وايه الاعراف الوحيده يقتلون وباقي المواضع يذبحون، وايه ابراهيم الوحيده ويذبحون بزياده حرف الواو',1);
INSERT INTO `mawadi3` (`mawdi_id`,`mawdi_number`,`surah_id`,`reference_text`,`start_page`,`end_page`,`plain_text`,`html_text`,`normalized_text`,`is_closed`) VALUES (48,51,NULL,'الأعراف: ١٤٢',8,8,'
[٥١] ﴿ وَإِذْ وَٰعَدْنَا مُوسَىٰ أَرْبَعِينَ لَيْلَةً ثُمَّ ٱتَّخَذْتُمُ ... ﴾ [البقرة: ٥١]
﴿ وَوَٰعَدْنَا مُوسَىٰ ثَلٰثِينَ لَيْلَةً وَأَتْمَمْنٰهَا بِعَشْرٍ فَتَمَّ مِيقٰتُ رَبِّهِۦٓ أَرْبَعِينَ لَيْلَةً وَقَالَ مُوسَىٰ ... ﴾ [الأعراف: ١٤٢]
وبالزيادة في ترتيب السور جاءت آية الأعراف زائدة في كلماتها في قوله: "ثلاثين ليلة وأتممناها ... " فانتبه لها.','
[٥١] ﴿ <span style="color:red">وَإِذْ وَٰعَدْنَا مُوسَىٰ أَرْبَعِينَ لَيْلَةً ثُمَّ ٱتَّخَذْتُمُ ...</span> ﴾ [البقرة: ٥١]
﴿ <span style="color:red">وَوَٰعَدْنَا مُوسَىٰ ثَلٰثِينَ لَيْلَةً وَأَتْمَمْنٰهَا بِعَشْرٍ فَتَمَّ مِيقٰتُ رَبِّهِۦٓ</span> أَرْبَعِينَ لَيْلَةً وَقَالَ مُوسَىٰ ... ﴾ [الأعراف: ١٤٢]
وبالزيادة في ترتيب السور جاءت آية الأعراف زائدة في كلماتها في قوله: "<span style="color:red">ثلاثين ليلة وأتممناها ... </span>" فانتبه لها.','٥١ واذ وعدنا موسي اربعين ليله ثم ٱتخذتم البقره ٥١ ووعدنا موسي ثلثين ليله واتممنها بعشر فتم ميقت ربهۦٓ اربعين ليله وقال موسي الاعراف ١٤٢ وبالزياده في ترتيب السور جاءت ايه الاعراف زائده في كلماتها في قوله ثلاثين ليله واتممناها فانتبه لها',1);
INSERT INTO `mawadi3` (`mawdi_id`,`mawdi_number`,`surah_id`,`reference_text`,`start_page`,`end_page`,`plain_text`,`html_text`,`normalized_text`,`is_closed`) VALUES (49,51,NULL,'ثاني البقرة : ٩٢-٩٣',8,8,'
[٥١] ﴿ ... ثُمَّ ٱتَّخَذْتُمُ ٱلْعِجْلَ مِنْ بَعْدِهِۦ وَأَنْتُمْ ظٰلِمُونَ ﴿٥١﴾ ثُمَّ عَفَوْنَا عَنْكُمْ ... ﴾ [أول البقرة : ٥١-٥٢]
﴿ ... ثُمَّ ٱتَّخَذْتُمُ ٱلْعِجْلَ مِنْ بَعْدِهِۦ وَأَنْتُمْ ظٰلِمُونَ ﴿٥١﴾ وَإِذْ أَخَذْنَا مِيثٰقَكُمْ وَرَفَعْنَا ... ﴾ [ثاني البقرة : ٩٢-٩٣]','
[٥١] ﴿ ... ثُمَّ ٱتَّخَذْتُمُ ٱلْعِجْلَ مِنْ بَعْدِهِۦ وَأَنْتُمْ ظٰلِمُونَ ﴿٥١﴾ <span style="color:red">ثُمَّ عَفَوْنَا عَنْكُمْ ...</span> ﴾ [أول البقرة : ٥١-٥٢]
﴿ ... ثُمَّ ٱتَّخَذْتُمُ ٱلْعِجْلَ مِنْ بَعْدِهِۦ وَأَنْتُمْ ظٰلِمُونَ ﴿٥١﴾ <span style="color:red">وَإِذْ أَخَذْنَا مِيثٰقَكُمْ وَرَفَعْنَا ...</span> ﴾ [ثاني البقرة : ٩٢-٩٣]','٥١ ثم ٱتخذتم ٱلعجل من بعدهۦ وانتم ظلمون ٥١ ثم عفونا عنكم اول البقره ٥١٥٢ ثم ٱتخذتم ٱلعجل من بعدهۦ وانتم ظلمون ٥١ واذ اخذنا ميثقكم ورفعنا ثاني البقره ٩٢٩٣',1);
INSERT INTO `mawadi3` (`mawdi_id`,`mawdi_number`,`surah_id`,`reference_text`,`start_page`,`end_page`,`plain_text`,`html_text`,`normalized_text`,`is_closed`) VALUES (50,52,NULL,'ثاني البقرة : ٥٦',8,8,'
[٥٦،٥٢] ﴿ ثُمَّ عَفَوْنَا عَنكُم مِّن بَعْدِ ذٰلِكَ لَعَلَّكُمْ تَشْكُرُونَ ﴾ [أول البقرة : ٥٢]
﴿ ثُمَّ بَعَثْنٰكُم مِّن بَعْدِ مَوْتِكُمْ لَعَلَّكُمْ تَشْكُرُونَ ﴾ [ثاني البقرة : ٥٦]
يمكنك ربط الآية الأولى عن طريق حرف الواو في "عفونا" بحرف الواو في "أول".','
[٥٦،٥٢] ﴿ <span style="color:red">ثُمَّ عَفَوْنَا عَنكُم مِّن بَعْدِ ذٰلِكَ</span> لَعَلَّكُمْ تَشْكُرُونَ ﴾ [<span style="color:red">أول</span> البقرة : ٥٢]
﴿ <span style="color:red">ثُمَّ بَعَثْنٰكُم مِّن</span> بَعْدِ <span style="color:red">مَوْتِكُمْ</span> لَعَلَّكُمْ تَشْكُرُونَ ﴾ [ثاني البقرة : ٥٦]
يمكنك ربط الآية ال<span style="color:red">أول</span>ى عن طريق حرف الواو في "<span style="color:red">عفونا</span>" بحرف الواو في "<span style="color:red">أول</span>".','٥٦،٥٢ ثم عفونا عنكم من بعد ذلك لعلكم تشكرون اول البقره ٥٢ ثم بعثنكم من بعد موتكم لعلكم تشكرون ثاني البقره ٥٦ يمكنك ربط الايه الاولي عن طريق حرف الواو في عفونا بحرف الواو في اول',1);
INSERT INTO `mawadi3` (`mawdi_id`,`mawdi_number`,`surah_id`,`reference_text`,`start_page`,`end_page`,`plain_text`,`html_text`,`normalized_text`,`is_closed`) VALUES (51,54,NULL,'البقرة: ٦٧',8,8,'
[٥٤] ﴿وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِۦ﴾ تكررت خمس مرات، انظر [البقرة: ٦٧].','
[٥٤] ﴿<span style="color:red">وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِۦ</span>﴾ تكررت خمس مرات، انظر [البقرة: ٦٧].','٥٤ واذ قال موسي لقومهۦ تكررت خمس مرات، انظر البقره ٦٧',1);
INSERT INTO `mawadi3` (`mawdi_id`,`mawdi_number`,`surah_id`,`reference_text`,`start_page`,`end_page`,`plain_text`,`html_text`,`normalized_text`,`is_closed`) VALUES (52,55,NULL,'ثاني البقرة : ٦١',8,8,'
[٦١ ، ٥٥] ﴿ وَإِذْ قُلْتُمْ يٰمُوسَىٰ لَن نُّؤْمِنَ لَكَ حَتَّىٰ ... ﴾ [أول البقرة : ٥٥]، اربط بين همزة "نؤمن" وهمزة أول.
﴿ وَإِذْ قُلْتُمْ يٰمُوسَىٰ لَن نَّصْبِرَ عَلَىٰ طَعَامٍ ... ﴾ [ثاني البقرة : ٦١]، اربط بين ألف "طعام" وألف ثاني.','
[٦١ ، ٥٥] ﴿ وَإِذْ قُلْتُمْ يٰمُوسَىٰ لَن <span style="color:red">نُّؤْمِنَ لَكَ حَتَّىٰ ...</span> ﴾ [<span style="color:red">أول</span> البقرة : ٥٥]، اربط بين همزة "<span style="color:red">نؤمن</span>" وهمزة <span style="color:red">أول</span>.
﴿ وَإِذْ قُلْتُمْ يٰمُوسَىٰ لَن <span style="color:red">نَّصْبِرَ عَلَىٰ طَعَامٍ ...</span> ﴾ [<span style="color:red">ثاني</span> البقرة : ٦١]، اربط بين ألف "<span style="color:red">طعام</span>" وألف <span style="color:red">ثاني</span>.','٦١ ، ٥٥ واذ قلتم يموسي لن نؤمن لك حتي اول البقره ٥٥، اربط بين همزه نؤمن وهمزه اول واذ قلتم يموسي لن نصبر علي طعام ثاني البقره ٦١، اربط بين الف طعام والف ثاني',1);
INSERT INTO `mawadi3` (`mawdi_id`,`mawdi_number`,`surah_id`,`reference_text`,`start_page`,`end_page`,`plain_text`,`html_text`,`normalized_text`,`is_closed`) VALUES (53,57,NULL,'طه : ٨٠-٨١',8,8,'
[٥٧] ﴿ ... كُلُواْ مِن طَيِّبٰتِ مَا رَزَقْنٰكُمْ وَمَا ظَلَمُونَا وَلٰكِن كَانُوٓاْ أَنفُسَهُمْ يَظْلِمُونَ ﴿٥٧﴾ وَإِذْ قُلْنَا ... ﴾ [البقرة : ٥٧-٥٨]
﴿ ... كُلُواْ مِن طَيِّبٰتِ مَا رَزَقْنٰكُمْ وَمَا ظَلَمُونَا وَلٰكِن كَانُوٓاْ أَنفُسَهُمْ يَظْلِمُونَ ﴿١٦٠﴾ وَإِذْ قِيلَ لَهُمُ ... ﴾ [الأعراف : ١٦٠-١٦١]
﴿ ... وَنَزَّلْنَا عَلَيْكُمُ ٱلْمَنَّ وَٱلسَّلْوَىٰ ﴿٨٠﴾ كُلُواْ مِن طَيِّبٰتِ مَا رَزَقْنٰكُمْ وَلَا تَطْغَوْاْ فِيهِ فَيَحِلَّ عَلَيْكُمْ غَضَبِي ... ﴾ [طه : ٨٠-٨١]','
[٥٧] ﴿ ... كُلُواْ مِن طَيِّبٰتِ مَا رَزَقْنٰكُمْ وَمَا ظَلَمُونَا وَلٰكِن كَانُوٓاْ أَنفُسَهُمْ يَظْلِمُونَ ﴿٥٧﴾ <span style="color:red">وَإِذْ قُلْنَا ...</span> ﴾ [البقرة : ٥٧-٥٨]
﴿ ... كُلُواْ مِن طَيِّبٰتِ مَا رَزَقْنٰكُمْ وَمَا ظَلَمُونَا وَلٰكِن كَانُوٓاْ أَنفُسَهُمْ يَظْلِمُونَ ﴿١٦٠﴾ <span style="color:red">وَإِذْ قِيلَ لَهُمُ ...</span> ﴾ [الأعراف : ١٦٠-١٦١]
﴿ ... وَنَزَّلْنَا عَلَيْكُمُ ٱلْمَنَّ وَٱلسَّلْوَىٰ ﴿٨٠﴾ كُلُواْ مِن طَيِّبٰتِ مَا رَزَقْنٰكُمْ <span style="color:red">وَلَا تَطْغَوْاْ فِيهِ فَيَحِلَّ عَلَيْكُمْ غَضَبِي ...</span> ﴾ [طه : ٨٠-٨١]','٥٧ كلوا من طيبت ما رزقنكم وما ظلمونا ولكن كانوٓا انفسهم يظلمون ٥٧ واذ قلنا البقره ٥٧٥٨ كلوا من طيبت ما رزقنكم وما ظلمونا ولكن كانوٓا انفسهم يظلمون ١٦٠ واذ قيل لهم الاعراف ١٦٠١٦١ ونزلنا عليكم ٱلمن وٱلسلوي ٨٠ كلوا من طيبت ما رزقنكم ولا تطغوا فيه فيحل عليكم غضبي طه ٨٠٨١',1);
INSERT INTO `mawadi3` (`mawdi_id`,`mawdi_number`,`surah_id`,`reference_text`,`start_page`,`end_page`,`plain_text`,`html_text`,`normalized_text`,`is_closed`) VALUES (54,57,NULL,'البقرة : ٥٧، الأعراف : ١٦٠، التوبة : ٧٠، النحل : ٨٣، ١١٨، العنكبوت : ٤٠، الروم : ٩',8,8,'
[٥٧] ﴿ وَلٰكِن أَنفُسَهُمْ يَظْلِمُونَ ﴾ [آل عمران : ١١٧] الوحيدة في القرآن وباقي المواضع ﴿ وَلٰكِن كَانُوٓاْ أَنفُسَهُمْ يَظْلِمُونَ ﴾ [البقرة : ٥٧، الأعراف : ١٦٠، التوبة : ٧٠، النحل : ٨٣، ١١٨، العنكبوت : ٤٠، الروم : ٩]','
[٥٧] ﴿ <span style="color:red">وَلٰكِن أَنفُسَهُمْ يَظْلِمُونَ</span> ﴾ [آل عمران : ١١٧] الوحيدة في القرآن وباقي المواضع ﴿ <span style="color:red">وَلٰكِن كَانُوٓاْ أَنفُسَهُمْ يَظْلِمُونَ</span> ﴾ [البقرة : ٥٧، الأعراف : ١٦٠، التوبة : ٧٠، النحل : ٨٣، ١١٨، العنكبوت : ٤٠، الروم : ٩]','٥٧ ولكن انفسهم يظلمون ال عمران ١١٧ الوحيده في القران وباقي المواضع ولكن كانوٓا انفسهم يظلمون البقره ٥٧، الاعراف ١٦٠، التوبه ٧٠، النحل ٨٣، ١١٨، العنكبوت ٤٠، الروم ٩',1);
INSERT INTO `mawadi3` (`mawdi_id`,`mawdi_number`,`surah_id`,`reference_text`,`start_page`,`end_page`,`plain_text`,`html_text`,`normalized_text`,`is_closed`) VALUES (55,58,NULL,'ثاني البقرة: ٥٨',9,9,'
﴿...فَكُلُوا۟ مِنْهَا حَيْثُ شِئْتُمْ رَغَدًۭا...﴾ [ثاني البقرة: ٥٨]
﴿... وَكُلَا مِنْهَا حَيْثُ شِئْتُمَا رَغَدًۭا ...﴾ [أول البقرة: ٣٥]','
﴿...<span style="color:red">فَكُلُوا۟</span> مِنْهَا حَيْثُ شِئْتُمْ <span style="color:red"><span style="color:red">رَغَدًۭا</span></span>...﴾ [ثاني البقرة: ٥٨]
﴿... وَكُلَا مِنْهَا حَيْثُ شِئْتُمَا <span style="color:red"><span style="color:red">رَغَدًۭا</span></span> ...﴾ [أول البقرة: ٣٥]','فكلوا۟ منها حيث شئتم رغدۭا ثاني البقره ٥٨ وكلا منها حيث شئتما رغدۭا اول البقره ٣٥',1);
INSERT INTO `mawadi3` (`mawdi_id`,`mawdi_number`,`surah_id`,`reference_text`,`start_page`,`end_page`,`plain_text`,`html_text`,`normalized_text`,`is_closed`) VALUES (56,'٥٩-٥٨',NULL,'البقرة:٥٨-٥٩',9,9,'
﴿وَإِذْ قُلْنَا ٱدْخُلُوا۟ هَـٰذِهِ ٱلْقَرْيَةَ فَكُلُوا۟ مِنْهَا حَيْثُ شِئْتُمْ رَغَدًۭا وَٱدْخُلُوا۟ ٱلْبَابَ سُجَّدًۭا وَقُولُوا۟ حِطَّةٌۭ نَّغْفِرْ لَكُمْ خَطَـٰيَـٰكُمْ وَسَنَزِيدُ ٱلْمُحْسِنِينَ ۝٥٨ فَبَدَّلَ ٱلَّذِينَ ظَلَمُوا۟ قَوْلًا غَيْرَ ٱلَّذِى قِيلَ لَهُمْ فَأَنزَلْنَا عَلَى ٱلَّذِينَ ظَلَمُوا۟ رِجْزًۭا مِّنَ ٱلسَّمَاءِ بِمَا كَانُوا۟ يَفْسُقُونَ ۝٥٩﴾ [البقرة:٥٨-٥٩]
﴿وَإِذْ قِيلَ لَهُمُ ٱسْكُنُوا۟ هَـٰذِهِ ٱلْقَرْيَةَ وَكُلُوا۟ مِنْهَا حَيْثُ شِئْتُمْ وَقُولُوا۟ حِطَّةٌۭ وَٱدْخُلُوا۟ ٱلْبَابَ سُجَّدًۭا نَّغْفِرْ لَكُمْ خَطِيـٰٓـَٔـٰتِكُمْ سَنَزِيدُ ٱلْمُحْسِنِينَ ۝١٦١ فَبَدَّلَ ٱلَّذِينَ ظَلَمُوا۟ مِنْهُمْ قَوْلًا غَيْرَ ٱلَّذِى قِيلَ لَهُمْ فَأَرْسَلْنَا عَلَيْهِمْ رِجْزًۭا مِّنَ ٱلسَّمَاءِ بِمَا كَانُوا۟ يَظْلِمُونَ ۝١٦٢﴾ [الأعراف : ١٦١-١٦٢]
اربط بين قاف "وقولوا" وقاف البقرة، أي أن السورة التي جاء في اسمها حرف القاف -البقرة- هي التي تأخرت بها "وقولوا حطة"، وأيضا اربط بين قاف "يفسقون" وقاف البقرة، أي أن السورة التي جاء في اسمها حرف القاف -البقرة- هي التي وقعت بها "يفسقون" التي جاء بها حرف القاف كذلك، وأيضا اربط بين همزة "خطيئاتكم" وهمزة الأعراف، أي أن السورة التي جاء في اسمها حرف الهمزة -الأعراف- هي التي وقعت بها "خطيئاتكم" التي جاء بها حرف الهمزة كذلك.','
﴿وَإِذْ قُلْنَا <span style="color:red">ٱدْخُلُوا۟</span> هَـٰذِهِ ٱلْقَرْيَةَ <span style="color:red">فَكُلُوا۟</span> مِنْهَا حَيْثُ شِئْتُمْ <span style="color:red">رَغَدًۭا</span> وَ<span style="color:red">ٱدْخُلُوا۟</span> ٱلْبَابَ سُجَّدًۭا <span style="color:red">وَقُولُوا۟</span> <span style="color:red"><span style="color:red">حِطَّةٌۭ</span></span> <span style="color:red"><span style="color:red">نَّغْفِرْ</span></span> لَكُمْ <span style="color:red">خَطَـٰيَـٰكُمْ</span> <span style="color:red">وَ<span style="color:red">سَنَزِيدُ</span></span> ٱلْمُحْسِنِينَ ۝٥٨ فَبَدَّلَ ٱلَّذِينَ ظَلَمُوا۟ قَوْلًا غَيْرَ ٱلَّذِى قِيلَ لَهُمْ <span style="color:red">فَأَنزَلْنَا</span> <span style="color:red">عَلَى</span> ٱلَّذِينَ ظَلَمُوا۟ رِجْزًۭا مِّنَ ٱلسَّمَاءِ بِمَا كَانُوا۟ <span style="color:red">يَفْسُقُونَ</span> ۝٥٩﴾ [<span style="color:red"><span style="color:red"><span style="color:red">البقرة</span></span></span>:٥٨-٥٩]
﴿وَإِذْ قِيلَ <span style="color:red">لَهُمُ ٱسْكُنُوا۟</span> هَـٰذِهِ ٱلْقَرْيَةَ <span style="color:red">وَكُلُوا۟</span> مِنْهَا حَيْثُ شِئْتُمْ <span style="color:red">وَقُولُوا۟</span> <span style="color:red"><span style="color:red">حِطَّةٌۭ</span></span> وَ<span style="color:red">ٱدْخُلُوا۟</span> ٱلْبَابَ سُجَّدًۭا <span style="color:red"><span style="color:red">نَّغْفِرْ</span></span> لَكُمْ <span style="color:red">خَطِيـٰٓـَٔـٰتِكُمْ</span> <span style="color:red">سَنَزِيدُ</span> ٱلْمُحْسِنِينَ ۝١٦١ فَبَدَّلَ ٱلَّذِينَ ظَلَمُوا۟ <span style="color:red">مِنْهُمْ</span> قَوْلًا غَيْرَ ٱلَّذِى قِيلَ لَهُمْ <span style="color:red">فَأَرْسَلْنَا</span> <span style="color:red">عَلَيْهِمْ</span> رِجْزًۭا مِّنَ ٱلسَّمَاءِ بِمَا كَانُوا۟ <span style="color:red">يَظْلِمُونَ</span> ۝١٦٢﴾ [<span style="color:red"><span style="color:red">الأعراف</span></span> : ١٦١-١٦٢]
اربط بين قاف "<span style="color:red">وقولوا</span>" وقاف <span style="color:red"><span style="color:red"><span style="color:red">البقرة</span></span></span>، أي أن السورة التي جاء في اسمها حرف القاف -<span style="color:red"><span style="color:red"><span style="color:red">البقرة</span></span></span>- هي التي تأخرت بها "<span style="color:red">وقولوا</span> حطة"، وأيضا اربط بين قاف "<span style="color:red"><span style="color:red">يفسقون</span></span>" وقاف <span style="color:red"><span style="color:red"><span style="color:red">البقرة</span></span></span>، أي أن السورة التي جاء في اسمها حرف القاف -<span style="color:red"><span style="color:red"><span style="color:red">البقرة</span></span></span>- هي التي وقعت بها "<span style="color:red"><span style="color:red">يفسقون</span></span>" التي جاء بها حرف القاف كذلك، وأيضا اربط بين همزة "<span style="color:red"><span style="color:red">خطيئاتكم</span></span>" وهمزة <span style="color:red"><span style="color:red">الأعراف</span></span>، أي أن السورة التي جاء في اسمها حرف الهمزة -<span style="color:red"><span style="color:red">الأعراف</span></span>- هي التي وقعت بها "<span style="color:red"><span style="color:red">خطيئاتكم</span></span>" التي جاء بها حرف الهمزة كذلك.','واذ قلنا ٱدخلوا۟ هذه ٱلقريه فكلوا۟ منها حيث شئتم رغدۭا وٱدخلوا۟ ٱلباب سجدۭا وقولوا۟ حطهۭ نغفر لكم خطيكم وسنزيد ٱلمحسنين ۝٥٨ فبدل ٱلذين ظلموا۟ قولا غير ٱلذي قيل لهم فانزلنا علي ٱلذين ظلموا۟ رجزۭا من ٱلسماء بما كانوا۟ يفسقون ۝٥٩ البقره٥٨٥٩ واذ قيل لهم ٱسكنوا۟ هذه ٱلقريه وكلوا۟ منها حيث شئتم وقولوا۟ حطهۭ وٱدخلوا۟ ٱلباب سجدۭا نغفر لكم خطيٓٔتكم سنزيد ٱلمحسنين ۝١٦١ فبدل ٱلذين ظلموا۟ منهم قولا غير ٱلذي قيل لهم فارسلنا عليهم رجزۭا من ٱلسماء بما كانوا۟ يظلمون ۝١٦٢ الاعراف ١٦١١٦٢ اربط بين قاف وقولوا وقاف البقره، اي ان السوره التي جاء في اسمها حرف القاف البقره هي التي تاخرت بها وقولوا حطه، وايضا اربط بين قاف يفسقون وقاف البقره، اي ان السوره التي جاء في اسمها حرف القاف البقره هي التي وقعت بها يفسقون التي جاء بها حرف القاف كذلك، وايضا اربط بين همزه خطيئاتكم وهمزه الاعراف، اي ان السوره التي جاء في اسمها حرف الهمزه الاعراف هي التي وقعت بها خطيئاتكم التي جاء بها حرف الهمزه كذلك',1);
INSERT INTO `mawadi3` (`mawdi_id`,`mawdi_number`,`surah_id`,`reference_text`,`start_page`,`end_page`,`plain_text`,`html_text`,`normalized_text`,`is_closed`) VALUES (57,60,NULL,'البقرة : ٦٠',9,9,'
﴿... أَضْرِب بِّعَصَاكَ الْحَجَرَ فَٱنفَجَرَتْ مِنْهُ اثْنَتَا عَشْرَةَ عَيْنًا قَدْ عَلِمَ كُلُّ أُنَاسٍ مَّشْرَبَهُمْ كُلُوا وَٱشْرَبُوا مِن رِّزْقِ ...﴾ [البقرة : ٦٠] ، ﴿... أَضْرِب بِّعَصَاكَ الْحَجَرَ فَٱنبَجَسَتْ مِنْهُ اثْنَتَا عَشْرَةَ عَيْنًا قَدْ عَلِمَ كُلُّ أُنَاسٍ مَّشْرَبَهُمْ وَظَلَّلْنَا عَلَيْهِمُ ...﴾ [الأعراف : ١٦٠] ، ﴿فَأَوْحَيْنَا إِلَىٰ مُوسَىٰ أَنِ اضْرِب بِّعَصَاكَ الْبَحْرَ فَٱنفَلَقَ ...﴾ [الشعراء : ٦٣]
ملحوظة: آية الشعراء الوحيدة "اضرب بعصاك البحر" وباقي المواضع "اضرب بعصاك الحجر".','
﴿... أَضْرِب بِّعَصَاكَ الْحَجَرَ <span style="color:red">فَٱنفَجَرَتْ</span> مِنْهُ اثْنَتَا عَشْرَةَ عَيْنًا قَدْ عَلِمَ كُلُّ أُنَاسٍ مَّشْرَبَهُمْ <span style="color:red">كُلُوا وَٱشْرَبُوا مِن</span> رِّزْقِ ...﴾ [البقرة : ٦٠] ، ﴿... أَضْرِب بِّعَصَاكَ الْحَجَرَ <span style="color:red">فَٱنبَجَسَتْ</span> مِنْهُ اثْنَتَا عَشْرَةَ عَيْنًا قَدْ عَلِمَ كُلُّ أُنَاسٍ مَّشْرَبَهُمْ <span style="color:red">وَظَلَّلْنَا عَلَيْهِمُ</span> ...﴾ [الأعراف : ١٦٠] ، ﴿فَأَوْحَيْنَا إِلَىٰ مُوسَىٰ أَنِ اضْرِب بِّعَصَاكَ <span style="color:red">الْبَحْرَ فَٱنفَلَقَ</span> ...﴾ [الشعراء : ٦٣]
ملحوظة: آية الشعراء الوحيدة "اضرب بعصاك <span style="color:red">البحر</span>" وباقي المواضع "اضرب بعصاك <span style="color:red">الحجر</span>".','اضرب بعصاك الحجر فٱنفجرت منه اثنتا عشره عينا قد علم كل اناس مشربهم كلوا وٱشربوا من رزق البقره ٦٠ ، اضرب بعصاك الحجر فٱنبجست منه اثنتا عشره عينا قد علم كل اناس مشربهم وظللنا عليهم الاعراف ١٦٠ ، فاوحينا الي موسي ان اضرب بعصاك البحر فٱنفلق الشعراء ٦٣ ملحوظه ايه الشعراء الوحيده اضرب بعصاك البحر وباقي المواضع اضرب بعصاك الحجر',1);
INSERT INTO `mawadi3` (`mawdi_id`,`mawdi_number`,`surah_id`,`reference_text`,`start_page`,`end_page`,`plain_text`,`html_text`,`normalized_text`,`is_closed`) VALUES (58,61,NULL,'البقرة : ٦١-٦٢',9,9,'
﴿... وَضُرِبَتْ عَلَيْهِمُ الذِّلَّةُ وَالْمَسْكَنَةُ وَبَاءُوا بِغَضَبٍ مِّنَ اللَّهِ ذَٰلِكَ بِأَنَّهُمْ كَانُوا يَكْفُرُونَ بِآيَاتِ اللَّهِ وَيَقْتُلُونَ النَّبِيِّينَ بِغَيْرِ الْحَقِّ ذَٰلِكَ بِمَا عَصَوا وَّكَانُوا يَعْتَدُونَ ۝٦١ إِنَّ الَّذِينَ آمَنُوا ...﴾ [البقرة : ٦١-٦٢]
﴿إِنَّ الَّذِينَ يَكْفُرُونَ بِآيَاتِ اللَّهِ وَيَقْتُلُونَ النَّبِيِّينَ بِغَيْرِ حَقٍّ وَيَقْتُلُونَ ...﴾ [أول آل عمران : ٢١]
﴿... وَضُرِبَتْ عَلَيْهِمُ الْمَسْكَنَةُ وَبَاءُوا بِغَضَبٍ مِّنَ اللَّهِ بِأَنَّهُمْ كَانُوا يَكْفُرُونَ بِآيَاتِ اللَّهِ وَيَقْتُلُونَ الْأَنبِيَاءَ بِغَيْرِ حَقٍّ ذَٰلِكَ بِمَا عَصَوا وَّكَانُوا يَعْتَدُونَ ۝١١٢ لَيْسُوا سَوَاءً مِّنْ أَهْلِ الْكِتَابِ أُمَّةٌ قَائِمَةٌ يَتْلُونَ آيَاتِ اللَّهِ ...﴾ [ثاني آل عمران : ١١٢-١١٣]
﴿... ذَٰلِكَ بِمَا عَصَوا وَّكَانُوا يَعْتَدُونَ ۝٧٨ كَانُوا لَا يَتَنَاهَوْنَ عَن مُّنكَرٍ فَعَلُوهُ ...﴾ [المائدة : ٧٨-٧٩]
ملحوظة: آية البقرة الوحيدة "ويقتلون النبيين بغير الحق" وباقي المواضع "بغير حق"، سواء جاء قبلها "النبيين" أو "الأنبياء"، كما [بآخر آل عمران : ١٨١ ، النساء : ١٥٥]، وآية آل عمران الثانية "ويقتلون الأنبياء" وباقي المواضع "ويقتلون النبيين".','
﴿... وَضُرِبَتْ عَلَيْهِمُ <span style="color:red">الذِّلَّةُ</span> وَالْمَسْكَنَةُ وَبَاءُوا بِغَضَبٍ مِّنَ اللَّهِ ذَٰلِكَ بِأَنَّهُمْ كَانُوا يَكْفُرُونَ بِآيَاتِ اللَّهِ وَيَقْتُلُونَ <span style="color:red"><span style="color:red">النَّبِيِّينَ</span></span> بِغَيْرِ <span style="color:red">الْحَقِّ</span> ذَٰلِكَ بِمَا عَصَوا وَّكَانُوا يَعْتَدُونَ ۝٦١ <span style="color:red">إِنَّ الَّذِينَ آمَنُوا</span> ...﴾ [البقرة : ٦١-٦٢]
﴿إِنَّ الَّذِينَ يَكْفُرُونَ بِآيَاتِ اللَّهِ وَيَقْتُلُونَ <span style="color:red"><span style="color:red">النَّبِيِّينَ</span></span> بِغَيْرِ <span style="color:red"><span style="color:red">حَقٍّ</span></span> وَيَقْتُلُونَ ...﴾ [أول آل عمران : ٢١]
﴿... وَضُرِبَتْ عَلَيْهِمُ الْمَسْكَنَةُ وَبَاءُوا بِغَضَبٍ مِّنَ اللَّهِ بِأَنَّهُمْ كَانُوا يَكْفُرُونَ بِآيَاتِ اللَّهِ وَيَقْتُلُونَ <span style="color:red">الْأَنبِيَاءَ</span> بِغَيْرِ <span style="color:red"><span style="color:red">حَقٍّ</span></span> ذَٰلِكَ بِمَا عَصَوا وَّكَانُوا يَعْتَدُونَ ۝١١٢ <span style="color:red">لَيْسُوا سَوَاءً مِّنْ أَهْلِ الْكِتَابِ أُمَّةٌ قَائِمَةٌ يَتْلُونَ آيَاتِ اللَّهِ</span> ...﴾ [ثاني آل عمران : ١١٢-١١٣]
﴿... ذَٰلِكَ بِمَا عَصَوا وَّكَانُوا يَعْتَدُونَ ۝٧٨ <span style="color:red">كَانُوا لَا يَتَنَاهَوْنَ عَن مُّنكَرٍ فَعَلُوهُ</span> ...﴾ [المائدة : ٧٨-٧٩]
ملحوظة: آية البقرة الوحيدة "ويقتلون <span style="color:red"><span style="color:red">النبيين</span></span> بغير <span style="color:red">الحق</span>" وباقي المواضع "<span style="color:red">بغير حق</span>"، سواء جاء قبلها "<span style="color:red"><span style="color:red">النبيين</span></span>" أو "<span style="color:red"><span style="color:red">الأنبياء</span></span>"، كما [بآخر آل عمران : ١٨١ ، النساء : ١٥٥]، وآية آل عمران الثانية "ويقتلون <span style="color:red"><span style="color:red">الأنبياء</span></span>" وباقي المواضع "ويقتلون <span style="color:red"><span style="color:red">النبيين</span></span>".','وضربت عليهم الذله والمسكنه وباءوا بغضب من الله ذلك بانهم كانوا يكفرون بايات الله ويقتلون النبيين بغير الحق ذلك بما عصوا وكانوا يعتدون ۝٦١ ان الذين امنوا البقره ٦١٦٢ ان الذين يكفرون بايات الله ويقتلون النبيين بغير حق ويقتلون اول ال عمران ٢١ وضربت عليهم المسكنه وباءوا بغضب من الله بانهم كانوا يكفرون بايات الله ويقتلون الانبياء بغير حق ذلك بما عصوا وكانوا يعتدون ۝١١٢ ليسوا سواء من اهل الكتاب امه قائمه يتلون ايات الله ثاني ال عمران ١١٢١١٣ ذلك بما عصوا وكانوا يعتدون ۝٧٨ كانوا لا يتناهون عن منكر فعلوه المائده ٧٨٧٩ ملحوظه ايه البقره الوحيده ويقتلون النبيين بغير الحق وباقي المواضع بغير حق، سواء جاء قبلها النبيين او الانبياء، كما باخر ال عمران ١٨١ ، النساء ١٥٥، وايه ال عمران الثانيه ويقتلون الانبياء وباقي المواضع ويقتلون النبيين',1);
INSERT INTO `mawadi3` (`mawdi_id`,`mawdi_number`,`surah_id`,`reference_text`,`start_page`,`end_page`,`plain_text`,`html_text`,`normalized_text`,`is_closed`) VALUES (59,62,NULL,NULL,10,10,'
﴿ إِنَّ الَّذِينَ ءَامَنُوا وَالَّذِينَ هَادُوا وَالنَّصَٰرَىٰ وَالصَّٰبِـِٔينَ مَنْ ءَامَنَ بِاللَّهِ وَالْيَوْمِ الْآخِرِ وَعَمِلَ صَٰلِحًا فَلَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ ﴿٦٢﴾ وَإِذْ أَخَذْنَا مِيثَٰقَكُمْ ... ﴾ [البقرة : ٦٢-٦٣]
﴿ إِنَّ الَّذِينَ ءَامَنُوا وَالَّذِينَ هَادُوا وَالصَّٰبِـُٔونَ وَالنَّصَٰرَىٰ مَنْ ءَامَنَ بِاللَّهِ وَالْيَوْمِ الْآخِرِ وَعَمِلَ صَٰلِحًا فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ ﴿٦٩﴾ لَقَدْ أَخَذْنَا مِيثَٰقَ ... ﴾ [المائدة : ٦٩-٧٠]
﴿ إِنَّ الَّذِينَ ءَامَنُوا وَالَّذِينَ هَادُوا وَالصَّٰبِـِٔينَ وَالنَّصَٰرَىٰ وَالْمَجُوسَ وَالَّذِينَ أَشْرَكُوا ... ﴾ [الحج : ١٧]
ملحوظة: آية البقرة الوحيدة التي قدم بها لفظ "النصارى على الصابئين"، وآية المائدة الوحيدة التي جاء بها "الصابئون".','
﴿ إِنَّ الَّذِينَ ءَامَنُوا وَالَّذِينَ هَادُوا وَالنَّصَٰرَىٰ <span style="color:red">وَالصَّٰبِـِٔينَ</span> مَنْ ءَامَنَ بِاللَّهِ وَالْيَوْمِ الْآخِرِ وَعَمِلَ صَٰلِحًا <span style="color:red">فَلَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا</span> خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ ﴿٦٢﴾ <span style="color:red">وَإِذْ أَخَذْنَا مِيثَٰقَ</span>كُمْ ... ﴾ [البقرة : ٦٢-٦٣]
﴿ إِنَّ الَّذِينَ ءَامَنُوا وَالَّذِينَ هَادُوا <span style="color:red">وَالصَّٰبِـُٔونَ وَالنَّصَٰرَىٰ</span> مَنْ ءَامَنَ بِاللَّهِ وَالْيَوْمِ الْآخِرِ وَعَمِلَ صَٰلِحًا <span style="color:red">فَلَا</span> خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ ﴿٦٩﴾ <span style="color:red">لَقَدْ أَخَذْنَا مِيثَٰقَ</span> ... ﴾ [المائدة : ٦٩-٧٠]
﴿ إِنَّ الَّذِينَ ءَامَنُوا وَالَّذِينَ هَادُوا <span style="color:red">وَالصَّٰبِـِٔينَ</span> وَالنَّصَٰرَىٰ <span style="color:red">وَالْمَجُوسَ وَالَّذِينَ أَشْرَكُوا</span> ... ﴾ [الحج : ١٧]
ملحوظة: آية البقرة الوحيدة التي قدم بها لفظ "<span style="color:red">النصارى على الصابئين</span>"، وآية المائدة الوحيدة التي جاء بها "<span style="color:red">الصابئون</span>".','ان الذين ءامنوا والذين هادوا والنصري والصبٔين من ءامن بالله واليوم الاخر وعمل صلحا فلهم اجرهم عند ربهم ولا خوف عليهم ولا هم يحزنون ٦٢ واذ اخذنا ميثقكم البقره ٦٢٦٣ ان الذين ءامنوا والذين هادوا والصبٔون والنصري من ءامن بالله واليوم الاخر وعمل صلحا فلا خوف عليهم ولا هم يحزنون ٦٩ لقد اخذنا ميثق المائده ٦٩٧٠ ان الذين ءامنوا والذين هادوا والصبٔين والنصري والمجوس والذين اشركوا الحج ١٧ ملحوظه ايه البقره الوحيده التي قدم بها لفظ النصاري علي الصابئين، وايه المائده الوحيده التي جاء بها الصابئون',1);
INSERT INTO `mawadi3` (`mawdi_id`,`mawdi_number`,`surah_id`,`reference_text`,`start_page`,`end_page`,`plain_text`,`html_text`,`normalized_text`,`is_closed`) VALUES (60,62,NULL,NULL,10,10,'
﴿ فَلَهُمْ أَجْرُهُمْ ﴾ تكررت مرتين: [البقرة : ٦٢ ، ٢٧٤]
ليس في القرآن غيرهما وباقي المواضع ﴿ لَهُمْ أَجْرُهُمْ ﴾ [البقرة : ٢٦٢ ، ٢٧٧ ، آل عمران : ١٩٩ ، الحديد : ١٩]','
﴿ <span style="color:red">فَ<span style="color:red">لَهُمْ أَجْرُهُمْ</span></span> ﴾ تكررت مرتين: [البقرة : ٦٢ ، ٢٧٤]
ليس في القرآن غيرهما وباقي المواضع ﴿ <span style="color:red">لَهُمْ أَجْرُهُمْ</span> ﴾ [البقرة : ٢٦٢ ، ٢٧٧ ، آل عمران : ١٩٩ ، الحديد : ١٩]','فلهم اجرهم تكررت مرتين البقره ٦٢ ، ٢٧٤ ليس في القران غيرهما وباقي المواضع لهم اجرهم البقره ٢٦٢ ، ٢٧٧ ، ال عمران ١٩٩ ، الحديد ١٩',1);
INSERT INTO `mawadi3` (`mawdi_id`,`mawdi_number`,`surah_id`,`reference_text`,`start_page`,`end_page`,`plain_text`,`html_text`,`normalized_text`,`is_closed`) VALUES (61,63,NULL,NULL,10,10,'
﴿ وَإِذْ أَخَذْنَا مِيثَٰقَكُمْ وَرَفَعْنَا فَوْقَكُمُ الطُّورَ خُذُوا مَا ءَاتَيْنَٰكُم بِقُوَّةٍ وَٱذْكُرُوا مَا فِيهِ لَعَلَّكُمْ تَتَّقُونَ ﴾ [أول البقرة : ٦٣]
﴿ وَإِذْ أَخَذْنَا مِيثَٰقَكُمْ لَا تَسْفِكُونَ دِمَاءَكُمْ وَلَا تُخْرِجُونَ أَنفُسَكُم ... ﴾ [ثاني البقرة : ٨٤]
﴿ وَإِذْ أَخَذْنَا مِيثَٰقَكُمْ وَرَفَعْنَا فَوْقَكُمُ الطُّورَ خُذُوا مَا ءَاتَيْنَٰكُم بِقُوَّةٍ وَٱسْمَعُوا قَالُوا سَمِعْنَا وَعَصَيْنَا ... ﴾ [ثالث البقرة : ٩٣]
﴿ ... وَظَنُّوا أَنَّهُ وَاقِعٌ بِهِمْ خُذُوا مَا ءَاتَيْنَٰكُم بِقُوَّةٍ وَٱذْكُرُوا مَا فِيهِ لَعَلَّكُمْ تَتَّقُونَ ﴾ [الأعراف : ١٧١]
ملحوظة: آية البقرة الثالثة الوحيدة "خذوا ما آتيناكم بقوة واسمعوا" وباقي المواضع "خذوا ما آتيناكم بقوة واذكروا".','
﴿ وَإِذْ أَخَذْنَا مِيثَٰقَكُمْ <span style="color:red"><span style="color:red">وَرَفَعْنَا فَوْقَكُمُ الطُّورَ</span></span> خُذُوا مَا ءَاتَيْنَٰكُم بِقُوَّةٍ <span style="color:red"><span style="color:red">وَٱذْكُرُوا مَا فِيهِ لَعَلَّكُمْ تَتَّقُونَ</span></span> ﴾ [أول البقرة : ٦٣]
﴿ وَإِذْ أَخَذْنَا مِيثَٰقَكُمْ <span style="color:red">لَا تَسْفِكُونَ دِمَاءَكُمْ وَلَا تُخْرِجُونَ أَنفُسَكُم</span> ... ﴾ [ثاني البقرة : ٨٤]
﴿ وَإِذْ أَخَذْنَا مِيثَٰقَكُمْ <span style="color:red"><span style="color:red">وَرَفَعْنَا فَوْقَكُمُ الطُّورَ</span></span> خُذُوا مَا ءَاتَيْنَٰكُم بِقُوَّةٍ <span style="color:red">وَٱسْمَعُوا قَالُوا سَمِعْنَا وَعَصَيْنَا</span> ... ﴾ [ثالث البقرة : ٩٣]
﴿ ... وَظَنُّوا أَنَّهُ وَاقِعٌ بِهِمْ خُذُوا مَا ءَاتَيْنَٰكُم بِقُوَّةٍ <span style="color:red"><span style="color:red">وَٱذْكُرُوا مَا فِيهِ لَعَلَّكُمْ تَتَّقُونَ</span></span> ﴾ [الأعراف : ١٧١]
ملحوظة: آية البقرة الثالثة الوحيدة "خذوا ما آتيناكم بقوة <span style="color:red">واسمعوا</span>" وباقي المواضع "خذوا ما آتيناكم بقوة <span style="color:red">واذكروا</span>".','واذ اخذنا ميثقكم ورفعنا فوقكم الطور خذوا ما ءاتينكم بقوه وٱذكروا ما فيه لعلكم تتقون اول البقره ٦٣ واذ اخذنا ميثقكم لا تسفكون دماءكم ولا تخرجون انفسكم ثاني البقره ٨٤ واذ اخذنا ميثقكم ورفعنا فوقكم الطور خذوا ما ءاتينكم بقوه وٱسمعوا قالوا سمعنا وعصينا ثالث البقره ٩٣ وظنوا انه واقع بهم خذوا ما ءاتينكم بقوه وٱذكروا ما فيه لعلكم تتقون الاعراف ١٧١ ملحوظه ايه البقره الثالثه الوحيده خذوا ما اتيناكم بقوه واسمعوا وباقي المواضع خذوا ما اتيناكم بقوه واذكروا',1);
INSERT INTO `mawadi3` (`mawdi_id`,`mawdi_number`,`surah_id`,`reference_text`,`start_page`,`end_page`,`plain_text`,`html_text`,`normalized_text`,`is_closed`) VALUES (62,64,NULL,NULL,10,10,'
﴿ فَلَوْلَا فَضْلُ اللَّهِ عَلَيْكُمْ وَرَحْمَتُهُ ﴾ [البقرة : ٦٤] الوحيدة في القرآن وباقي المواضع ﴿ وَلَوْلَا فَضْلُ اللَّهِ عَلَيْكُمْ وَرَحْمَتُهُ ﴾ [النساء : ٨٣ ، النور : ١٠ ، ١٤ ، ٢٠ ، ٢١] ، للتفصيل انظر [النساء : ٨٣].','
﴿ <span style="color:red">فَلَوْلَا فَضْلُ اللَّهِ عَلَيْكُمْ وَرَحْمَتُهُ</span> ﴾ [البقرة : ٦٤] الوحيدة في القرآن وباقي المواضع ﴿ <span style="color:red">وَلَوْلَا فَضْلُ اللَّهِ عَلَيْكُمْ وَرَحْمَتُهُ</span> ﴾ [النساء : ٨٣ ، النور : ١٠ ، ١٤ ، ٢٠ ، ٢١] ، للتفصيل انظر [النساء : ٨٣].','فلولا فضل الله عليكم ورحمته البقره ٦٤ الوحيده في القران وباقي المواضع ولولا فضل الله عليكم ورحمته النساء ٨٣ ، النور ١٠ ، ١٤ ، ٢٠ ، ٢١ ، للتفصيل انظر النساء ٨٣',1);
INSERT INTO `mawadi3` (`mawdi_id`,`mawdi_number`,`surah_id`,`reference_text`,`start_page`,`end_page`,`plain_text`,`html_text`,`normalized_text`,`is_closed`) VALUES (63,65,NULL,NULL,10,10,'
﴿ وَلَقَدْ عَلِمْتُمُ الَّذِينَ اعْتَدَوْا مِنكُمْ فِي السَّبْتِ فَقُلْنَا لَهُمْ كُونُوا قِرَدَةً خَٰسِـِٔينَ ﴿٦٥﴾ فَجَعَلْنَٰهَا نَكَٰلًا ... ﴾ [البقرة : ٦٥-٦٦]
﴿ فَلَمَّا عَتَوْا عَن مَّا نُهُوا عَنْهُ قُلْنَا لَهُمْ كُونُوا قِرَدَةً خَٰسِـِٔينَ ﴿١٦٦﴾ وَإِذْ تَأَذَّنَ رَبُّكَ لَيَبْعَثَنَّ ... ﴾ [الأعراف : ١٦٦-١٦٧]','
﴿ وَلَقَدْ عَلِمْتُمُ الَّذِينَ اعْتَدَوْا مِنكُمْ فِي السَّبْتِ فَقُلْنَا لَهُمْ كُونُوا قِرَدَةً خَٰسِـِٔينَ ﴿٦٥﴾ <span style="color:red">فَجَعَلْنَٰهَا نَكَٰلًا</span> ... ﴾ [البقرة : ٦٥-٦٦]
﴿ فَلَمَّا عَتَوْا عَن مَّا نُهُوا عَنْهُ قُلْنَا لَهُمْ كُونُوا قِرَدَةً خَٰسِـِٔينَ ﴿١٦٦﴾ <span style="color:red">وَإِذْ تَأَذَّنَ رَبُّكَ لَيَبْعَثَنَّ</span> ... ﴾ [الأعراف : ١٦٦-١٦٧]','ولقد علمتم الذين اعتدوا منكم في السبت فقلنا لهم كونوا قرده خسٔين ٦٥ فجعلنها نكلا البقره ٦٥٦٦ فلما عتوا عن ما نهوا عنه قلنا لهم كونوا قرده خسٔين ١٦٦ واذ تاذن ربك ليبعثن الاعراف ١٦٦١٦٧',1);
INSERT INTO `mawadi3` (`mawdi_id`,`mawdi_number`,`surah_id`,`reference_text`,`start_page`,`end_page`,`plain_text`,`html_text`,`normalized_text`,`is_closed`) VALUES (64,67,NULL,NULL,10,10,'
﴿ وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِۦۤ إِنَّ اللَّهَ يَأْمُرُكُمْ أَن تَذْبَحُوا ... ﴾ [ثاني البقرة : ٦٧] ، بدون "ياقوم".
﴿ وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِ ٱذْكُرُوا نِعْمَةَ اللَّهِ عَلَيْكُمْ إِذْ أَنجَىٰكُم ... ﴾ [إبراهيم : ٦] ، بدون "ياقوم".
﴿ وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِۦ يَٰقَوْمِ إِنَّكُمْ ظَلَمْتُمْ أَنفُسَكُم ... ﴾ [أول البقرة : ٥٤]
﴿ وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِۦ يَٰقَوْمِ ٱذْكُرُوا نِعْمَةَ اللَّهِ عَلَيْكُمْ إِذْ جَعَلَ فِيكُمْ أَنبِيَاءَ ... ﴾ [المائدة : ٢٠]
﴿ وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِۦ يَٰقَوْمِ لِمَ تُؤْذُونَنِي وَقَد تَّعْلَمُونَ ... ﴾ [الصف : ٥]
﴿ وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِۦ ﴾ تكررت خمس مرات. ملحوظة: آية البقرة الثانية وآية إبراهيم بدون "ياقوم" ، فانتبه لهما.','
﴿ وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِۦۤ <span style="color:red">إِنَّ اللَّهَ يَأْمُرُكُمْ أَن تَذْبَحُوا</span> ... ﴾ [ثاني البقرة : ٦٧] ، بدون "<span style="color:red"><span style="color:red"><span style="color:red">ياقوم</span></span></span>".
﴿ وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِ <span style="color:red">ٱذْكُرُوا نِعْمَةَ اللَّهِ عَلَيْكُمْ إِذْ أَنجَىٰكُم</span> ... ﴾ [إبراهيم : ٦] ، بدون "<span style="color:red"><span style="color:red"><span style="color:red">ياقوم</span></span></span>".
﴿ وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِۦ يَٰقَوْمِ <span style="color:red">إِنَّكُمْ ظَلَمْتُمْ أَنفُسَكُم</span> ... ﴾ [أول البقرة : ٥٤]
﴿ وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِۦ يَٰقَوْمِ <span style="color:red">ٱذْكُرُوا نِعْمَةَ اللَّهِ عَلَيْكُمْ إِذْ جَعَلَ فِيكُمْ أَنبِيَاءَ</span> ... ﴾ [المائدة : ٢٠]
﴿ وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِۦ يَٰقَوْمِ <span style="color:red">لِمَ تُؤْذُونَنِي وَقَد تَّعْلَمُونَ</span> ... ﴾ [الصف : ٥]
﴿ وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِۦ ﴾ تكررت خمس مرات. ملحوظة: آية البقرة الثانية وآية إبراهيم بدون "<span style="color:red"><span style="color:red"><span style="color:red">ياقوم</span></span></span>" ، فانتبه لهما.','واذ قال موسي لقومهۦۤ ان الله يامركم ان تذبحوا ثاني البقره ٦٧ ، بدون ياقوم واذ قال موسي لقومه ٱذكروا نعمه الله عليكم اذ انجيكم ابراهيم ٦ ، بدون ياقوم واذ قال موسي لقومهۦ يقوم انكم ظلمتم انفسكم اول البقره ٥٤ واذ قال موسي لقومهۦ يقوم ٱذكروا نعمه الله عليكم اذ جعل فيكم انبياء المائده ٢٠ واذ قال موسي لقومهۦ يقوم لم تؤذونني وقد تعلمون الصف ٥ واذ قال موسي لقومهۦ تكررت خمس مرات ملحوظه ايه البقره الثانيه وايه ابراهيم بدون ياقوم ، فانتبه لهما',1);
INSERT INTO `mawadi3` (`mawdi_id`,`mawdi_number`,`surah_id`,`reference_text`,`start_page`,`end_page`,`plain_text`,`html_text`,`normalized_text`,`is_closed`) VALUES (65,68,NULL,NULL,11,11,'
[٦٨ ، ٧١] ﴿ ... قَالَ إِنَّهُۥ يَقُولُ إِنَّهَا بَقَرَةٌ لَّا فَارِضٌ وَلَا بِكْرٌ عَوَانٌۢ بَيْنَ ذَٰلِكَ ۖ فَٱفْعَلُوا۟ مَا تُؤْمَرُونَ ﴾ [أول البقرة : ٦٨]
﴿ قَالَ إِنَّهُۥ يَقُولُ إِنَّهَا بَقَرَةٌ لَّا ذَلُولٌ تُثِيرُ ٱلْأَرْضَ وَلَا تَسْقِي ٱلْحَرْثَ مُسَلَّمَةٌ لَّا شِيَةَ فِيهَا ... ﴾ [ثاني البقرة : ٧١]
كثيرًا ما يحدث لبس بين الآيتين، ويمكن ضبطهما عن طريق ربطهما بكلمة أول وثاني، فالموضع الأول جاء به كلمة "عوان" وجاء بها حرف الواو، وكذلك كلمة أول جاء بها حرف الواو، والموضع الثاني جاء به كلمة "تثير" و"تسقي" وجاء بهما حرف الياء، وكذلك كلمة ثاني جاء بها حرف الياء فانتبه.','
[٦٨ ، ٧١] ﴿ ... قَالَ إِنَّهُۥ يَقُولُ إِنَّهَا بَقَرَةٌ لَّا <span style="color:red">فَارِضٌ وَلَا بِكْرٌ</span> <span style="color:red">عَوَانٌۢ بَيْنَ ذَٰلِكَ</span> ۖ فَٱفْعَلُوا۟ مَا تُؤْمَرُونَ ﴾ [أول البقرة : ٦٨]
﴿ قَالَ إِنَّهُۥ يَقُولُ إِنَّهَا بَقَرَةٌ لَّا ذَلُولٌ <span style="color:red">تُثِيرُ ٱلْأَرْضَ</span> وَلَا <span style="color:red">تَسْقِي</span> ٱلْحَرْثَ <span style="color:red">مُسَلَّمَةٌ لَّا شِيَةَ فِيهَا</span> ... ﴾ [ثاني البقرة : ٧١]
كثيرًا ما يحدث لبس بين الآيتين، ويمكن ضبطهما عن طريق ربطهما بكلمة أول وثاني، فالموضع الأول جاء به كلمة "عوان" وجاء بها حرف الواو، وكذلك كلمة أول جاء بها حرف الواو، والموضع الثاني جاء به كلمة "تثير" و"تسقي" وجاء بهما حرف الياء، وكذلك كلمة ثاني جاء بها حرف الياء فانتبه.','٦٨ ، ٧١ قال انهۥ يقول انها بقره لا فارض ولا بكر عوانۢ بين ذلك ۖ فٱفعلوا۟ ما تؤمرون اول البقره ٦٨ قال انهۥ يقول انها بقره لا ذلول تثير ٱلارض ولا تسقي ٱلحرث مسلمه لا شيه فيها ثاني البقره ٧١ كثيرا ما يحدث لبس بين الايتين، ويمكن ضبطهما عن طريق ربطهما بكلمه اول وثاني، فالموضع الاول جاء به كلمه عوان وجاء بها حرف الواو، وكذلك كلمه اول جاء بها حرف الواو، والموضع الثاني جاء به كلمه تثير وتسقي وجاء بهما حرف الياء، وكذلك كلمه ثاني جاء بها حرف الياء فانتبه',1);
INSERT INTO `mawadi3` (`mawdi_id`,`mawdi_number`,`surah_id`,`reference_text`,`start_page`,`end_page`,`plain_text`,`html_text`,`normalized_text`,`is_closed`) VALUES (66,76,NULL,NULL,11,11,'
[٧٦] ﴿ وَإِذَا لَقُوا۟ ٱلَّذِينَ ءَامَنُوا۟ قَالُوٓا۟ ءَامَنَّا وَإِذَا خَلَا بَعْضُهُمْ إِلَىٰ بَعْضٍ قَالُوٓا۟ أَتُحَدِّثُونَهُم ... ﴾ [ثاني البقرة : ٧٦]
﴿ وَإِذَا لَقُوا۟ ٱلَّذِينَ ءَامَنُوا۟ قَالُوٓا۟ ءَامَنَّا وَإِذَا خَلَوْا۟ إِلَىٰ شَيَٰطِينِهِمْ قَالُوٓا۟ إِنَّا مَعَكُمْ إِنَّمَا نَحْنُ مُسْتَهْزِءُونَ ﴾ [أول البقرة : ١٤]
اربط بين ألف "خلا" وألف ثاني، أي أن الآية التي جاء بها حرف الألف المدية قد وقعت بالموضع الثاني الذي جاء به حرف الألف المدية كذلك، وأيضا اربط بين واو "خلوا" وواو أول، أي أن الآية التي جاء بها "خلوا" وجاء بها حرف الواو قد وقعت بالموضع الأول الذي جاء به حرف الواو كذلك.','
[٧٦] ﴿ وَإِذَا لَقُوا۟ ٱلَّذِينَ ءَامَنُوا۟ قَالُوٓا۟ ءَامَنَّا وَإِذَا <span style="color:red">خَلَا</span> <span style="color:red">بَعْضُهُمْ</span> <span style="color:red">إِلَىٰ بَعْضٍ</span> قَالُوٓا۟ <span style="color:red">أَتُحَدِّثُونَهُم</span> ... ﴾ [ثاني البقرة : ٧٦]
﴿ وَإِذَا لَقُوا۟ ٱلَّذِينَ ءَامَنُوا۟ قَالُوٓا۟ ءَامَنَّا وَإِذَا <span style="color:red">خَلَوْا۟</span> <span style="color:red">إِلَىٰ شَيَٰطِينِهِمْ</span> قَالُوٓا۟ إِنَّا مَعَكُمْ إِنَّمَا نَحْنُ <span style="color:red">مُسْتَهْزِءُونَ</span> ﴾ [أول البقرة : ١٤]
اربط بين ألف "خلا" وألف ثاني، أي أن الآية التي جاء بها حرف الألف المدية قد وقعت بالموضع الثاني الذي جاء به حرف الألف المدية كذلك، وأيضا اربط بين واو "خلوا" وواو أول، أي أن الآية التي جاء بها "خلوا" وجاء بها حرف الواو قد وقعت بالموضع الأول الذي جاء به حرف الواو كذلك.','٧٦ واذا لقوا۟ ٱلذين ءامنوا۟ قالوٓا۟ ءامنا واذا خلا بعضهم الي بعض قالوٓا۟ اتحدثونهم ثاني البقره ٧٦ واذا لقوا۟ ٱلذين ءامنوا۟ قالوٓا۟ ءامنا واذا خلوا۟ الي شيطينهم قالوٓا۟ انا معكم انما نحن مستهزءون اول البقره ١٤ اربط بين الف خلا والف ثاني، اي ان الايه التي جاء بها حرف الالف المديه قد وقعت بالموضع الثاني الذي جاء به حرف الالف المديه كذلك، وايضا اربط بين واو خلوا وواو اول، اي ان الايه التي جاء بها خلوا وجاء بها حرف الواو قد وقعت بالموضع الاول الذي جاء به حرف الواو كذلك',1);
INSERT INTO `mawadi3` (`mawdi_id`,`mawdi_number`,`surah_id`,`reference_text`,`start_page`,`end_page`,`plain_text`,`html_text`,`normalized_text`,`is_closed`) VALUES (67,76,NULL,NULL,11,11,'
[٧٦] ﴿ ... قَالُوٓا۟ أَتُحَدِّثُونَهُم بِمَا فَتَحَ ٱللَّهُ عَلَيْكُمْ لِيُحَاجُّوكُم بِهِۦ عِندَ رَبِّكُمْ ۚ أَفَلَا تَعْقِلُونَ ﴾ [البقرة : ٧٦]
﴿ ... أَن يُؤْتَىٰٓ أَحَدٌ مِّثْلَ مَآ أُوتِيتُمْ أَوْ يُحَاجُّوكُمْ عِندَ رَبِّكُمْ ۗ قُلْ إِنَّ ٱلْفَضْلَ بِيَدِ ٱللَّهِ ... ﴾ [آل عمران : ٧٣]
جاءت "به" زائدة في سورة البقرة، ويمكن ربط "به" باسم السورة فإن حرف الباء مشترك بينهما، أي أن "به" التي جاء بها حرف الباء قد جاءت بالسورة التي جاء في اسمها حرف الباء -البقرة-.','
[٧٦] ﴿ ... قَالُوٓا۟ أَتُحَدِّثُونَهُم بِمَا فَتَحَ ٱللَّهُ عَلَيْكُمْ لِيُحَاجُّوكُم <span style="color:red">بِهِۦ</span> عِندَ رَبِّكُمْ ۚ أَفَلَا تَعْقِلُونَ ﴾ [البقرة : ٧٦]
﴿ ... أَن يُؤْتَىٰٓ أَحَدٌ مِّثْلَ مَآ أُوتِيتُمْ أَوْ يُحَاجُّوكُمْ عِندَ رَبِّكُمْ ۗ قُلْ إِنَّ ٱلْفَضْلَ بِيَدِ ٱللَّهِ ... ﴾ [آل عمران : ٧٣]
جاءت "به" زائدة في سورة البقرة، ويمكن ربط "به" باسم السورة فإن حرف الباء مشترك بينهما، أي أن "به" التي جاء بها حرف الباء قد جاءت بالسورة التي جاء في اسمها حرف الباء -البقرة-.','٧٦ قالوٓا۟ اتحدثونهم بما فتح ٱلله عليكم ليحاجوكم بهۦ عند ربكم ۚ افلا تعقلون البقره ٧٦ ان يؤتيٓ احد مثل مآ اوتيتم او يحاجوكم عند ربكم ۗ قل ان ٱلفضل بيد ٱلله ال عمران ٧٣ جاءت به زائده في سوره البقره، ويمكن ربط به باسم السوره فان حرف الباء مشترك بينهما، اي ان به التي جاء بها حرف الباء قد جاءت بالسوره التي جاء في اسمها حرف الباء البقره',1);
INSERT INTO `mawadi3` (`mawdi_id`,`mawdi_number`,`surah_id`,`reference_text`,`start_page`,`end_page`,`plain_text`,`html_text`,`normalized_text`,`is_closed`) VALUES (68,78,NULL,NULL,11,11,'
[٧٨] ﴿ إِنْ هُمْ إِلَّا يَظُنُّونَ ﴾ تكررت مرتين: [البقرة : ٧٨، الجاثية : ٢٤] ليس في القرآن غيرهما وباقي المواضع ﴿ إِنْ هُمْ إِلَّا يَخْرُصُونَ ﴾ [الأنعام : ١١٦، يونس : ٦٦، الزخرف : ٢٠]','
[٧٨] ﴿ إِنْ هُمْ إِلَّا <span style="color:red">يَظُنُّونَ</span> ﴾ تكررت مرتين: [البقرة : ٧٨، الجاثية : ٢٤] ليس في القرآن غيرهما وباقي المواضع ﴿ إِنْ هُمْ إِلَّا <span style="color:red">يَخْرُصُونَ</span> ﴾ [الأنعام : ١١٦، يونس : ٦٦، الزخرف : ٢٠]','٧٨ ان هم الا يظنون تكررت مرتين البقره ٧٨، الجاثيه ٢٤ ليس في القران غيرهما وباقي المواضع ان هم الا يخرصون الانعام ١١٦، يونس ٦٦، الزخرف ٢٠',1);
INSERT INTO `mawadi3` (`mawdi_id`,`mawdi_number`,`surah_id`,`reference_text`,`start_page`,`end_page`,`plain_text`,`html_text`,`normalized_text`,`is_closed`) VALUES (69,80,NULL,NULL,11,11,'
[٨٠] ﴿ وَقَالُوا۟ لَن تَمَسَّنَا ٱلنَّارُ إِلَّآ أَيَّامًا مَّعْدُودَةً ۚ قُلْ أَتَّخَذْتُمْ ... ﴾ [أول البقرة : ٨٠]
﴿ ذَٰلِكَ بِأَنَّهُمْ قَالُوا۟ لَن تَمَسَّنَا ٱلنَّارُ إِلَّآ أَيَّامًا مَّعْدُودَٰتٍ ۖ وَغَرَّهُمْ فِي دِينِهِم ... ﴾ [آل عمران : ٢٤]
﴿ أَيَّامًا مَّعْدُودَٰتٍ ۚ فَمَن كَانَ مِنكُم ... ﴾ [ثاني البقرة : ١٨٤]
﴿ وَٱذْكُرُوا۟ ٱللَّهَ فِي أَيَّامٍ مَّعْدُودَٰتٍ ... ﴾ [ثالث البقرة : ٢٠٣]
﴿ لِّيَشْهَدُوا۟ مَنَٰفِعَ لَهُمْ وَيَذْكُرُوا۟ ٱسْمَ ٱللَّهِ فِي أَيَّامٍ مَّعْلُومَٰتٍ عَلَىٰ مَا رَزَقَهُم ... ﴾ [الحج : ٢٨]
ملحوظة: آية البقرة الأولى الوحيدة "أيامًا معدودة" وباقي المواضع "معدودات"، وآية الحج الوحيدة "معلومات".','
[٨٠] ﴿ وَقَالُوا۟ لَن تَمَسَّنَا ٱلنَّارُ إِلَّآ أَيَّامًا <span style="color:red">مَّعْدُودَةً</span> ۚ قُلْ <span style="color:red">أَتَّخَذْتُمْ</span> ... ﴾ [أول البقرة : ٨٠]
﴿ ذَٰلِكَ بِأَنَّهُمْ قَالُوا۟ لَن تَمَسَّنَا ٱلنَّارُ إِلَّآ أَيَّامًا <span style="color:red"><span style="color:red"><span style="color:red">مَّعْدُودَٰتٍ</span></span></span> ۖ <span style="color:red">وَغَرَّهُمْ فِي دِينِهِم</span> ... ﴾ [آل عمران : ٢٤]
﴿ أَيَّامًا <span style="color:red"><span style="color:red"><span style="color:red">مَّعْدُودَٰتٍ</span></span></span> ۚ فَمَن كَانَ مِنكُم ... ﴾ [ثاني البقرة : ١٨٤]
﴿ وَٱذْكُرُوا۟ ٱللَّهَ فِي أَيَّامٍ <span style="color:red"><span style="color:red"><span style="color:red">مَّعْدُودَٰتٍ</span></span></span> ... ﴾ [ثالث البقرة : ٢٠٣]
﴿ لِّيَشْهَدُوا۟ مَنَٰفِعَ لَهُمْ وَيَذْكُرُوا۟ ٱسْمَ ٱللَّهِ فِي أَيَّامٍ <span style="color:red">مَّعْلُومَٰتٍ</span> عَلَىٰ مَا رَزَقَهُم ... ﴾ [الحج : ٢٨]
ملحوظة: آية البقرة الأولى الوحيدة "أيامًا معدودة" وباقي المواضع "معدودات"، وآية الحج الوحيدة "معلومات".','٨٠ وقالوا۟ لن تمسنا ٱلنار الآ اياما معدوده ۚ قل اتخذتم اول البقره ٨٠ ذلك بانهم قالوا۟ لن تمسنا ٱلنار الآ اياما معدودت ۖ وغرهم في دينهم ال عمران ٢٤ اياما معدودت ۚ فمن كان منكم ثاني البقره ١٨٤ وٱذكروا۟ ٱلله في ايام معدودت ثالث البقره ٢٠٣ ليشهدوا۟ منفع لهم ويذكروا۟ ٱسم ٱلله في ايام معلومت علي ما رزقهم الحج ٢٨ ملحوظه ايه البقره الاولي الوحيده اياما معدوده وباقي المواضع معدودات، وايه الحج الوحيده معلومات',1);
